import { expect, test } from '@playwright/test';
import {
  TOY_OKAMOTO_PARAMS,
  enumerateTranscripts,
  gqCheatAttempt,
  gqExtract,
  gqProve,
  gqVerify,
  okamotoExtract,
  okamotoProve,
  okamotoVerify,
  transcriptMultisetsEqual,
} from '../js/sigma.js';

/**
 * Fast, named owners for Exhibit 07's six rendered verdicts. The replayable
 * mutation runner invokes one at a time with --retries=0. Browser claims still
 * exercise the DOM; these small arithmetic fixtures make each mutation fail
 * immediately instead of waiting on RSA generation or a UI timeout.
 */

test('mutation oracle · Okamoto verification keeps the h term', () => {
  const proof = okamotoProve(
    TOY_OKAMOTO_PARAMS,
    { alpha: 5n, beta: 7n },
    { alpha: 3n, beta: 8n },
    11n,
  );
  const result = okamotoVerify(TOY_OKAMOTO_PARAMS, proof);
  expect(result.ok).toBe(true);
  expect(result.lhs).toBe(result.rhs);
});

test('mutation oracle · Okamoto extraction keeps delta-c sign', () => {
  const witness = { alpha: 5n, beta: 7n };
  const nonce = { alpha: 3n, beta: 8n };
  const first = okamotoProve(TOY_OKAMOTO_PARAMS, witness, nonce, 4n);
  const second = okamotoProve(TOY_OKAMOTO_PARAMS, witness, nonce, 11n);
  const extracted = okamotoExtract(TOY_OKAMOTO_PARAMS, first, second);
  expect(extracted.ok).toBe(true);
  expect(extracted.alpha).toBe(witness.alpha);
  expect(extracted.beta).toBe(witness.beta);
});

test('mutation oracle · transcript multiset comparison checks entries', () => {
  const first = enumerateTranscripts({ alpha: 5n, beta: 7n }, 'fixed-nonce');
  const second = enumerateTranscripts({ alpha: 9n, beta: 8n }, 'fixed-nonce');
  expect(first).toHaveLength(second.length);
  expect(transcriptMultisetsEqual(first, second)).toBe(false);
});

test('mutation oracle · GQ verification keeps y-to-c', () => {
  const params = { N: 55n, e: 3n };
  const proof = gqProve(params, 2n, 1n, 3n);
  const result = gqVerify(params, proof);
  expect(result.ok).toBe(true);
  expect(result.lhs).toBe(result.rhs);
});

test("mutation oracle · Shamir's trick uses s on y", () => {
  const params = { N: 55n, e: 3n };
  const first = gqProve(params, 2n, 0n, 3n);
  const second = gqProve(params, 2n, 1n, 3n);
  const extracted = gqExtract(params, first, second);
  expect(extracted.ok).toBe(true);
  expect(extracted.root).toBe(2n);
  expect(extracted.check).toBe(first.y);
});

test('mutation oracle · GQ cheater is checked against verifier c', () => {
  const y = 8n; // 2^3 mod 55; cubing is bijective because gcd(3, phi(55)) = 1.
  let accepted = 0;
  for (let trial = 0; trial < 300; trial += 1) {
    const attempt = gqCheatAttempt(y, 3n, 55n);
    expect(attempt.accepted).toBe(attempt.verifierChallenge === attempt.guessedChallenge);
    if (attempt.accepted) accepted += 1;
  }
  expect(accepted).toBeGreaterThan(50);
  expect(accepted).toBeLessThan(150);
});

import { expect, test } from '@playwright/test';
import { createField, scriptedChallengeSource, seededChallengeSource } from '../js/field.js';
import { evaluatePolynomial, parsePolynomial } from '../js/polynomial.js';
import {
  createSumcheckProver,
  createSumcheckSession,
  createSumcheckVerifier,
  replaySumcheckTranscript,
} from '../js/sumcheck.js';
import { DEMO_CIRCUIT, createGkrProver, createGkrVerifier, runGkr } from '../js/gkr.js';

/**
 * Fast, named owners for Exhibit 08's nine source mutations. The replayable
 * mutation runner invokes one at a time with --retries=0 and requires the kill
 * to be an assertion in exactly this test. Each fixture is scripted or seeded,
 * so the verdict a mutation changes is deterministic.
 */

const field = createField(2147483647n);
const g = parsePolynomial(field, '2*x1^3 + x1*x3 + x2*x3');
const oracle = (point: bigint[]) => evaluatePolynomial(field, g, point);
/** r0; four layer-0 sum-check coins; r*; four layer-1 coins; r*. */
const fullGkrChallenges = [2n, 3n, 5n, 7n, 9n, 10n, 4n, 6n, 8n, 11n, 15n];

test('mutation oracle · sum-check verifier enforces the recurrence', () => {
  const prover = createSumcheckProver({ field, polynomial: g, strategy: { kind: 'wrong-sum-naive', offset: 1n } });
  const session = createSumcheckSession({ field, polynomial: g, prover, challengeSource: scriptedChallengeSource(field, [7n, 8n, 9n]) });
  const verdict = session.run();
  expect(verdict.accepted).toBe(false);
  expect(verdict.failedCheck).toBe('recurrence');
  expect(verdict.reason).toBe('round 1: s1(0) + s1(1) = 12 but the verifier expected 13 (the claimed sum)');
});

test('mutation oracle · sum-check verifier enforces the degree bound', () => {
  const prover = createSumcheckProver({ field, polynomial: g, strategy: { kind: 'excessive-degree', round: 2 } });
  const session = createSumcheckSession({ field, polynomial: g, prover, challengeSource: scriptedChallengeSource(field, [7n, 8n, 9n]) });
  const verdict = session.run();
  expect(verdict.accepted).toBe(false);
  expect(verdict.failedCheck).toBe('degree');
  expect(verdict.reason).toBe('round 2: the message has degree 3 but the degree bound for X2 is 1');
});

test('mutation oracle · sum-check verifier rejects a false final evaluation', () => {
  // Challenges 7, 8, 9 miss every root the carried lie can hide behind (2, 3, 4 in round 1; 2 in rounds 2 and 3).
  const prover = createSumcheckProver({ field, polynomial: g, strategy: { kind: 'wrong-sum-carried', offset: 5n } });
  const session = createSumcheckSession({ field, polynomial: g, prover, challengeSource: scriptedChallengeSource(field, [7n, 8n, 9n]) });
  const verdict = session.run();
  expect(session.verifier.checks().every((check) => check.ok)).toBe(true);
  expect(verdict.accepted).toBe(false);
  expect(verdict.failedCheck).toBe('final');
  const final = session.verifier.final();
  expect(final?.ok).toBe(false);
  expect(final?.evaluated).toBe(oracle(final!.point));
  expect(final?.claimed).not.toBe(final?.evaluated);
});

test('mutation oracle · GKR verifier evaluates the wiring it derived itself', () => {
  const inputs = [3n, 2n, 3n, 1n];
  const run = runGkr({ field, circuit: DEMO_CIRCUIT, inputs, prover: createGkrProver({ field, circuit: DEMO_CIRCUIT, inputs }), challengeSource: seededChallengeSource(field, 'mutation-wiring') });
  expect(run.accepted).toBe(true);
  expect(run.failedAt).toBeNull();
  expect(run.transcript.layers.map((layer) => layer.final?.ok)).toEqual([true, true]);
  expect(run.transcript.terminal?.ok).toBe(true);
});

test('mutation oracle · GKR verifier enforces the line-polynomial degree bound', () => {
  const inputs = [3n, 2n, 3n, 1n];
  const run = runGkr({
    field,
    circuit: DEMO_CIRCUIT,
    inputs,
    prover: createGkrProver({ field, circuit: DEMO_CIRCUIT, inputs, strategy: { kind: 'invalid-line', layer: 0, mode: 'degree' } }),
    // Keep enough verifier coins for the mutated guard to run through the
    // later semantic checks; source exhaustion must never masquerade as a kill.
    challengeSource: scriptedChallengeSource(field, fullGkrChallenges),
  });
  expect(run.accepted).toBe(false);
  expect(run.failedAt).toEqual({ stage: 'line-degree', layer: 0 });
  expect(run.reason).toBe('layer 0 line: q has degree 3 but W̃1 restricted to a line has degree at most 2');
});

test('mutation oracle · GKR terminal check is anchored to the public inputs', () => {
  const inputs = [3n, 2n, 3n, 1n];
  const challenges = [2n, 3n, 5n, 7n, 9n, 10n, 4n, 6n, 8n, 11n, 15n];
  const run = runGkr({
    field,
    circuit: DEMO_CIRCUIT,
    inputs,
    prover: createGkrProver({ field, circuit: DEMO_CIRCUIT, inputs, strategy: { kind: 'invalid-line', layer: 1, mode: 'value', offset: 1n } }),
    challengeSource: scriptedChallengeSource(field, challenges),
  });
  expect(run.accepted).toBe(false);
  expect(run.failedAt).toEqual({ stage: 'terminal', layer: 2 });
  expect(run.transcript.terminal?.ok).toBe(false);
  expect(run.transcript.terminal?.claim).not.toBe(run.transcript.terminal?.evaluated);
});

test('mutation oracle · GKR refuses verifier challenges outside its field', () => {
  const invalidSource = {
    kind: 'scripted' as const,
    label: 'invalid mutation fixture',
    draw: () => field.p,
  };
  const verifier = createGkrVerifier({
    field,
    circuit: DEMO_CIRCUIT,
    inputs: [3n, 2n, 3n, 1n],
    challengeSource: invalidSource,
  });
  // Exercise GKR's own r0 guard directly. If that guard is removed, this call
  // succeeds; a downstream sum-check guard cannot accidentally kill the mutant.
  expect(() => verifier.receiveOutputs([18n, 4n])).toThrow('the challenge source returned a value outside the field');
});

test('mutation oracle · a challenge cannot be drawn before its prover message', () => {
  const verifier = createSumcheckVerifier({ field, degreeBounds: [3, 1, 1], claimedSum: 12n, challengeSource: scriptedChallengeSource(field, [2n, 3n, 6n]) });
  expect(verifier.receiveMessage([1n, 2n, 0n, 8n]).ok).toBe(true);
  expect(verifier.drawChallenge()).toBe(2n);
  // Round 2's message has not arrived: drawing its challenge now must be refused, not silently redraw round 1's.
  expect(() => verifier.drawChallenge()).toThrow('cannot be drawn before the prover\'s round-2 message');
  expect(verifier.transcript().rounds[0].challenge).toBe(2n);
  const fresh = createSumcheckVerifier({ field, degreeBounds: [3, 1, 1], claimedSum: 12n, challengeSource: scriptedChallengeSource(field, [2n]) });
  expect(() => fresh.drawChallenge()).toThrow('cannot be drawn before the prover\'s round-1 message');
});

test('mutation oracle · transcript replay refuses a truncated transcript', () => {
  const session = createSumcheckSession({ field, polynomial: g, prover: createSumcheckProver({ field, polynomial: g }), challengeSource: scriptedChallengeSource(field, [2n, 3n, 6n]) });
  session.run();
  const transcript = session.verifier.transcript();
  const truncated = { ...transcript, rounds: transcript.rounds.slice(0, 2) };
  let outcome: ReturnType<typeof replaySumcheckTranscript> | undefined;
  expect(() => {
    outcome = replaySumcheckTranscript({ field, transcript: truncated, oracle, expectedDegreeBounds: [3, 1, 1] });
  }).not.toThrow();
  expect(outcome?.ok).toBe(false);
  expect(outcome?.reason).toBe('malformed transcript: 2 rounds recorded but the statement has 3 variables');
});

/** Only an assertion in the exact owning test can kill a source mutation. */
export function assertNormalExit(result, label) {
  if (result.error || result.signal || !Number.isInteger(result.status)) {
    throw new Error(`${label}: process did not exit normally (${result.error?.message ?? result.signal ?? 'no exit status'})`);
  }
}

export function validateNamedRun(result, owner, shouldPass, expectedFile = 'claims.spec.ts') {
  assertNormalExit(result, owner);
  let report;
  try {
    report = JSON.parse(result.stdout);
  } catch {
    throw new Error(`${owner}: missing or invalid Playwright JSON report`);
  }
  if (!Array.isArray(report.errors) || report.errors.length) {
    throw new Error(`${owner}: runner errors cannot count as a mutation kill`);
  }
  const specs = [];
  function visit(suite) {
    specs.push(...(suite.specs ?? []));
    for (const child of suite.suites ?? []) visit(child);
  }
  for (const suite of report.suites ?? []) visit(suite);
  // Playwright's JSON locations are relative to testDir (e2e/).
  if (specs.length !== 1 || !specs[0].title.includes(owner) || specs[0].file !== expectedFile) {
    throw new Error(`${owner}: expected exactly the named owning test`);
  }
  const tests = specs[0].tests ?? [];
  if (tests.length !== 1 || tests[0].expectedStatus !== 'passed' || tests[0].results?.length !== 1) {
    throw new Error(`${owner}: skipped, expected-failure, repeated, or retried tests are invalid`);
  }
  const observed = tests[0].results[0];
  const expectedStatus = shouldPass ? 'passed' : 'failed';
  if (observed.status !== expectedStatus || observed.retry !== 0 || result.status !== (shouldPass ? 0 : 1)) {
    throw new Error(`${owner}: expected ${expectedStatus}, observed ${observed.status}, exit ${result.status}`);
  }
  const errors = observed.errors ?? (observed.error ? [observed.error] : []);
  if (shouldPass) {
    if (errors.length) throw new Error(`${owner}: passing test reported errors`);
    return;
  }
  if (errors.length !== 1) throw new Error(`${owner}: expected exactly one owning assertion failure`);
  const failure = [observed.error?.message, observed.error?.stack, errors[0].message, errors[0].stack].filter(Boolean).join('\n');
  if (!/expect\(|AssertionError/.test(failure) || !/spec\.ts:\d+:\d+/.test(failure) ||
      /No tests found|browserType\.launch|browser has been closed|Target (?:page|browser|context).*closed|net::ERR_|Test timeout of|page\.goto:|locator\.(?:click|check|uncheck):|waiting for.*web server|at (?:boot|solveBob)\b|page must raise no uncaught exceptions/i.test(failure)) {
    throw new Error(`${owner}: infrastructure, setup, runtime, or non-assertion failure cannot count as a mutation kill`);
  }
}

export function validateUnitRun(result, owner, file, shouldPass) {
  assertNormalExit(result, owner);
  const report = JSON.parse(result.stdout);
  const suites = report.testResults ?? [];
  const assertions = suites.flatMap(s => (s.assertionResults ?? []).filter(a => a.status !== 'skipped').map(a => ({...a,file:s.name})));
  if (assertions.length !== 1 || !assertions[0].title.includes(owner) || !assertions[0].file.endsWith(file) ||
      assertions[0].status !== (shouldPass ? 'passed' : 'failed') || result.status !== (shouldPass ? 0 : 1) ||
      report.numPassedTests !== (shouldPass ? 1 : 0) || report.numFailedTests !== (shouldPass ? 0 : 1)) throw Error(`${owner}: expected exactly the owning unit test`);
  const failures = assertions[0].failureMessages ?? [];
  if (shouldPass ? failures.length : failures.length !== 1 || !/AssertionError|expected .*to/i.test(failures[0])) throw Error(`${owner}: expected an owning assertion failure`);
}

// Fifteen concrete, replayable patches: six own Exhibit 07's rendered verdicts
// (js/sigma.js) and nine own Exhibit 08's sum-check and GKR checks (js/sumcheck.js,
// js/gkr.js). Every run proves the five §4.1c observations and restores the
// source in a finally block. Run from the repository root with
// `npm run test:mutations`, or name one mutation as the first argument.
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { assertNormalExit,validateNamedRun } from './mutation-report.mjs';

const SIGMA = { source: 'js/sigma.js', spec: 'e2e/sigma-mutations.spec.ts' };
const SUMCHECK = { source: 'js/sumcheck.js', spec: 'e2e/sumcheck-mutations.spec.ts' };
const GKR = { source: 'js/gkr.js', spec: 'e2e/sumcheck-mutations.spec.ts' };

const mutations = [
  {
    ...SIGMA,
    name: 'Okamoto verifier h term',
    anchor: 'const lhs = modpowBig(params.g, transcript.zAlpha, params.p) * modpowBig(params.h, transcript.zBeta, params.p) % params.p;',
    replacement: 'const lhs = modpowBig(params.g, transcript.zAlpha, params.p) * 1n % params.p;',
    test: 'mutation oracle · Okamoto verification keeps the h term',
  },
  {
    ...SIGMA,
    name: 'Okamoto extraction challenge sign',
    anchor: 'const deltaC = modulo(first.c - second.c, params.q);',
    replacement: 'const deltaC = modulo(second.c - first.c, params.q);',
    test: 'mutation oracle · Okamoto extraction keeps delta-c sign',
  },
  {
    ...SIGMA,
    name: 'transcript multiset entries',
    anchor: 'return left.length === right.length && left.every((entry, index) => entry === right[index]);',
    replacement: 'return left.length === right.length;',
    test: 'mutation oracle · transcript multiset comparison checks entries',
  },
  {
    ...SIGMA,
    name: 'GQ verifier y-to-c term',
    anchor: 'const rhs = transcript.yT * modpowBig(transcript.y, transcript.c, params.N) % params.N;',
    replacement: 'const rhs = transcript.yT;',
    test: 'mutation oracle · GQ verification keeps y-to-c',
  },
  {
    ...SIGMA,
    name: "Shamir extraction coefficient",
    anchor: 'const root = powSigned(first.y, coefficients.x, params.N) * powSigned(deltaX, coefficients.y, params.N) % params.N;',
    replacement: 'const root = powSigned(first.y, coefficients.y, params.N) * powSigned(deltaX, coefficients.y, params.N) % params.N;',
    test: "mutation oracle · Shamir's trick uses s on y",
  },
  {
    ...SIGMA,
    name: 'GQ cheater verifier challenge',
    anchor: 'const transcript = { y, yT: forged.yT, c: verifierChallenge, xZ: forged.xZ };',
    replacement: 'const transcript = { y, yT: forged.yT, c: forged.guessedChallenge, xZ: forged.xZ };',
    test: 'mutation oracle · GQ cheater is checked against verifier c',
  },
  {
    ...SUMCHECK,
    name: 'sum-check recurrence enforcement',
    anchor: "} else if (sumAt01 !== expected) {",
    replacement: "} else if (sumAt01 !== sumAt01) {",
    test: 'mutation oracle · sum-check verifier enforces the recurrence',
  },
  {
    ...SUMCHECK,
    name: 'sum-check degree enforcement',
    anchor: 'if (degree > bound) {',
    replacement: 'if (degree > bound + 1000) {',
    test: 'mutation oracle · sum-check verifier enforces the degree bound',
  },
  {
    ...SUMCHECK,
    name: 'sum-check final evaluation',
    anchor: 'const ok = evaluated === expected;',
    replacement: 'const ok = evaluated === evaluated;',
    test: 'mutation oracle · sum-check verifier rejects a false final evaluation',
  },
  {
    ...GKR,
    name: 'GKR verifier wiring evaluation',
    anchor: 'total = field.add(total, field.mul(field.mul(chi(field, a, here, z), chi(field, in1, below, b)), chi(field, in2, below, c)));',
    replacement: 'total = field.add(total, field.mul(field.mul(chi(field, a, here, z), chi(field, in2, below, b)), chi(field, in1, below, c)));',
    test: 'mutation oracle · GKR verifier evaluates the wiring it derived itself',
  },
  {
    ...GKR,
    name: 'GKR line-polynomial degree enforcement',
    anchor: 'if (degree > bound) {',
    replacement: 'if (degree > bound + 1000) {',
    test: 'mutation oracle · GKR verifier enforces the line-polynomial degree bound',
  },
  {
    ...GKR,
    name: 'GKR terminal public-input check',
    anchor: 'const ok = evaluated === claim;',
    replacement: 'const ok = evaluated === evaluated;',
    test: 'mutation oracle · GKR terminal check is anchored to the public inputs',
  },
  {
    ...GKR,
    name: 'GKR canonical verifier challenge',
    anchor: "if (!field.isCanonical(challenge)) throw new RangeError('the challenge source returned a value outside the field');",
    replacement: "if (false) throw new RangeError('the challenge source returned a value outside the field');",
    test: 'mutation oracle · GKR refuses verifier challenges outside its field',
  },
  {
    ...SUMCHECK,
    name: 'sum-check challenge ordering guard',
    anchor: "if (phase !== 'await-challenge') {\n        throw new Error(`protocol order: the round-${round} challenge cannot be drawn",
    replacement: "if (phase !== 'await-challenge' && phase !== 'await-message') {\n        throw new Error(`protocol order: the round-${round} challenge cannot be drawn",
    test: 'mutation oracle · a challenge cannot be drawn before its prover message',
  },
  {
    ...SUMCHECK,
    name: 'sum-check replay round count',
    anchor: 'if (rounds.length !== variables) {',
    replacement: 'if (rounds.length > variables) {',
    test: 'mutation oracle · transcript replay refuses a truncated transcript',
  },
];

function run(command, args, timeout = 300_000) {
  const result = spawnSync(command, args, {
    encoding: 'utf8',
    env: { ...process.env, CI: '1' },
    maxBuffer: 16 * 1024 * 1024,
    timeout,
  });
  assertNormalExit(result, command);
  return {
    ...result,
    code: result.status,
    output: `${result.stdout ?? ''}${result.stderr ?? ''}`,
  };
}

function build() {
  const result = run('npm', ['run', 'build'], 120_000);
  if (result.code !== 0) throw new Error(`Build failed:\n${result.output}`);
}

function bundleHash() {
  const files = readdirSync('dist/assets').filter((file) => file.endsWith('.js')).sort();
  if (files.length === 0) throw new Error('Build produced no JavaScript bundles.');
  const hash = createHash('sha256');
  for (const file of files) hash.update(file).update(readFileSync(`dist/assets/${file}`));
  return hash.digest('hex');
}

function namedTest(spec, testName, shouldPass) {
  const result = run('npx', [
    'playwright',
    'test',
    spec,
    '--grep',
    testName,
    '--retries=0',
    '--workers=1',
    '--reporter=json',
  ]);
  validateNamedRun(result, testName, shouldPass, spec.replace(/^e2e\//, ''));
  return result;
}

function sourceDiff(source) {
  return run('git', ['diff', '--no-ext-diff', '--', source], 30_000);
}

const selectedName = process.argv[2];
const selected = selectedName ? mutations.filter(({ name }) => name === selectedName) : mutations;
if (selected.length === 0) throw new Error(`Unknown mutation: ${selectedName}`);

if (run('git',['status','--porcelain']).output.trim()) throw Error('Commit source changes before replaying mutations');
const records = [];
for (const mutation of selected) {
  const source = readFileSync(mutation.source, 'utf8');
  if (source.split(mutation.anchor).length !== 2) {
    throw new Error(`${mutation.name}: source anchor must occur exactly once.`);
  }

  build();
  const baselineHash = bundleHash();
  const baseline = namedTest(mutation.spec, mutation.test, true);
  if (baseline.code !== 0) throw new Error(`${mutation.name}: baseline failed.\n${baseline.output}`);
  console.log(`[${mutation.name}] 1/5 baseline passes: ${mutation.test}`);

  let mutatedHash;
  try {
    const changed = source.replace(mutation.anchor, mutation.replacement);
    if (changed === source) throw new Error(`${mutation.name}: mutation was empty.`);
    writeFileSync(mutation.source, changed);

    const diff = sourceDiff(mutation.source);
    if (diff.code !== 0 || diff.output.trim() === '') {
      throw new Error(`${mutation.name}: source diff was empty.\n${diff.output}`);
    }
    console.log(`[${mutation.name}] 2/5 source diff NON-EMPTY`);

    build();
    mutatedHash = bundleHash();
    if (mutatedHash === baselineHash) throw new Error(`${mutation.name}: bundle hash did not move.`);
    console.log(`[${mutation.name}] 3/5 bundle hash MOVED: ${baselineHash} -> ${mutatedHash}`);

    const observed = namedTest(mutation.spec, mutation.test, false);
    if (observed.code === 0) throw new Error(`${mutation.name}: mutation survived.`);
    if (!observed.output.includes(mutation.test)) {
      throw new Error(`${mutation.name}: red output did not name its owning test.\n${observed.output}`);
    }
    if (/Process from config\.webServer|ERR_CONNECTION_REFUSED|Cannot find module|No tests found/.test(observed.output)) {
      throw new Error(`${mutation.name}: infrastructure failure is not a kill.\n${observed.output}`);
    }
    console.log(`[${mutation.name}] 4/5 NAMED test red: ${mutation.test}`);
  } finally {
    writeFileSync(mutation.source, source);
    build();
  }

  if (bundleHash() !== baselineHash) throw new Error(`${mutation.name}: restored bundle differs.`);
  const restored = namedTest(mutation.spec, mutation.test, true);
  if (restored.code !== 0) throw new Error(`${mutation.name}: restored control failed.\n${restored.output}`);
  console.log(`[${mutation.name}] 5/5 restored and green`);
  records.push({ ...mutation, baselineHash, mutatedHash, killed: true, restored: true });
}

console.log(`${records.length} of ${selected.length} concrete mutations killed, with passing controls.`);

#!/usr/bin/env node
/**
 * Focused PR-10 mutation checks.
 *
 * Every case runs in a disposable copy so an interruption cannot leave the
 * source tree mutated. A kill counts only when the unmutated suite passed and
 * the owning assertion is visible in the failed run.
 */
import { cpSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const scratch = mkdtempSync(join(tmpdir(), 'stark-tower-pr10-mutations-'));

const mutations = [
  {
    name: 'heuristic label removed',
    file: 'index.html',
    before: 'capacity-model query bits (heuristic)',
    after: 'soundness bits',
    owningFailure: 'capacity arithmetic is visibly classified as heuristic',
  },
  {
    name: 'CL146 query term replaced by capacity arithmetic',
    file: 'src/soundness.ts',
    before: 'Math.pow(1 - Math.min(evidence.theta!, evidence.distance!), queries)',
    after: 'Math.pow(rate, queries)',
    owningFailure: 'FAIL  soundness: CL146 conditional query formula uses min(theta, delta)',
  },
  {
    name: 'missing fold error silently accepted',
    file: 'src/soundness.ts',
    before: 'evidence.foldMcaErrors.length === folds',
    after: 'evidence.foldMcaErrors.length >= 0',
    owningFailure: 'FAIL  soundness: one of two fold errors is incomplete, not zero',
  },
  {
    name: 'final-code membership becomes the whole verdict',
    file: 'src/stark.ts',
    before: 'const accepted = checks.every((c) => c.ok);',
    after: 'const accepted = finalConstant;',
    owningFailure: 'FAIL  final membership alone cannot accept a proof',
  },
];

function disposableCopy(label) {
  const destination = join(scratch, label);
  cpSync(root, destination, {
    recursive: true,
    filter(source) {
      const path = relative(root, source);
      return !(
        path === '.git' || path.startsWith(`.git${process.platform === 'win32' ? '\\' : '/'}`) ||
        path === 'node_modules' || path.startsWith(`node_modules${process.platform === 'win32' ? '\\' : '/'}`) ||
        path === 'dist' || path.startsWith(`dist${process.platform === 'win32' ? '\\' : '/'}`) ||
        path === 'test-results' || path.startsWith(`test-results${process.platform === 'win32' ? '\\' : '/'}`) ||
        path === 'playwright-report' || path.startsWith(`playwright-report${process.platform === 'win32' ? '\\' : '/'}`) ||
        path === 'scripts/selftest_bundle.mjs' || path === 'scripts/app_bundle.mjs'
      );
    },
  });
  symlinkSync(join(root, 'node_modules'), join(destination, 'node_modules'), 'dir');
  return destination;
}

function runSuite(cwd) {
  return spawnSync(process.execPath, ['scripts/test.mjs'], {
    cwd,
    encoding: 'utf8',
    env: { ...process.env, CI: '1', FORCE_COLOR: '0' },
    maxBuffer: 20 * 1024 * 1024,
    timeout: 120_000,
  });
}

function output(result) {
  return `${result.stdout ?? ''}${result.stderr ?? ''}`;
}

function replaceExactlyOnce(cwd, mutation) {
  const path = join(cwd, mutation.file);
  const source = readFileSync(path, 'utf8');
  const count = source.split(mutation.before).length - 1;
  if (count !== 1) throw new Error(`${mutation.name}: expected one anchor in ${mutation.file}, found ${count}`);
  writeFileSync(path, source.replace(mutation.before, mutation.after));
}

try {
  const baselineRoot = disposableCopy('baseline');
  const baseline = runSuite(baselineRoot);
  if (baseline.status !== 0 || baseline.signal) {
    throw new Error(`baseline failed or timed out\n${output(baseline)}`);
  }
  console.log('baseline: unmutated copy PASSES');

  for (let i = 0; i < mutations.length; i += 1) {
    const mutation = mutations[i];
    const mutationRoot = disposableCopy(`mutation-${i + 1}`);
    replaceExactlyOnce(mutationRoot, mutation);
    const result = runSuite(mutationRoot);
    const transcript = output(result);
    if (result.status === 0 || result.signal) {
      throw new Error(`${mutation.name}: mutation survived or timed out\n${transcript}`);
    }
    if (!transcript.includes(mutation.owningFailure)) {
      throw new Error(`${mutation.name}: suite failed, but not at its owning assertion\n${transcript}`);
    }
    console.log(`caught ${i + 1}/${mutations.length}: ${mutation.name}`);
  }

  console.log(`all ${mutations.length} mutation(s) caught`);
} finally {
  rmSync(scratch, { recursive: true, force: true });
}

#!/usr/bin/env node

/** Focused mutation gate for the repaired XOR proof relation. */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { lstat, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const TEST_TITLE = 'actual weak relation proves the explicit phantom output and repaired relation rejects it';
const CONSTRAINTS = '    a * (a - 1) === 0;\n    b * (b - 1) === 0;';
const MUTANT =
  '    // MUTATION: the two binary-input constraints were removed.\n' +
  '    // A direct prover can now supply non-binary field elements.';
const TARGETS = [
  'public/zk/xor_repaired.circom',
  'public/zk/xor_repaired.wasm',
  'public/zk/xor_repaired_final.zkey',
  'public/zk/xor_repaired_verification_key.json',
];

function parseArguments(argv) {
  if (argv.length !== 2 || argv[0] !== '--circom' || !argv[1]) {
    throw new Error('usage: node scripts/mutations.mjs --circom PATH');
  }
  return resolve(argv[1]);
}

function sha256(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

function run(command, args, options = {}) {
  return spawnSync(command, args, {
    cwd: ROOT,
    encoding: 'utf8',
    env: { ...process.env, CI: 'true' },
    maxBuffer: 16 * 1024 * 1024,
    ...options,
  });
}

function browserCheck(expectPass) {
  const cli = join(ROOT, 'node_modules/@playwright/test/cli.js');
  const result = run(process.execPath, [
    cli,
    'test',
    'e2e/constraint-gap.spec.ts',
    '--grep',
    TEST_TITLE,
    '--workers=1',
    '--reporter=list',
  ]);
  const output = `${result.stdout ?? ''}\n${result.stderr ?? ''}`;
  assert.match(output, /actual weak relation proves the explicit phantom output/, 'owning test did not run');
  assert.doesNotMatch(
    output,
    /browserType\.launch|Process from config\.webServer was not able to start/,
    'environment failure cannot count as a mutation result',
  );
  if (expectPass) {
    assert.equal(result.status, 0, `clean owning test failed:\n${output}`);
    assert.match(output, /1 passed/, 'clean result did not report one passing owning test');
  } else {
    assert.notEqual(result.status, 0, 'constraint-removal mutant survived the owning test');
    assert.match(output, /1 failed/, 'mutant failure summary was not present');
    assert.match(
      output,
      /repaired-rejected-phantom/,
      'failure was not the repaired-relation learner claim',
    );
  }
  return output;
}

async function main() {
  const circom = parseArguments(process.argv.slice(2));
  const compiler = await lstat(circom);
  assert.equal(compiler.isFile(), true, 'Circom compiler is not a regular file');

  const snapshots = new Map();
  for (const name of TARGETS) {
    const path = join(ROOT, name);
    assert.equal((await lstat(path)).isFile(), true, `${name} is not a regular file`);
    snapshots.set(name, await readFile(path));
  }
  const source = snapshots.get(TARGETS[0]).toString('utf8');
  assert.equal(source.split(CONSTRAINTS).length, 2, 'expected repaired constraint block exactly once');

  browserCheck(true);
  process.stdout.write('baseline: unmutated copy PASSES\n');

  let mutationCaught = false;
  try {
    await writeFile(join(ROOT, TARGETS[0]), source.replace(CONSTRAINTS, MUTANT));
    assert.notEqual(
      sha256(await readFile(join(ROOT, TARGETS[0]))),
      sha256(snapshots.get(TARGETS[0])),
      'mutation produced no source diff',
    );

    const build = run(process.execPath, [
      join(ROOT, 'scripts/build-xor-artifacts.mjs'),
      '--circom',
      circom,
      '--out',
      join(ROOT, 'public/zk'),
      '--circuit',
      'xor_repaired',
      '--reuse-ptau',
      join(ROOT, 'public/zk/xor_phase2.ptau'),
    ]);
    assert.equal(
      build.status,
      0,
      `mutated circuit/artifact regeneration failed:\n${build.stdout ?? ''}\n${build.stderr ?? ''}`,
    );
    for (const name of TARGETS.slice(1)) {
      assert.notEqual(
        sha256(await readFile(join(ROOT, name))),
        sha256(snapshots.get(name)),
        `mutation produced no ${name} diff`,
      );
    }
    browserCheck(false);
    mutationCaught = true;
    process.stdout.write('caught: removing both binary constraints makes the owning browser claim fail\n');
  } finally {
    for (const [name, contents] of snapshots) await writeFile(join(ROOT, name), contents);
    for (const [name, contents] of snapshots) {
      assert.equal(
        sha256(await readFile(join(ROOT, name))),
        sha256(contents),
        `byte restoration failed for ${name}`,
      );
    }
  }

  assert.equal(mutationCaught, true, 'focused constraint-removal mutation was not caught');
  browserCheck(true);
  process.stdout.write('restored baseline PASSES\n');
  process.stdout.write('all 1 mutation(s) caught\n');
}

main().catch((error) => {
  process.stderr.write(`${error?.stack ?? error}\n`);
  process.exitCode = 1;
});

