// Replay concrete faults against the assertion that owns each security or
// correctness claim. Every mutant must build, change dist/, die by assertion,
// restore byte-for-byte, and leave its owning test green again.
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import process from 'node:process';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
process.chdir(root);

const npmCommand = process.platform === 'win32' ? 'npm.cmd' : 'npm';
const build = [npmCommand, ['run', 'build']];
const vitest = (file, title) => [
  process.execPath,
  [join(root, 'node_modules', 'vitest', 'vitest.mjs'), 'run', file, '--testNamePattern', title],
];

function run([command, args]) {
  return spawnSync(command, args, {
    cwd: root,
    encoding: 'utf8',
    env: { ...process.env, CI: '1', NO_COLOR: '1' },
  });
}

function pass(command, label) {
  const result = run(command);
  if (result.status !== 0) {
    throw new Error(`${label}\n${result.stdout}\n${result.stderr}`);
  }
  return result;
}

function distHash() {
  const hash = createHash('sha256');
  const walk = (directory) => {
    for (const entry of readdirSync(directory, { withFileTypes: true })
      .sort((a, b) => a.name.localeCompare(b.name))) {
      const pathname = join(directory, entry.name);
      if (entry.isDirectory()) walk(pathname);
      else {
        hash.update(pathname);
        hash.update(readFileSync(pathname));
      }
    }
  };
  walk('dist');
  return hash.digest('hex');
}

const cases = [
  [
    'query randomness is replaced by a constant mask',
    'src/pir.ts',
    '  const maskS = (rand[0] & lowBitsMask(dbSize)) >>> 0;',
    '  const maskS = (0 & lowBitsMask(dbSize)) >>> 0;',
    vitest('src/pir.test.ts', 'produces a fresh random mask across runs'),
  ],
  [
    'non-integer target indices are accepted',
    'src/pir.ts',
    '  if (!Number.isInteger(targetIndex)) {',
    '  if (false && !Number.isInteger(targetIndex)) {',
    vitest('src/pir.test.ts', 'rejects NaN — which used to pass the range check'),
  ],
  [
    'non-integer server masks are coerced',
    'src/pir.ts',
    '  if (!Number.isInteger(mask) || mask < 0 || mask > 0xffffffff) {',
    '  if (false && (!Number.isInteger(mask) || mask < 0 || mask > 0xffffffff)) {',
    vitest('src/pir.test.ts', 'rejects values that bitwise coercion would silently turn into another mask'),
  ],
  [
    'server masks may name nonexistent records',
    'src/pir.ts',
    '  if ((unsignedMask & ~lowBitsMask(size)) >>> 0) {',
    '  if (false && ((unsignedMask & ~lowBitsMask(size)) >>> 0)) {',
    vitest('src/pir.test.ts', 'rejects mask bits that name records outside the database'),
  ],
  [
    'reconstruction verdict ignores author bytes',
    'src/pir.ts',
    '  return bytesEqual(reconstructed, expected);',
    '  return bytesEqual(reconstructed.subarray(0, 48), expected.subarray(0, 48));',
    vitest('src/pir.test.ts', 'recordsMatch rejects a record whose AUTHOR bytes were altered'),
  ],
  [
    'bit-31 collusion recovery uses Math.log2 on the signed XOR',
    'src/pir.ts',
    '  return 31 - Math.clz32(diff);',
    '  return Math.log2(maskS ^ maskSPrime);',
    vitest('src/pir.test.ts', 'recovers index 31 from a mask pair whose XOR sets the sign bit'),
  ],
  [
    'UTF-8 truncation slices through code points',
    'src/catalog.ts',
    '  const buf = new Uint8Array(maxBytes);\n  const { written } = encoder.encodeInto(text, buf);\n  return buf.subarray(0, written);',
    '  return encoder.encode(text).slice(0, maxBytes);',
    vitest('src/pir.test.ts', 'never produces a replacement character, at any cut point'),
  ],
  [
    'the second query mask no longer flips the requested bit',
    'src/pir.ts',
    '  const maskSPrime = (maskS ^ (1 << targetIndex)) >>> 0;',
    '  const maskSPrime = maskS;',
    vitest('src/pir.test.ts', 'masks differ in exactly one bit, and that bit is the target index'),
  ],
];

const sourceFiles = [...new Set(cases.map((entry) => entry[1]))];
const dirty = spawnSync('git', ['diff', '--exit-code', '--', ...sourceFiles], {
  cwd: root,
  encoding: 'utf8',
});
if (dirty.status !== 0) {
  throw new Error('Commit the source baseline before mutation checks.');
}

pass(build, 'baseline build');
const baseline = distHash();
const evidence = [];
console.log('baseline: unmutated copy PASSES');
mkdirSync('mutation-logs', { recursive: true });

for (const [name, file, before, after, owner] of cases) {
  pass(owner, `${name}: baseline owner`);
  const original = readFileSync(file, 'utf8');
  if (original.split(before).length !== 2) {
    throw new Error(`${name}: expected exactly one mutation site`);
  }

  let restoredBuild;
  let restoredHash;
  let restoredOwner;
  try {
    writeFileSync(file, original.replace(before, after));
    const sourceDiff = spawnSync('git', ['diff', '--', file], {
      cwd: root,
      encoding: 'utf8',
    }).stdout;
    if (!sourceDiff.trim()) throw new Error(`${name}: source diff is empty`);

    pass(build, `${name}: mutant build`);
    const mutant = distHash();
    if (mutant === baseline) throw new Error(`${name}: production artifact did not move`);

    const result = run(owner);
    const output = result.stdout + result.stderr;
    const logName = name.replaceAll(/[^A-Za-z0-9.-]+/g, '-').replace(/^-|-$/g, '');
    writeFileSync(`mutation-logs/${logName}.log`, output);
    if (
      result.status === 0 ||
      !/AssertionError|expected|FAIL|Test Files\s+\d+ failed/i.test(output)
    ) {
      throw new Error(`${name}: no assertion kill\n${output}`);
    }

    evidence.push({
      name,
      sourceDiff,
      baseline,
      mutant,
      namedTest: owner[1][owner[1].indexOf('--testNamePattern') + 1],
      assertionFailure: true,
      retries: 0,
    });
  } finally {
    writeFileSync(file, original);
    restoredBuild = run(build);
    if (restoredBuild.status === 0) restoredHash = distHash();
    restoredOwner = run(owner);
  }

  if (restoredBuild.status !== 0) {
    throw new Error(`${name}: restore build failed\n${restoredBuild.stdout}\n${restoredBuild.stderr}`);
  }
  if (restoredHash !== baseline) throw new Error(`${name}: restored artifact hash differs`);
  if (restoredOwner.status !== 0) {
    throw new Error(`${name}: restored owner failed\n${restoredOwner.stdout}\n${restoredOwner.stderr}`);
  }
  evidence.at(-1).restoredGreen = true;
  console.log(`${name}: killed; exact artifact restored; owning test green`);
}

writeFileSync('mutation-evidence.json', `${JSON.stringify(evidence, null, 2)}\n`);
console.log(`all ${cases.length} mutation(s) caught`);

/** Only an assertion in the exact owning test can kill a source mutation. */
export function assertNormalExit(result, label) {
  if (result.error || result.signal || !Number.isInteger(result.status)) {
    throw new Error(`${label}: process did not exit normally (${result.error?.message ?? result.signal ?? 'no exit status'})`);
  }
}

export function validateNamedRun(result, owner, shouldPass, expectedFile = 'claims.spec.ts') {
  assertNormalExit(result, owner);
  let report;
  try {
    report = JSON.parse(result.stdout);
  } catch {
    throw new Error(`${owner}: missing or invalid Playwright JSON report`);
  }
  if (!Array.isArray(report.errors) || report.errors.length) {
    throw new Error(`${owner}: runner errors cannot count as a mutation kill`);
  }
  const specs = [];
  function visit(suite) {
    specs.push(...(suite.specs ?? []));
    for (const child of suite.suites ?? []) visit(child);
  }
  for (const suite of report.suites ?? []) visit(suite);
  // Playwright's JSON locations are relative to testDir (e2e/).
  if (specs.length !== 1 || !specs[0].title.includes(owner) || specs[0].file !== expectedFile) {
    throw new Error(`${owner}: expected exactly the named owning test`);
  }
  const tests = specs[0].tests ?? [];
  if (tests.length !== 1 || tests[0].expectedStatus !== 'passed' || tests[0].results?.length !== 1) {
    throw new Error(`${owner}: skipped, expected-failure, repeated, or retried tests are invalid`);
  }
  const observed = tests[0].results[0];
  const expectedStatus = shouldPass ? 'passed' : 'failed';
  if (observed.status !== expectedStatus || observed.retry !== 0 || result.status !== (shouldPass ? 0 : 1)) {
    throw new Error(`${owner}: expected ${expectedStatus}, observed ${observed.status}, exit ${result.status}`);
  }
  const errors = observed.errors ?? (observed.error ? [observed.error] : []);
  if (shouldPass) {
    if (errors.length) throw new Error(`${owner}: passing test reported errors`);
    return;
  }
  if (errors.length !== 1) throw new Error(`${owner}: expected exactly one owning assertion failure`);
  const failure = [observed.error?.message, observed.error?.stack, errors[0].message, errors[0].stack].filter(Boolean).join('\n');
  if (!/expect\(|AssertionError/.test(failure) || !/spec\.ts:\d+:\d+/.test(failure) ||
      /No tests found|browserType\.launch|browser has been closed|Target (?:page|browser|context).*closed|net::ERR_|Test timeout of|page\.goto:|locator\.(?:click|check|uncheck):|waiting for.*web server|at (?:boot|solveBob)\b|page must raise no uncaught exceptions/i.test(failure)) {
    throw new Error(`${owner}: infrastructure, setup, runtime, or non-assertion failure cannot count as a mutation kill`);
  }
}

export function validateUnitRun(result, owner, file, shouldPass) {
  assertNormalExit(result, owner);
  const report = JSON.parse(result.stdout);
  const suites = report.testResults ?? [];
  const assertions = suites.flatMap(s => (s.assertionResults ?? []).filter(a => a.status !== 'skipped').map(a => ({...a,file:s.name})));
  if (assertions.length !== 1 || !assertions[0].title.includes(owner) || !assertions[0].file.endsWith(file) ||
      assertions[0].status !== (shouldPass ? 'passed' : 'failed') || result.status !== (shouldPass ? 0 : 1) ||
      report.numPassedTests !== (shouldPass ? 1 : 0) || report.numFailedTests !== (shouldPass ? 0 : 1)) throw Error(`${owner}: expected exactly the owning unit test`);
  const failures = assertions[0].failureMessages ?? [];
  if (shouldPass ? failures.length : failures.length !== 1 || !/AssertionError|expected .*to/i.test(failures[0])) throw Error(`${owner}: expected an owning assertion failure`);
}

#!/usr/bin/env node

/**
 * Replays the Exhibit 7 §4.1c ledger in an isolated archive of committed HEAD.
 * A mutation is killed only after all five required observations occur:
 * baseline green, non-empty source diff, moved bundle, named test red, and
 * byte-identical restoration with the named test green. No result is typed in.
 */

import { spawnSync } from 'node:child_process';
import { assertNormalExit,validateNamedRun } from './mutation-report.mjs';
import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  symlinkSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url)).replace(/\/$/, '');
const ledger = JSON.parse(readFileSync(join(root, 'e2e', 'verdict-mutations.json'), 'utf8'));
const selected = process.argv.slice(2);
const mutations = selected.length
  ? ledger.mutations.filter((entry) => selected.includes(entry.id))
  : ledger.mutations;

if (selected.some((id) => !ledger.mutations.some((entry) => entry.id === id))) {
  console.error('Unknown mutation id. Run without arguments to execute the full ledger.');
  process.exit(2);
}

function run(command, args, cwd, allowFailure = false) {
  const result = spawnSync(command, args, {
    cwd,
    encoding: 'utf8',
    env: { ...process.env, CI: '1', FORCE_COLOR: '0' },
    maxBuffer: 64 * 1024 * 1024,
  });
  assertNormalExit(result,command);
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  if (!allowFailure && result.status !== 0) {
    throw new Error(`${command} ${args.join(' ')} failed (${result.status})\n${output}`);
  }
  return { ...result, status: result.status, output };
}

const git = (...args) => run('git', ['-C', root, ...args], root).output.trim();
const trackedDirty = git('status', '--porcelain', '--untracked-files=no');
if (trackedDirty) {
  console.error('Refusing to mutate: commit the real implementation first.');
  console.error(trackedDirty);
  process.exit(2);
}

for (const entry of mutations) {
  const source = readFileSync(join(root, entry.file), 'utf8');
  const count = source.split(entry.find).length - 1;
  if (count !== 1) {
    console.error(`${entry.id}: anchor occurs ${count} times in ${entry.file}; expected exactly once.`);
    process.exit(2);
  }
  if (source.replace(entry.find, entry.replace) === source) {
    console.error(`${entry.id}: patch is a no-op.`);
    process.exit(2);
  }
}

const tree = mkdtempSync(join(tmpdir(), 'frost-ats-mutations-'));
const archive = join(tree, 'source.tar');

function digest(value) {
  return createHash('sha256').update(value).digest('hex').slice(0, 12);
}

function fileHash(path) {
  return digest(readFileSync(path));
}

function bundleHash() {
  const assets = join(tree, 'dist', 'assets');
  if (!existsSync(assets)) throw new Error('dist/assets does not exist after a reported successful build');
  const hash = createHash('sha256');
  for (const name of readdirSync(assets).sort()) {
    hash.update(name);
    hash.update(readFileSync(join(assets, name)));
  }
  return hash.digest('hex').slice(0, 12);
}

function build() {
  run('npm', ['run', 'build'], tree);
  return bundleHash();
}

function owningTest(entry, expectGreen) {
  const result = run(
    'npx',
    [
      'playwright',
      'test',
      'e2e/claims.spec.ts',
      '-g',
      entry.test,
      '--retries=0',
      '--reporter=json',
    ],
    tree,
    !expectGreen,
  );
  validateNamedRun(result,entry.test,expectGreen);

}

function replaceExactly(path, from, to) {
  const source = readFileSync(path, 'utf8');
  const count = source.split(from).length - 1;
  if (count !== 1) throw new Error(`${path}: replacement anchor occurs ${count} times`);
  const changed = source.replace(from, to);
  if (changed === source) throw new Error(`${path}: source diff was empty`);
  writeFileSync(path, changed);
}

let failures = 0;
try {
  run('git', ['archive', '--format=tar', `--output=${archive}`, 'HEAD'], root);
  run('tar', ['-xf', archive, '-C', tree], root);
  unlinkSync(archive);
  symlinkSync(join(root, 'node_modules'), join(tree, 'node_modules'));
  symlinkSync(join(root, 'pkg'), join(tree, 'pkg'));

  console.log(`Committed tree: ${git('rev-parse', '--short', 'HEAD')}`);
  console.log(`Mutations: ${mutations.length}\n`);

  const baselineBundle = build();

  for (const entry of mutations) {
    const path = join(tree, entry.file);
    const sourceBefore = fileHash(path);
    console.log(`${entry.id}`);
    try {
      owningTest(entry, true);
      console.log(`  1 baseline PASSES — ${entry.test}`);

      replaceExactly(path, entry.find, entry.replace);
      const sourceAfter = fileHash(path);
      if (sourceAfter === sourceBefore) throw new Error('source diff is empty');
      console.log(`  2 source diff NON-EMPTY — ${sourceBefore} -> ${sourceAfter}`);

      const mutatedBundle = build();
      if (mutatedBundle === baselineBundle) throw new Error('production bundle hash did not move');
      console.log(`  3 bundle hash MOVED — ${baselineBundle} -> ${mutatedBundle}`);

      owningTest(entry, false);
      console.log(`  4 NAMED test RED — ${entry.test}`);

      replaceExactly(path, entry.replace, entry.find);
      if (fileHash(path) !== sourceBefore) throw new Error('source did not restore byte-for-byte');
      const restoredBundle = build();
      if (restoredBundle !== baselineBundle) throw new Error('restored bundle hash differs from baseline');
      owningTest(entry, true);
      console.log(`  5 restored and GREEN — bundle ${restoredBundle}\n`);
    } catch (error) {
      failures += 1;
      console.error(`  FAILED: ${error instanceof Error ? error.message : String(error)}\n`);
      const current = readFileSync(path, 'utf8');
      if (current.includes(entry.replace) && !current.includes(entry.find)) {
        replaceExactly(path, entry.replace, entry.find);
      }
    }
  }
} finally {
  rmSync(tree, { recursive: true, force: true });
}

console.log(`${mutations.length - failures}/${mutations.length} mutations killed.`);
process.exit(failures === 0 ? 0 : 1);

// Clean-baseline mutation gate for the visual-sharing exhibit.
//
// Fourteen recipes over `src/visual.ts` and `src/visual-ui.ts`. Until
// 2026-10-27 this runner counted ANY non-zero exit of the two owned test files
// as a kill, so a mutant that failed to compile, or a test run that crashed,
// would have been reported as "caught". It now follows the fleet pattern
// (Attestation Gate, Matsui Line, Residue Gate, Shelf Oracle): for every recipe
// it proves, in order,
//
//   1. the unmodified copy passes the WHOLE unit suite and builds,
//   2. the named owning test is green on the unmodified copy,
//   3. the patch produces a NON-EMPTY source change and the production bundle
//      hash moves (a mutation the build never picked up proves nothing),
//   4. the named owning test goes RED on a test failure -- a timeout, a crash,
//      a missing module or a type error is NOT a kill,
//   5. the source is restored byte for byte, the bundle hash returns to the
//      baseline, and the owning test is green again.
//
// Owners were chosen from observed kills, not from prose: each recipe was
// applied and the two owned specs run with the JSON reporter, and the owner
// is one of the tests that failed with an assertion. Eleven are owned by
// `src/visual.test.ts` and three by the jsdom smoke test in
// `src/ui-smoke.test.ts`.
//
// Run from demos/shamir-gate (or anywhere; the script changes to its package):
//   node scripts/visual-mutations.mjs [mutation name]

import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { stripVTControlCharacters } from 'node:util';
import process from 'node:process';

process.chdir(join(dirname(fileURLToPath(import.meta.url)), '..'));

const VISUAL = 'src/visual.ts';
const VISUAL_UI = 'src/visual-ui.ts';
const VISUAL_SPEC = 'src/visual.test.ts';
const SMOKE_SPEC = 'src/ui-smoke.test.ts';

const unit = (spec, test) => ({ runner: 'vitest', spec, test });
const SMOKE_OWNER = 'generates, reconstructs, proves full distributions, runs controls, and retires stale results';

const mutations = [
  {
    name: 'white and black share-2 rules swapped',
    file: VISUAL,
    anchor: 'share2: source === 0 ? [...pattern] as Block : complementBlock(pattern),',
    replacement: 'share2: source === 1 ? [...pattern] as Block : complementBlock(pattern),',
    ...unit(VISUAL_SPEC, 'uses identical rows for white and complementary rows for black'),
  },
  {
    name: 'physical stack changed from OR to XOR',
    file: VISUAL,
    anchor: '? (bit | share2[rowIndex][columnIndex]) as Bit',
    replacement: '? (bit ^ share2[rowIndex][columnIndex]) as Bit',
    ...unit(VISUAL_SPEC, 'draws independently for every pixel and round-trips solely from the shares'),
  },
  {
    name: 'basis admits a weight-one pattern',
    file: VISUAL,
    anchor: '  [0, 0, 1, 1],',
    replacement: '  [0, 0, 0, 1],',
    ...unit(VISUAL_SPEC, 'enumerates exactly the six distinct weight-two patterns in canonical order'),
  },
  {
    name: 'one of six pattern outcomes removed',
    file: VISUAL,
    anchor: '  [1, 1, 0, 0],\n',
    replacement: '',
    ...unit(VISUAL_SPEC, 'enumerates exactly the six distinct weight-two patterns in canonical order'),
  },
  {
    name: 'uniform rejection sampler replaced with byte modulo six',
    file: VISUAL,
    anchor: 'const value = await draw(0n, BigInt(VISUAL_PATTERNS.length));',
    replacement: 'const value = (await draw(0n, 256n)) % BigInt(VISUAL_PATTERNS.length);',
    ...unit(VISUAL_SPEC, 'uses rejection sampling through randomBigInt rather than byte modulo six'),
  },
  {
    name: 'one mask reused across the image',
    file: VISUAL,
    anchor: 'const patternIndex = await samplePatternIndex(draw);',
    replacement: 'const patternIndex = patternIndices[0] ?? await samplePatternIndex(draw);',
    ...unit(VISUAL_SPEC, 'draws independently for every pixel and round-trips solely from the shares'),
  },
  {
    name: 'share 2 keyed by a pattern bit instead of the source pixel',
    file: VISUAL,
    anchor: 'const sourceBit = source[Math.floor(index / width)][index % width];',
    replacement: 'const sourceBit = pattern[0];',
    ...unit(VISUAL_SPEC, 'draws independently for every pixel and round-trips solely from the shares'),
  },
  {
    name: 'contrast difference hardcoded instead of derived',
    file: VISUAL,
    anchor: 'const difference = blackOrWeight - whiteOrWeight;',
    replacement: 'const difference = 2;',
    ...unit(VISUAL_SPEC, 'derives pixel expansion and one-half contrast from the basis blocks'),
  },
  {
    name: 'mismatched share dimensions allowed to zip',
    file: VISUAL,
    anchor: 'if (left.width !== right.width || left.height !== right.height) {',
    replacement: 'if (false && (left.width !== right.width || left.height !== right.height)) {',
    ...unit(VISUAL_SPEC, 'refuses missing, malformed and mismatched shares instead of truncating'),
  },
  {
    name: 'one missing share no longer refused at the boundary',
    file: VISUAL,
    anchor: 'if (!share1Input || !share2Input) {',
    replacement: 'if (!share1Input && !share2Input) {',
    ...unit(VISUAL_SPEC, 'refuses missing, malformed and mismatched shares instead of truncating'),
  },
  {
    name: 'invalid pattern weight accepted',
    file: VISUAL,
    anchor: "  if (hammingWeight(pattern) !== 2) {\n    throw new Error('Every visual-share pattern must contain exactly two black subpixels.');\n  }",
    replacement: "  if (false && hammingWeight(pattern) !== 2) {\n    throw new Error('Every visual-share pattern must contain exactly two black subpixels.');\n  }",
    ...unit(VISUAL_SPEC, 'keeps either labeled share weight two for both source colors'),
  },
  {
    name: 'input change preserves stale derived verdicts',
    file: VISUAL_UI,
    anchor: "  placeholder('visual-share-2', 'Generate shares from the current source.');\n  clearDerivedResults();\n  setStatus(`${reason} Previous masks, reconstructions, distributions, and verdicts were retired.`);",
    replacement: "  placeholder('visual-share-2', 'Generate shares from the current source.');\n  setStatus(`${reason} Previous masks, reconstructions, distributions, and verdicts were retired.`);",
    ...unit(SMOKE_SPEC, SMOKE_OWNER),
  },
  {
    name: 'digital XOR mislabeled as physical stacking',
    file: VISUAL_UI,
    anchor: 'XOR is not physical transparency stacking:',
    replacement: 'XOR is physical transparency stacking:',
    ...unit(SMOKE_SPEC, SMOKE_OWNER),
  },
  {
    name: 'marginals mislabeled as the full privacy proof',
    file: VISUAL_UI,
    anchor: 'same complete block distribution',
    replacement: 'same per-subpixel marginals',
    ...unit(SMOKE_SPEC, SMOKE_OWNER),
  },
];

const INFRASTRUCTURE = /No test files found|Cannot find module|Failed to load url|Unhandled Error|error TS\d+|Test timed out|Test timeout of/;

function run(command, args, timeout) {
  const child = spawnSync(command, args, {
    encoding: 'utf8',
    env: { ...process.env, CI: '1', NO_COLOR: '1' },
    maxBuffer: 32 * 1024 * 1024,
    timeout,
  });
  return {
    ok: child.status === 0 && !child.error && !child.signal,
    status: child.status,
    signal: child.signal,
    error: child.error,
    output: stripVTControlCharacters(`${child.stdout ?? ''}${child.stderr ?? ''}`),
  };
}

function requirePass(result, label) {
  if (!result.ok) {
    throw new Error(`${label} failed (status ${result.status}, signal ${result.signal ?? 'none'}):\n${result.output.slice(-4000)}`);
  }
}

/** `npm run build` runs the publish-request control, typechecks and bundles. */
function build() {
  requirePass(run('npm', ['run', 'build'], 300_000), 'build');
}

/** Hash of every emitted asset (JavaScript, CSS and source map). */
function bundleHash() {
  const dir = 'dist/assets';
  const files = readdirSync(dir).filter((file) => statSync(join(dir, file)).isFile()).sort();
  if (files.length === 0) throw new Error('build produced no assets');
  const hash = createHash('sha256');
  for (const file of files) hash.update(file).update(readFileSync(join(dir, file)));
  return hash.digest('hex');
}

const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function owningTest(mutation) {
  return run('npx', ['vitest', 'run', mutation.spec, '-t', escapeRegex(mutation.test)], 300_000);
}

function requireNamedGreen(result, mutation, label) {
  requirePass(result, label);
  if (!/Tests\s+1 passed\b/.test(result.output) || /\d+ failed\b/.test(result.output)) {
    throw new Error(`${label} did not execute exactly one passing test:\n${result.output.slice(-3000)}`);
  }
}

function requireNamedRed(result, mutation) {
  if (result.ok) throw new Error(`${mutation.name}: mutation SURVIVED its owning test`);
  if (INFRASTRUCTURE.test(result.output)) {
    throw new Error(`${mutation.name}: an infrastructure failure or timeout is not a kill:\n${result.output.slice(-3000)}`);
  }
  if (!result.output.includes(mutation.test)) {
    throw new Error(`${mutation.name}: the failure did not name its owning test:\n${result.output.slice(-3000)}`);
  }
  if (!/Tests\s+1 failed\b/.test(result.output)) {
    throw new Error(`${mutation.name}: the owning test did not fail exactly once:\n${result.output.slice(-3000)}`);
  }
  // A kill is a test FAILURE: an expect() assertion, or the code under test
  // throwing into the test body. Both are reported as failed tests; what is
  // excluded is everything the INFRASTRUCTURE pattern names above.
}

const requested = process.argv[2];
const selected = requested ? mutations.filter((mutation) => mutation.name === requested) : mutations;
if (selected.length === 0) throw new Error(`unknown mutation: ${requested}`);

const files = [...new Set(selected.map((mutation) => mutation.file))];
if (run('git', ['diff', '--quiet', 'HEAD', '--', ...files], 60_000).status !== 0) {
  throw new Error('commit the mutated source files before replaying mutations; the harness restores from disk, not from git');
}

build();
const baseline = bundleHash();
// The WHOLE unit suite: a baseline scoped to the mutated files would stay green
// while a mutation broke something elsewhere, and the restore control at the
// end would agree with it.
requirePass(run('npx', ['vitest', 'run'], 600_000), 'unmutated unit baseline');
console.log('baseline: unmutated copy PASSES');

const evidence = [];
for (const [index, mutation] of selected.entries()) {
  const original = readFileSync(mutation.file, 'utf8');
  if (original.split(mutation.anchor).length !== 2) {
    throw new Error(`${mutation.name}: the anchor must occur exactly once in ${mutation.file}`);
  }
  requireNamedGreen(owningTest(mutation), mutation, `${mutation.name}: named baseline`);
  let record;
  try {
    const changed = original.replace(mutation.anchor, mutation.replacement);
    if (changed === original) throw new Error(`${mutation.name}: the patch changed nothing`);
    writeFileSync(mutation.file, changed);
    const diff = run('git', ['diff', '--no-ext-diff', '--', mutation.file], 60_000);
    if (diff.output.trim() === '') throw new Error(`${mutation.name}: the source diff was empty`);
    build();
    const mutant = bundleHash();
    if (mutant === baseline) throw new Error(`${mutation.name}: the production bundle did not change`);
    const red = owningTest(mutation);
    requireNamedRed(red, mutation);
    record = {
      name: mutation.name,
      file: mutation.file,
      runner: mutation.runner,
      spec: mutation.spec,
      owningTest: mutation.test,
      baselineGreen: true,
      sourceDiffNonEmpty: true,
      baselineBundle: baseline,
      mutantBundle: mutant,
      bundleMoved: true,
      owningTestRed: true,
      failureExcerpt: red.output.split('\n').filter((line) => /expect|Error|✗|×|FAIL/.test(line)).slice(0, 6),
    };
    console.log(`caught ${index + 1}/${selected.length}: ${mutation.name} -> ${mutation.test}`);
  } finally {
    writeFileSync(mutation.file, original);
    if (readFileSync(mutation.file, 'utf8') !== original) {
      throw new Error(`${mutation.name}: source was not restored byte for byte`);
    }
    build();
    if (bundleHash() !== baseline) throw new Error(`${mutation.name}: restored bundle differs from the baseline`);
  }
  requireNamedGreen(owningTest(mutation), mutation, `${mutation.name}: restored baseline`);
  record.restoredGreen = true;
  evidence.push(record);
  writeFileSync('mutation-evidence.json', `${JSON.stringify(evidence, null, 2)}\n`);
}

requirePass(run('npx', ['vitest', 'run'], 600_000), 'restored unit baseline');
console.log(`all ${evidence.length} of ${selected.length} mutation(s) caught; sources and production bundle restored byte for byte`);

