    '(BigInt(round)<<15n)',
    '(BigInt(round)<<16n)',
    [
      'node',
      [
        '--import',
        'tsx',
        '--test',
        '--test-name-pattern',
        'PRESENT four published',
        'src/__tests__/present.test.ts',
