 {name:'splice loses XOR',file:'src/cbcmac/forge.ts',anchor:'forged.set(xor(m, t), 16)',replacement:'forged.set(xor(m, new Uint8Array(t.length)), 16)',test:'CBC-MAC one-query splice'},
