];
const run=(command,args,extra={})=>{const r=spawnSync(command,args,{encoding:'utf8',timeout:120000,env:{...process.env,CI:'1',...extra}});return {status:r.status,output:(r.stdout??'')+'\n'+(r.stderr??'')};};
