// Replay concrete faults against the assertion that owns each Poly1305 claim.
// Every mutant must build, change dist/, die by assertion, restore byte-for-byte,
// and leave its owning test green again.
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import process from 'node:process';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
process.chdir(root);

const npmCommand = process.platform === 'win32' ? 'npm.cmd' : 'npm';
const build = [npmCommand, ['run', 'build']];
const vitest = (title) => [
  process.execPath,
  [join(root, 'node_modules', 'vitest', 'vitest.mjs'), 'run', 'src/mac.test.ts', '--testNamePattern', title],
];

function run([command, args]) {
  return spawnSync(command, args, {
    cwd: root,
    encoding: 'utf8',
    env: { ...process.env, CI: '1', NO_COLOR: '1' },
  });
}

function pass(command, label) {
  const result = run(command);
  if (result.status !== 0) {
    throw new Error(`${label}\n${result.stdout}\n${result.stderr}`);
  }
  return result;
}

function distHash() {
  const hash = createHash('sha256');
  const walk = (directory) => {
    for (const entry of readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const pathname = join(directory, entry.name);
      if (entry.isDirectory()) walk(pathname);
      else {
        hash.update(pathname);
        hash.update(readFileSync(pathname));
      }
    }
  };
  walk('dist');
  return hash.digest('hex');
}

const cases = [
  [
    'MAC key validation no longer owns the exact 32-byte boundary',
    'src/mac.ts',
    'if (key.length !== POLY1305_KEY_LENGTH) {',
    'if (false && key.length !== POLY1305_KEY_LENGTH) {',
    vitest('rejects keys that are not 32 bytes'),
  ],
  [
    'the polynomial stepper accepts an oversized key',
    'src/poly-math.ts',
    'if (key.length !== 32) {',
    'if (key.length < 32) {',
    vitest('rejects keys that are not 32 bytes'),
  ],
  [
    'tag decoding silently truncates or extends a captured tag',
    'src/poly-math.ts',
    'if (tag.length !== BLOCK_SIZE) {',
    'if (false && tag.length !== BLOCK_SIZE) {',
    vitest('rejects values that are not exactly one complete tag'),
  ],
  [
    'verification accepts a genuine tag with trailing bytes',
    'src/mac.ts',
    'if (tag.length !== POLY1305_TAG_LENGTH) {',
    'if (false && tag.length !== POLY1305_TAG_LENGTH) {',
    vitest('fails on a wrong-length tag'),
  ],
  [
    'verification compares only the first tag byte',
    'src/mac.ts',
    'for (let index = 0; index < POLY1305_TAG_LENGTH; index += 1) {',
    'for (let index = 0; index < 1; index += 1) {',
    vitest('fails when one tag byte is flipped'),
  ],
  [
    'single-block encoding omits the required 0x01 byte',
    'src/poly-math.ts',
    'blockWithOne[chunk.length] = 0x01;',
    'blockWithOne[chunk.length] = 0x00;',
    vitest('forges a tag the genuine key accepts'),
  ],
  [
    'clamping leaves the high nibble of byte 15 intact',
    'src/poly-math.ts',
    'clamped[15] &= 0x0f;',
    'clamped[15] &= 0xff;',
    vitest('clamps r to the documented value'),
  ],
  [
    'clamping leaves the low bits of byte 4 intact',
    'src/poly-math.ts',
    'clamped[4] &= 0xfc;',
    'clamped[4] &= 0xff;',
    vitest('clamps r to the documented value'),
  ],
  [
    'ambiguous key recovery guesses the first surviving candidate',
    'src/poly-math.ts',
    'return candidates.length === 1 ? candidates[0] : null;',
    'return candidates.length > 0 ? candidates[0] : null;',
    vitest('reports ambiguity instead of guessing'),
  ],
  [
    'forged tags skip reduction in the Poly1305 field',
    'src/poly-math.ts',
    'const tagValue = (((c * recovered.r) % POLY1305_PRIME) + recovered.s) % TWO_POW_128;',
    'const tagValue = ((c * recovered.r) + recovered.s) % TWO_POW_128;',
    vitest('forges a tag the genuine key accepts'),
  ],
];

const sourceFiles = [...new Set(cases.map((entry) => entry[1]))];
const dirty = spawnSync('git', ['diff', '--exit-code', '--', ...sourceFiles], {
  cwd: root,
  encoding: 'utf8',
});
if (dirty.status !== 0) {
  throw new Error('Commit the source baseline before mutation checks.');
}

pass(build, 'baseline build');
const baseline = distHash();
const evidence = [];
console.log('baseline: unmutated copy PASSES');
mkdirSync('mutation-logs', { recursive: true });

for (const [name, file, before, after, owner] of cases) {
  pass(owner, `${name}: baseline owner`);
  const original = readFileSync(file, 'utf8');
  if (original.split(before).length !== 2) {
    throw new Error(`${name}: expected exactly one mutation site`);
  }

  let restoredBuild;
  let restoredHash;
  let restoredOwner;
  try {
    writeFileSync(file, original.replace(before, after));
    const sourceDiff = spawnSync('git', ['diff', '--', file], {
      cwd: root,
      encoding: 'utf8',
    }).stdout;
    if (!sourceDiff.trim()) throw new Error(`${name}: source diff is empty`);

    pass(build, `${name}: mutant build`);
    const mutant = distHash();
    if (mutant === baseline) throw new Error(`${name}: production artifact did not move`);

    const result = run(owner);
    const output = result.stdout + result.stderr;
    const logName = name.replaceAll(/[^A-Za-z0-9.-]+/g, '-').replace(/^-|-$/g, '');
    writeFileSync(`mutation-logs/${logName}.log`, output);
    if (result.status === 0 || !/AssertionError|expected|FAIL|failed/i.test(output)) {
      throw new Error(`${name}: no assertion kill\n${output}`);
    }

    evidence.push({
      name,
      sourceDiff,
      baseline,
      mutant,
      namedTest: owner[1][owner[1].indexOf('--testNamePattern') + 1],
      assertionFailure: true,
      retries: 0,
    });
  } finally {
    writeFileSync(file, original);
    restoredBuild = run(build);
    if (restoredBuild.status === 0) restoredHash = distHash();
    restoredOwner = run(owner);
  }

  if (restoredBuild.status !== 0) {
    throw new Error(`${name}: restore build failed\n${restoredBuild.stdout}\n${restoredBuild.stderr}`);
  }
  if (restoredHash !== baseline) throw new Error(`${name}: restored artifact hash differs`);
  if (restoredOwner.status !== 0) {
    throw new Error(`${name}: restored owner failed\n${restoredOwner.stdout}\n${restoredOwner.stderr}`);
  }
  evidence.at(-1).restoredGreen = true;
  console.log(`${name}: killed; exact artifact restored; owning test green`);
}

writeFileSync('mutation-evidence.json', `${JSON.stringify(evidence, null, 2)}\n`);
console.log(`all ${cases.length} mutation(s) caught`);

import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { assertNormalExit, validateNamedRun } from './mutation-report.mjs';

const mutations = [
  {
    id: 'flip-p-codeword',
    verdict: 'chosen-message correctness',
    file: 'src/ext/iknp.ts',
    from: 'p[b] = u[b] ^ v[b] ^ (choice === 2 ? 0xff : 0x00);',
    to: 'p[b] = u[b] ^ v[b] ^ (choice === 1 ? 0xff : 0x00);',
    test: 'OT extension printed correctness is derived from every produced transfer',
  },
  {
    id: 'drop-r-and-p',
    verdict: 'sender q identity',
    file: 'src/ext/iknp.ts',
    from: 'q[b] = selected[b] ^ (setup.senderChoiceBytes[b] & p[b]);',
    to: 'q[b] = selected[b] ^ (p[b] & 0);',
    test: 'sender q row uses r AND p, preserving the book identity',
  },
  {
    id: 'swap-hash-branch',
    verdict: 'wrong-message rejection',
    file: 'src/ext/iknp.ts',
    from: 'y2.set(hashRow(receiver.firstIndex + i, 2, qXorR), i * 32);',
    to: 'y2.set(hashRow(receiver.firstIndex + i, 1, qXorR), i * 32);',
    test: 'hash branch domain separation keeps both receiver choices correct',
  },
  {
    id: 'reverse-u-transpose',
    verdict: '128-coordinate alignment',
    file: 'src/ext/iknp.ts',
    from: 'const uRows = await transposeColumnsChunked(zeroColumns, ownedChoices.length, {',
    to: 'const uRows = await transposeColumnsChunked([...zeroColumns].reverse(), ownedChoices.length, {',
    test: 'rendered transpose keeps all 128 base coordinates aligned',
  },
  {
    id: 'invert-recovered-r',
    verdict: 'corrupt-receiver alarm',
    file: 'src/ext/corrupt-receiver.ts',
    from: 'recovered[j] = matchedOne ? 1 : 0;',
    to: 'recovered[j] = matchedOne ? 0 : 1;',
    test: 'corrupt receiver fixture keeps chosen checks green while recovering r and both later messages',
  },
  {
    id: 'repeat-aes-stream',
    verdict: 'fresh PRF positions across runs',
    file: 'src/ext/prf.ts',
    from: 'setUint32(12, (firstIndex - 1) / 128, false)',
    to: 'setUint32(12, 0, false)',
    test: 'repeated extension runs use new PRF positions under the same base setup',
  },
  {
    id: 'restart-hash-index',
    verdict: 'independent global-index hash calculation',
    file: 'src/ext/iknp.ts',
    from: 'writeIndex(encoded, index);',
    to: 'writeIndex(encoded, 1);',
    test: 'the repeated-run hash is independently derived from its displayed global index and row',
  },
  {
    id: 'misdisplay-probe-choices',
    verdict: 'displayed choices match fixed probes',
    file: 'src/ui-ext.ts',
    from: "brokenMode = (event.currentTarget as HTMLInputElement).checked;\n    choices = randomChoices(transferCount);\n    if (brokenMode) choices.fill(1, 0, 128);",
    to: "brokenMode = (event.currentTarget as HTMLInputElement).checked;\n    choices = randomChoices(transferCount);\n    if (brokenMode) choices.fill(2, 0, 128);",
    test: 'malicious probe choices are fixed and match the rows the page computes',
  },
  {
    id: 'retain-compromised-setup',
    verdict: 'discard base secrets after the attack',
    file: 'src/ui-ext.ts',
    from: 'if (!brokenMode) discardBaseSetup();',
    to: 'if (!brokenMode && false) discardBaseSetup();',
    test: 'returning from malicious mode discards the compromised base setup before an honest run',
  },
  {
    id: 'delete-negative-claim',
    verdict: 'visible malicious-security limitation',
    file: 'src/ui-ext.ts',
    from: "This OT extension is secure only against honest-but-curious parties: a receiver who deviates learns the sender's secret r, and with it both messages of every later transfer.",
    to: '',
    test: 'corrupt receiver fixture keeps chosen checks green while recovering r and both later messages',
  },
];

function run(file, args) {
  const result = spawnSync(file, args, {
    cwd: process.cwd(),
    env: { ...process.env, CI: '1', NO_COLOR: '1', FORCE_COLOR: '0' },
    encoding: 'utf8',
    stdio: 'pipe',
    timeout: 180_000,
    maxBuffer: 16 * 1024 * 1024,
  });
  assertNormalExit(result, `${file} ${args.join(' ')}`);
  return result;
}

function filesUnder(path) {
  return readdirSync(path)
    .flatMap((name) => {
      const full = join(path, name);
      return statSync(full).isDirectory() ? filesUnder(full) : [full];
    })
    .sort();
}

function bundleHash() {
  const hash = createHash('sha256');
  for (const file of filesUnder('dist').filter((path) => path.endsWith('.js'))) {
    hash.update(file);
    hash.update(readFileSync(file));
  }
  return hash.digest('hex');
}

function build() {
  const result = run('npm', ['run', 'build']);
  if (result.status !== 0) throw new Error(`build failed; this is not a mutation kill\n${result.stdout}\n${result.stderr}`);
  return bundleHash();
}

function namedTest(name, expectSuccess) {
  const result = run(
    'npx',
    [
      'playwright',
      'test',
      'e2e/claims.spec.ts',
      '--grep',
      // --grep includes the project/file prefix; the JSON validator below
      // still requires the exact spec.title and exactly one result.
      `${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`,
      '--retries=0',
      '--workers=1',
      '--reporter=json',
    ],
  );
  try {
    validateNamedRun(result, name, expectSuccess);
  } catch (error) {
    throw new Error(`${error.message}\n${result.stdout}\n${result.stderr}`);
  }
}

const initialStatus = execFileSync('git', ['status', '--porcelain'], { encoding: 'utf8' });
if (initialStatus !== '') {
  throw new Error('mutation run requires a clean committed worktree');
}

for (const mutation of mutations) {
  const original = readFileSync(mutation.file, 'utf8');
  if (original.split(mutation.from).length !== 2) {
    throw new Error(`${mutation.id}: mutation target must occur exactly once`);
  }
  process.stdout.write(`\nMUTATION ${mutation.id} — ${mutation.verdict}\n`);
  const baselineHash = build();
  namedTest(mutation.test, true);
  process.stdout.write(`1 baseline passes — ${mutation.test}\n`);
  try {
    writeFileSync(mutation.file, original.replace(mutation.from, mutation.to));
    const diff = execFileSync('git', ['diff', '--', mutation.file], { encoding: 'utf8' });
    if (diff.trim() === '') throw new Error(`${mutation.id}: source diff was empty`);
    process.stdout.write(`2 source diff NON-EMPTY — ${mutation.file}\n`);

    const mutantHash = build();
    if (mutantHash === baselineHash) throw new Error(`${mutation.id}: bundle hash did not move`);
    process.stdout.write(`3 bundle hash MOVED — ${baselineHash.slice(0, 12)} -> ${mutantHash.slice(0, 12)}\n`);

    namedTest(mutation.test, false);
    process.stdout.write(`4 named test RED (--retries=0) — ${mutation.test}\n`);
  } finally {
    writeFileSync(mutation.file, original);
    const restoredHash = build();
    if (restoredHash !== baselineHash) throw new Error(`${mutation.id}: restored bundle differs from baseline`);
    namedTest(mutation.test, true);
    if (execFileSync('git', ['status', '--porcelain'], { encoding: 'utf8' }) !== '') {
      throw new Error(`${mutation.id}: restore did not return to the committed tree`);
    }
    process.stdout.write(`5 restored, original bundle hash and GREEN — ${mutation.test}\n`);
  }
}

process.stdout.write(`\nSUMMARY ${mutations.length} of ${mutations.length} mutations killed\n`);

/** Only an assertion in the exact owning test can kill a source mutation. */
export function assertNormalExit(result, label) {
  if (result.error || result.signal || !Number.isInteger(result.status)) {
    throw new Error(`${label}: process did not exit normally (${result.error?.message ?? result.signal ?? 'no exit status'})`);
  }
}

export function validateNamedRun(result, owner, shouldPass) {
  assertNormalExit(result, owner);
  let report;
  try {
    report = JSON.parse(result.stdout);
  } catch {
    throw new Error(`${owner}: missing or invalid Playwright JSON report`);
  }
  if (!Array.isArray(report.errors) || report.errors.length) {
    throw new Error(`${owner}: runner errors cannot count as a mutation kill`);
  }
  const specs = [];
  function visit(suite) {
    specs.push(...(suite.specs ?? []));
    for (const child of suite.suites ?? []) visit(child);
  }
  for (const suite of report.suites ?? []) visit(suite);
  // Playwright's JSON locations are relative to testDir (e2e/).
  if (specs.length !== 1 || specs[0].title !== owner || specs[0].file !== 'claims.spec.ts') {
    throw new Error(`${owner}: expected exactly the named owning test`);
  }
  const tests = specs[0].tests ?? [];
  if (tests.length !== 1 || tests[0].expectedStatus !== 'passed' || tests[0].results?.length !== 1) {
    throw new Error(`${owner}: skipped, expected-failure, repeated, or retried tests are invalid`);
  }
  const observed = tests[0].results[0];
  const expectedStatus = shouldPass ? 'passed' : 'failed';
  if (observed.status !== expectedStatus || observed.retry !== 0 || result.status !== (shouldPass ? 0 : 1)) {
    throw new Error(`${owner}: expected ${expectedStatus}, observed ${observed.status}, exit ${result.status}`);
  }
  const errors = observed.errors ?? (observed.error ? [observed.error] : []);
  if (shouldPass) {
    if (errors.length) throw new Error(`${owner}: passing test reported errors`);
    return;
  }
  if (errors.length !== 1) throw new Error(`${owner}: expected exactly one owning assertion failure`);
  const failure = [observed.error?.message, observed.error?.stack, errors[0].message, errors[0].stack].filter(Boolean).join('\n');
  if (!/expect\(|AssertionError/.test(failure) || !/claims\.spec\.ts:\d+:\d+/.test(failure) ||
      /No tests found|browserType\.launch|browser has been closed|Target (?:page|browser|context).*closed|net::ERR_|Test timeout of|page\.goto:|locator\.(?:click|check|uncheck):|waiting for.*web server|at (?:setupExtensionBase|extendAndCheck|runProtocol)\b|page must raise no uncaught exceptions/i.test(failure)) {
    throw new Error(`${owner}: infrastructure, setup, runtime, or non-assertion failure cannot count as a mutation kill`);
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validateNamedRun } from './mutation-report.mjs';

const owner = 'rendered chosen-message count';
function fixture(passing = false) {
  return {
    status: passing ? 0 : 1, signal: null,
    stdout: JSON.stringify({
      errors: [], suites: [{ suites: [{ specs: [{ title: owner, file: 'claims.spec.ts', tests: [{
        expectedStatus: 'passed', results: [{ status: passing ? 'passed' : 'failed', retry: 0,
          errors: passing ? [] : [{ message: 'Error: expect(received).toBe(expected)\nExpected: 1000\nReceived: 0', stack: 'at /repo/e2e/claims.spec.ts:510:20' }],
        }],
      }] }] }] }],
    }),
  };
}
function editReport(change) {
  const result = fixture();
  const report = JSON.parse(result.stdout);
  change(report, report.suites[0].suites[0].specs[0]);
  result.stdout = JSON.stringify(report);
  return result;
}

test('accepts a single ordinary assertion failure and its restored green run', () => {
  validateNamedRun(fixture(), owner, false);
  validateNamedRun(fixture(true), owner, true);
  const result = editReport((r, s) => {
    const observed = s.tests[0].results[0];
    observed.error = observed.errors[0];
    observed.errors = [{ message: 'formatted assertion details' }];
  });
  validateNamedRun(result, owner, false);
});
test('rejects missing tests and malformed reports', () => {
  assert.throws(() => validateNamedRun({ ...fixture(), stdout: 'No tests found' }, owner, false));
  assert.throws(() => validateNamedRun(editReport((r) => { r.suites = []; }), owner, false));
});
test('rejects signals, spawn errors, timeouts and inconsistent exits', () => {
  for (const patch of [{ status: null, signal: 'SIGTERM' }, { error: new Error('ETIMEDOUT') }, { status: 2 }, { status: 0 }]) {
    assert.throws(() => validateNamedRun({ ...fixture(), ...patch }, owner, false));
  }
  assert.throws(() => validateNamedRun(editReport((r, s) => { s.tests[0].results[0].status = 'timedOut'; }), owner, false));
});
test('rejects infrastructure and setup errors even inside a selected test', () => {
  for (const message of ['browserType.launch: Target page, context or browser has been closed',
    'Error: expect(received).toBe(expected) at setupExtensionBase (/repo/e2e/claims.spec.ts:480:3)',
    'Test timeout of 30000ms exceeded', 'locator.click: Timeout 30000ms exceeded',
    'Error: expect(errors).toEqual([]): page must raise no uncaught exceptions', 'net::ERR_CONNECTION_REFUSED']) {
    const result = editReport((r, s) => { s.tests[0].results[0].errors[0].message = message; });
    assert.throws(() => validateNamedRun(result, owner, false));
  }
});
test('rejects a different owner, multiple tests, retry, skip and expected failure', () => {
  for (const change of [
    (r, s) => { s.title = 'another test'; },
    (r, s) => { s.file = 'e2e/other.spec.ts'; },
    (r, s) => { s.tests.push(structuredClone(s.tests[0])); },
    (r, s) => { s.tests[0].results.push(structuredClone(s.tests[0].results[0])); },
    (r, s) => { s.tests[0].results[0].retry = 1; },
    (r, s) => { s.tests[0].results[0].status = 'skipped'; },
    (r, s) => { s.tests[0].expectedStatus = 'failed'; },
    (r, s) => { r.errors.push({ message: 'web server failed' }); },
  ]) assert.throws(() => validateNamedRun(editReport(change), owner, false));
});
test('rejects an unexpected green mutant and an assertion in a restored run', () => {
  assert.throws(() => validateNamedRun(fixture(true), owner, false));
  assert.throws(() => validateNamedRun(fixture(), owner, true));
});

