function run(command, args, timeout = 900_000, env = process.env) {
  const result = spawnSync(command, args, {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
    timeout,
    env,
  });
  if (result.error || result.signal || !Number.isInteger(result.status)) {
    throw new Error(
      `${command}: process did not exit normally (${result.error?.message ?? result.signal ?? 'no exit status'})`,
    );
  }
  const stdout = result.stdout ?? '';
  const stderr = result.stderr ?? '';
  return { code: result.status, stdout, stderr, output: `${stdout}${stderr}` };
}

const INFRASTRUCTURE_MARKERS = [
  'Cannot find module',
  'ERR_MODULE_NOT_FOUND',
  'SyntaxError',
  'ReferenceError',
];

function rejectInfrastructureFailure(name, output) {
  for (const marker of INFRASTRUCTURE_MARKERS) {
    if (output.includes(marker)) {
      throw new Error(
        `${name}: "${marker}" is an infrastructure failure, not a mutation kill\n${output.slice(0, 2000)}`,
      );
    }
  }
}

/** Run exactly the one named pure check and insist the result is unambiguous. */
function namedPureCheck(mutation, shouldPass) {
  const result = run('npx', ['tsx', CHECKS, '--only', mutation.check]);
  const total = Number(/^# checks (\d+)$/m.exec(result.output)?.[1] ?? -1);
  const pass = Number(/^# pass (\d+)$/m.exec(result.output)?.[1] ?? -1);
  const fail = Number(/^# fail (\d+)$/m.exec(result.output)?.[1] ?? -1);
  rejectInfrastructureFailure(mutation.name, result.output);
  if (total !== 1) {
    throw new Error(
      `${mutation.name}: expected exactly one check named ${JSON.stringify(mutation.check)}, the runner reported ${total}`,
    );
  }
  if (shouldPass) {
    if (result.code !== 0 || pass !== 1 || fail !== 0) {
      throw new Error(
        `${mutation.name}: expected a green baseline, got exit ${result.code} pass ${pass} fail ${fail}\n${result.output}`,
      );
    }
    return;
  }
  if (result.code === 0 || fail !== 1 || pass !== 0) {
    throw new Error(
      `${mutation.name}: the mutation SURVIVED (exit ${result.code}, pass ${pass}, fail ${fail})\n${result.output.slice(0, 2000)}`,
    );
  }
  if (!/^# error code ERR_ASSERTION$/m.test(result.output)) {
    throw new Error(
      `${mutation.name}: the owning check went red without an assertion failure, which cannot count as a kill\n${result.output.slice(0, 2000)}`,
    );
  }
}

/** Hash of the built bundle, so a mutation the build never picked up is visible. */
function bundleDigest() {
  const dir = 'dist/assets';
  let names;
  try {
    names = readdirSync(dir).sort();
  } catch {
    return 'NO-DIST';
  }
  const hash = createHash('sha256');
  for (const name of names) {
    hash.update(name);
    hash.update(readFileSync(join(dir, name)));
  }
  return hash.digest('hex');
}

/**
 * Run exactly the one named browser test against a freshly built bundle.
 *
 * `vite build` is run HERE rather than left to Playwright's webServer, because
 * locally `reuseExistingServer` means Playwright may attach to a preview server
 * that is already up and never rebuild -- which would test the unmutated bundle
 * and read as "the mutation was not caught".
 */
function namedBrowserCheck(mutation, shouldPass) {
  const build = run('npx', ['tsc', '--noEmit']);
  if (build.code !== 0) {
    throw new Error(`${mutation.name}: type check failed\n${build.output.slice(0, 2000)}`);
  }
  const bundle = run('npx', ['vite', 'build']);
  if (bundle.code !== 0) {
    throw new Error(`${mutation.name}: vite build failed\n${bundle.output.slice(0, 2000)}`);
  }
  const digest = bundleDigest();

  const result = run('npx', [
    'playwright',
    'test',
    '--config',
    'playwright.config.ts',
    '-g',
    mutation.check,
    '--reporter',
    'line',
  ]);
  rejectInfrastructureFailure(mutation.name, result.output);
  if (/0 tests? (?:ran|found)|No tests found/i.test(result.output)) {
    throw new Error(`${mutation.name}: no browser test matched ${JSON.stringify(mutation.check)}`);
  }
  if (shouldPass) {
    if (result.code !== 0 || !/\b1 passed\b/.test(result.output) || /\b1 failed\b/.test(result.output)) {
      throw new Error(`${mutation.name}: expected a green browser baseline\n${result.output.slice(0, 3000)}`);
    }
  } else {
    if (result.code === 0) {
      throw new Error(`${mutation.name}: the mutation SURVIVED its browser test\n${result.output.slice(0, 3000)}`);
    }
    if (!/\b1 failed\b/.test(result.output) || !result.output.includes(mutation.check)) {
      throw new Error(
        `${mutation.name}: the named browser test did not fail exactly once\n${result.output.slice(0, 3000)}`,
      );
    }
    if (!/Error: expect\(/.test(result.output)) {
      throw new Error(
        `${mutation.name}: browser run went red without a Playwright assertion failure\n${result.output.slice(0, 3000)}`,
      );
    }
  }
  return digest;
}

const digestOf = (text) => createHash('sha256').update(text).digest('hex');

const requested = process.argv[2];
const selected = requested ? mutations.filter((m) => m.name === requested) : mutations;
if (selected.length === 0) {
  console.error(`Unknown mutation: ${requested}`);
  process.exit(2);
}

for (const file of [KNAPSACK, MAIN, CHECKS, UI_SPEC]) {
  if (run('git', ['status', '--porcelain', '--', file]).output.trim()) {
    throw new Error(
      `${file} has an existing working-tree change. Preserve or deliberately restore it before ` +
        'replaying mutations; this harness will not overwrite unrelated work.',
    );
  }
}

let killed = 0;
for (const mutation of selected) {
  const original = readFileSync(mutation.file, 'utf8');
  const originalDigest = digestOf(original);
  if (original.split(mutation.anchor).length !== 2) {
    throw new Error(`${mutation.name}: its anchor must occur exactly once in ${mutation.file}`);
  }

  if (mutation.kind === 'pure') namedPureCheck(mutation, true);
  else namedBrowserCheck(mutation, true);
  console.log(`[${mutation.name}]`);
  console.log(`  1/6 baseline GREEN: ${mutation.check}`);

  let bundleBefore = null;
  let bundleAfter = null;
  try {
    const changed = original.replace(mutation.anchor, mutation.replacement);
    if (changed === original) throw new Error(`${mutation.name}: the patch changed nothing`);
    if (mutation.kind === 'ui') bundleBefore = bundleDigest();
    writeFileSync(mutation.file, changed);

    const diff = run('git', ['diff', '--no-ext-diff', '--', mutation.file], 120_000);
    const changedLines = diff.output.split('\n').filter((l) => /^[+-][^+-]/.test(l)).length;
    if (diff.code !== 0 || changedLines === 0) {
      throw new Error(`${mutation.name}: the source diff was empty`);
    }
    console.log(`  2/6 source diff NON-EMPTY (${changedLines} changed lines in ${mutation.file})`);

    if (mutation.kind === 'pure') {
      namedPureCheck(mutation, false);
    } else {
      bundleAfter = namedBrowserCheck(mutation, false);
      if (bundleBefore !== null && bundleAfter === bundleBefore) {
        throw new Error(
          `${mutation.name}: the built bundle hash did not move, so the browser test ran against ` +
            'unmutated code and proves nothing',
        );
      }
      console.log('  2b/6 built bundle hash MOVED, so the browser really ran the mutated code');
    }
    console.log('  3/6 owning check RED');
    console.log(
      mutation.kind === 'pure'
        ? '  4/6 red on ERR_ASSERTION, with exactly one check matched'
        : '  4/6 exactly one named browser test failed on a Playwright assertion',
    );
  } finally {
    writeFileSync(mutation.file, original);
  }

  if (digestOf(readFileSync(mutation.file, 'utf8')) !== originalDigest) {
    throw new Error(`${mutation.name}: the restored source differs from the original`);
  }
  console.log('  5/6 source restored BYTE FOR BYTE');

  if (mutation.kind === 'pure') namedPureCheck(mutation, true);
  else namedBrowserCheck(mutation, true);
  console.log('  6/6 clean control GREEN again after restoration');
  killed += 1;
}

console.log('');
console.log(`BASELINE PASSED for all ${selected.length} mutations.`);
console.log(`ALL MUTATIONS CAUGHT: ${killed} of ${selected.length} killed by their own named checks.`);
if (killed !== selected.length) process.exit(1);

import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';

// Local constrained environments can supply a browser config without changing
// the committed CI browser version or removing any assertion.
const config = process.env.AEGIS_PLAYWRIGHT_CONFIG;
const args = ['playwright', 'test', 'e2e/commitment.spec.ts', '--workers=1', '--retries=0', ...(config ? ['--config', config] : [])];
const run = (cmd, argv) => spawnSync(cmd, argv, { encoding: 'utf8', env: { ...process.env, CI: '1' }, timeout: 180000 });
const build = () => {
  const r = run('npm', ['run', 'build']);
  if (r.status !== 0) throw new Error(`DOES NOT BUILD\n${r.stdout}\n${r.stderr}`);
  const hash = createHash('sha256');
  for (const f of readdirSync('dist/assets').filter(f => f.endsWith('.js')).sort()) hash.update(readFileSync(`dist/assets/${f}`));
  return hash.digest('hex');
};
const cases = [
  ['second authentication verdict', 'src/commitment.ts', 'const acceptedB = openedB !== null;', 'const acceptedB = openedB === null;'],
  ['state difference trace', 'src/commitment.ts', 'return sum;', 'return sum + 1;'],
  ['negative claim', 'src/commitment-ui.ts', 'key commitment failed for these two different key/AD contexts', 'a unique key was established'],
];
const baselineHash = build();
const baseline = run('npx', args);
if (baseline.status !== 0 || !/2 passed/.test(baseline.stdout)) throw new Error(`Baseline must pass both owning tests\n${baseline.stdout}\n${baseline.stderr}`);
console.log('Baseline: 2 owning tests passed');
for (const [name, path, from, to] of cases) {
  const original = readFileSync(path, 'utf8');
  if (original.split(from).length !== 2) throw new Error(`Non-unique mutation anchor: ${name}`);
  try {
    writeFileSync(path, original.replace(from, to));
    if (build() === baselineHash) throw new Error(`Bundle did not change: ${name}`);
    const r = run('npx', args);
    const log = `${r.stdout}\n${r.stderr}`;
    if (r.status !== 1 || !/[1-9]\d* failed/.test(log) || !/expect\(/.test(log) || /was not able to start|ERR_CONNECTION|Executable doesn't exist|browserType.launch/.test(log)) {
      throw new Error(`Not an assertion kill: ${name}\n${log}`);
    }
    console.log(`KILLED: ${name}`);
  } finally {
    writeFileSync(path, original);
    if (build() !== baselineHash) throw new Error(`Restored bundle differs: ${name}`);
  }
}
console.log('3/3 mutations killed; source and bundle restored');

/**
 * Ascon state: 5 x 64-bit words.
 * BigInt is required because JavaScript numbers lose precision above 2^53.
 */
export type AsconState = [bigint, bigint, bigint, bigint, bigint];

export const MASK64 = (1n << 64n) - 1n;

/**
 * Round constants (NIST SP 800-232 Table 5).
 * p12 uses indices 0..11
 * p8 uses indices 4..11
 * p6 uses indices 6..11
 */
export const ROUND_CONSTANTS: bigint[] = [
  0xf0n,
  0xe1n,
  0xd2n,
  0xc3n,
  0xb4n,
  0xa5n,
  0x96n,
  0x87n,
  0x78n,
  0x69n,
  0x5an,
  0x4bn,
];

/**
 * 64-bit circular right rotation.
 */
export function rotr64(x: bigint, n: number): bigint {
  const m = BigInt(n % 64);
  if (m === 0n) {
    return x & MASK64;
  }
  return ((x >> m) | (x << (64n - m))) & MASK64;
}

/**
 * Add round constant to x2.
 */
export function addConstant(state: AsconState, c: bigint): AsconState {
  return [state[0], state[1], (state[2] ^ c) & MASK64, state[3], state[4]];
}

/**
 * 5-bit S-box, bit-sliced across 64 parallel lanes.
 * NIST SP 800-232 Section 3.2.
 */
export function sbox(state: AsconState): AsconState {
  let [x0, x1, x2, x3, x4] = state;

  x0 ^= x4;
  x4 ^= x3;
  x2 ^= x1;

  const t0 = x0 ^ ((~x1 & MASK64) & x2);
  const t1 = x1 ^ ((~x2 & MASK64) & x3);
  const t2 = x2 ^ ((~x3 & MASK64) & x4);
  const t3 = x3 ^ ((~x4 & MASK64) & x0);
  const t4 = x4 ^ ((~x0 & MASK64) & x1);

  x0 = t0 & MASK64;
  x1 = t1 & MASK64;
  x2 = t2 & MASK64;
  x3 = t3 & MASK64;
  x4 = t4 & MASK64;

  x1 ^= x0;
  x0 ^= x4;
  x3 ^= x2;
  x2 = (~x2) & MASK64;

  return [x0 & MASK64, x1 & MASK64, x2 & MASK64, x3 & MASK64, x4 & MASK64];
}

/**
 * Linear diffusion layer.
 */
export function diffusion(state: AsconState): AsconState {
  const [x0, x1, x2, x3, x4] = state;
  return [
    (x0 ^ rotr64(x0, 19) ^ rotr64(x0, 28)) & MASK64,
    (x1 ^ rotr64(x1, 61) ^ rotr64(x1, 39)) & MASK64,
    (x2 ^ rotr64(x2, 1) ^ rotr64(x2, 6)) & MASK64,
    (x3 ^ rotr64(x3, 10) ^ rotr64(x3, 17)) & MASK64,
    (x4 ^ rotr64(x4, 7) ^ rotr64(x4, 41)) & MASK64,
  ];
}

/**
 * One round: add constant, S-box, diffusion.
 */
export function round(state: AsconState, c: bigint): AsconState {
  return diffusion(sbox(addConstant(state, c)));
}

/**
 * p12 - 12 rounds (init and finalization).
 */
export function p12(state: AsconState): AsconState {
  let s = state;
  for (let i = 0; i < 12; i += 1) {
    s = round(s, ROUND_CONSTANTS[i]);
  }
  return s;
}

/**
 * p8 - 8 rounds. Used by Ascon-AEAD128 for the associated-data and
 * plaintext/ciphertext phases. (Ascon-Hash256 and Ascon-XOF128 use p12
 * throughout - see hash.ts / xof.ts.)
 */
export function p8(state: AsconState): AsconState {
  let s = state;
  for (let i = 4; i < 12; i += 1) {
    s = round(s, ROUND_CONSTANTS[i]);
  }
  return s;
}

/**
 * p6 - 6 rounds. Not used by any algorithm in this demo: the data phase of
 * the older Ascon-128 v1.2 submission ran 6 rounds, but the standardized
 * Ascon-AEAD128 of NIST SP 800-232 uses p8 there. Kept only so the
 * permutation module is complete and the round-count difference between the
 * competition candidate and the final standard is inspectable.
 */
export function p6(state: AsconState): AsconState {
  let s = state;
  for (let i = 6; i < 12; i += 1) {
    s = round(s, ROUND_CONSTANTS[i]);
  }
  return s;
}

import { describe, expect, it } from 'vitest';

import { p12, p6, p8, type AsconState } from '../src/permutation';

function stateToHex(state: AsconState): string {
  return state.map((w) => w.toString(16).padStart(16, '0')).join('');
}

describe('Ascon permutation', () => {
  it('p12(zero state) matches official reference output', () => {
    const zeroState: AsconState = [0n, 0n, 0n, 0n, 0n];

    // Reference computed with the official ascon-c reference ROUND implementation.
    // Source equations: https://github.com/ascon/ascon-c/blob/main/crypto_aead/asconaead128/ref/round.h
    const expected =
      '78ea7ae5cfebb1089b9bfb8513b560f76937f83e03d11a503fe53f36f2c1178c045d648e4def12c9';

    expect(stateToHex(p12(zeroState))).toBe(expected);
  });

  it('p8 and p6 produce deterministic outputs', () => {
    const input: AsconState = [
      0x0123456789abcdefn,
      0xfedcba9876543210n,
      0x0011223344556677n,
      0x8899aabbccddeeffn,
      0x0f1e2d3c4b5a6978n,
    ];

    const p8a = p8(input);
    const p8b = p8(input);
    const p6a = p6(input);
    const p6b = p6(input);

    expect(p8a).toEqual(p8b);
    expect(p6a).toEqual(p6b);
  });
});

