#!/usr/bin/env node
/**
 * Build verification/manifest.yaml from verification/claims.mjs.
 *
 * The manifest has hard structural rules — claims sorted by file, symbol and line with
 * sequential ids; every snippet a literal substring of the file it anchors to; coverage
 * accounting for every symbol the validator's own regex finds. Those are mechanical, and
 * a mechanical rule enforced by hand drifts. So the substance lives in claims.mjs and the
 * structure is assembled here, which also means the manifest can be regenerated and
 * diffed to prove it has not been edited into disagreement with the code.
 *
 * Usage:
 *   node verification/tools/build-manifest.mjs          write the manifest
 *   node verification/tools/build-manifest.mjs --check  fail if it would change
 */

import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
const MANIFEST_PATH = join(ROOT, 'verification', 'manifest.yaml');

const { LAB, MATH_CORE, OTHER_FILES, PARAMETERS, CLAIMS, DEVIATIONS, OPEN_QUESTIONS,
  CRYPTOGRAPHER_CHECKLIST, REFERENCE_PACK, AUDIT_MODE, EXTRACTION } =
  await import(join(ROOT, 'verification', 'claims.mjs'));

/** The validator's own symbol regex, reproduced so coverage cannot drift from it. */
const SYMBOL_RE = /(?:function|class)\s+([A-Za-z0-9_]+)|(?:const|let|var)\s+([A-Za-z0-9_]+)\s*=/g;

function symbolsIn(source) {
  const found = new Set();
  let match;
  SYMBOL_RE.lastIndex = 0;
  while ((match = SYMBOL_RE.exec(source))) {
    if (match[1]) found.add(match[1]);
    if (match[2]) found.add(match[2]);
  }
  return [...found].sort();
}

const sources = new Map();
for (const path of MATH_CORE) sources.set(path, readFileSync(join(ROOT, path), 'utf8'));

// ── validate the definitions before emitting anything ───────────────────────────
const problems = [];
for (const claim of CLAIMS) {
  const source = sources.get(claim.file);
  if (!source) {
    problems.push(`${claim.symbol}: ${claim.file} is not declared as math_core`);
    continue;
  }
  if (!source.includes(claim.snippet)) {
    problems.push(`${claim.symbol}: snippet is not a literal substring of ${claim.file}`);
  }
  const line = source.split('\n').findIndex((text) => text.includes(claim.snippet.split('\n')[0]));
  if (line >= 0) claim.resolvedLine = line + 1;
  else problems.push(`${claim.symbol}: could not locate the snippet's first line`);
}
if (problems.length) {
  console.error('claim definitions are inconsistent with the source:');
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exit(1);
}

// ── canonical ordering: file, then symbol, then first line ──────────────────────
const ordered = [...CLAIMS].sort((a, b) =>
  a.file < b.file ? -1 : a.file > b.file ? 1
    : a.symbol < b.symbol ? -1 : a.symbol > b.symbol ? 1
      : a.resolvedLine - b.resolvedLine);

const claimIds = new Map();
ordered.forEach((claim, index) => claimIds.set(claim.key, `C${index + 1}`));

// ── coverage: every symbol the validator will find, accounted for ───────────────
const coverage = MATH_CORE.map((path) => {
  const source = sources.get(path);
  const all = symbolsIn(source);
  const reviewed = ordered.filter((claim) => claim.file === path).map((claim) => claim.symbol);
  const reviewedSet = new Set(reviewed);
  const excluded = all.filter((symbol) => !reviewedSet.has(symbol));
  return {
    file: path,
    reviewed_symbols: [...new Set(reviewed)].sort(),
    excluded_symbols: excluded,
    unresolved_regions: [],
    note: excluded.length
      ? 'excluded_symbols are local bindings and helpers reached through the reviewed '
        + 'entry points; they carry no independent claim of their own'
      : '',
  };
});

// extraction_hash is left PENDING: the validator is authoritative for it, and a value
// written here by the same pass that wrote the claims would be checking itself.
const extractionHash = 'PENDING';

const manifest = {
  manifest_version: '0.2',
  lab: LAB,
  repository: {
    url: 'https://github.com/systemslibrarian/crypto-lab-token-tell',
    default_branch: 'main',
    commit_sha: process.env.TOKEN_TELL_COMMIT_SHA ?? EXTRACTION.commit_sha,
  },
  extraction: { ...EXTRACTION.extraction, extraction_hash: extractionHash },
  audit_mode: AUDIT_MODE,
  reference_pack: REFERENCE_PACK,
  scope_map: {
    files: [
      ...MATH_CORE.map((path) => ({ path, role: 'math_core', note: '' })),
      ...OTHER_FILES,
    ],
    entry_points: ['src/main.ts'],
    extraction_order: MATH_CORE,
    red_flags: [],
    scope_amendments: [],
  },
  coverage,
  parameters: PARAMETERS,
  claims: ordered.map((claim) => ({
    id: claimIds.get(claim.key),
    type: claim.type,
    statement: claim.statement,
    latex: claim.latex ?? '',
    ...(claim.computable ? { computable: claim.computable } : {}),
    code_anchor: {
      file: claim.file,
      symbol: claim.symbol,
      lines: [claim.resolvedLine, claim.resolvedLine + claim.snippet.split('\n').length - 1],
      snippet: claim.snippet,
    },
    reference_anchor: claim.reference_anchor,
    verification: claim.verification,
    implementation_provenance: claim.implementation_provenance,
    depends_on: (claim.depends_on ?? []).map((key) => claimIds.get(key) ?? key),
    extractor_confidence: claim.extractor_confidence,
    extraction_status: claim.extraction_status,
    verification_status: claim.verification_status,
    conformance_status: claim.conformance_status,
    notes: claim.notes ?? '',
  })),
  deviations: DEVIATIONS,
  open_questions: OPEN_QUESTIONS,
  cryptographer_checklist: CRYPTOGRAPHER_CHECKLIST,
};

// ── emit YAML (a small, explicit writer: no dependency, no surprises) ───────────
// The array branch used to run `.replace(/\n/g, '\n')` before slicing, which replaces
// every newline with itself. CodeQL named it — js/identity-replacement, medium,
// 2026-10-28 — and it was dead rather than mistaken: the first line's indent is what
// has to change, and the `^<indent+2 spaces>` replacement below is what changes it.
// Removing it leaves the generated manifest byte-identical, which `--check` proves.
function yaml(value, indent = 0) {
  const pad = ' '.repeat(indent);
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) {
    if (!value.length) return ' []';
    return `\n${value.map((item) => {
      const rendered = yaml(item, indent + 2);
      return rendered.startsWith('\n')
        ? `${pad}-${rendered.slice(1).replace(new RegExp(`^${' '.repeat(indent + 2)}`), ' ')}`
        : `${pad}-${rendered}`;
    }).join('\n')}`;
  }
  if (typeof value === 'object') {
    const entries = Object.entries(value);
    if (!entries.length) return ' {}';
    return `\n${entries.map(([key, entry]) =>
      `${pad}${key}:${yaml(entry, indent + 2)}`).join('\n')}`;
  }
  if (typeof value === 'string') {
    // Always a double-quoted scalar, even for multi-line values. A block scalar would be
    // friendlier to read, but its indentation is inferred from the first line, and these
    // strings are code snippets whose leading whitespace is load-bearing: the validator
    // checks each one is a literal substring of the file it anchors to, so a single eaten
    // space is a failed check.
    return ` ${JSON.stringify(value)}`;
  }
  return ` ${JSON.stringify(value)}`;
}

const header = `# Verification manifest for crypto-lab-token-tell.
#
# GENERATED by verification/tools/build-manifest.mjs from verification/claims.mjs.
# Do not edit this file by hand: run the builder, and CI re-runs it with --check so an
# edit here that disagrees with the code cannot land.
#
# extraction_hash is PENDING on purpose. The validator computes it from the math_core
# contents and is authoritative for it; a value written by the same pass that wrote the
# claims would be marking its own homework.
`;

const body = Object.entries(manifest)
  .map(([key, value]) => `${key}:${yaml(value, 2)}`)
  .join('\n');
const output = `${header}${body}\n`;

if (process.argv.includes('--check')) {
  const existing = readFileSync(MANIFEST_PATH, 'utf8');
  if (existing !== output) {
    console.error('verification/manifest.yaml is out of date — run '
      + 'node verification/tools/build-manifest.mjs');
    process.exit(1);
  }
  console.log(`manifest is in sync (${manifest.claims.length} claims, `
    + `${manifest.open_questions.length} open questions)`);
} else {
  writeFileSync(MANIFEST_PATH, output, 'utf8');
  const mathCoreContent = MATH_CORE.slice().sort().map((path) => sources.get(path)).join('');
  console.log(`wrote verification/manifest.yaml — ${manifest.claims.length} claims, `
    + `${manifest.open_questions.length} open questions`);
  console.log('extraction_hash the validator will compute: '
    + createHash('sha256').update(mathCoreContent).digest('hex'));
}

#!/usr/bin/env node
/**
 * Evaluate every computable claim's own expression and compare it to the value published
 * beside it.
 *
 * Reads: verification/manifest.yaml (generated from verification/claims.mjs).
 * Prevents: a published figure that its own stated expression does not produce.
 *
 * WHY THIS EXISTS. The manifest carries 25 `computable` blocks: a language, an
 * expression, and an `expected` value. `validate-manifest.mjs` checks that the BLOCK is
 * present for the claim types that need one. Nothing evaluated the expression. So the
 * expressions were prose sitting next to numbers, and on 2026-11-05 three of the
 * nineteen python ones disagreed with the value published beside them -- including C18,
 * whose published 2951479051793528132 is not the value of its expression under any input
 * or multiplier (its expression, its LaTeX, its statement and the code it anchors to all
 * give 7844292295230488766).
 *
 * WHAT IS CHECKED. The `python` claims, by running each expression in python3 -- the
 * language the claim itself declares, rather than a reimplementation of it. Integers must
 * match EXACTLY, including the decimal-string encoding the manifest uses for values a
 * double cannot hold. Floats must agree to 1e-12 relative, which is loose enough for the
 * last-bit differences a cross-language float computation produces and far tighter than
 * any real discrepancy (the two open ones below are 1.7e-7 and 1.5e-4).
 *
 * WHAT IS NOT. The six `javascript` claims are statement lists whose value is their
 * completion value, which only `eval` returns -- and an eval over file content is a
 * code-injection sink this fleet will not add to a repository under CodeQL. They are
 * printed as NOT EVALUATED, by id, so the gap is named rather than silent. Each asserts a
 * boolean or a JSON shape that its own unit tests cover.
 */

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const yaml = require('js-yaml');

const HERE = dirname(fileURLToPath(import.meta.url));
const MANIFEST_PATH = join(HERE, '..', 'manifest.yaml');
const SCRATCH = join(tmpdir(), 'token-tell-claim-expression.py');

/** Relative tolerance for non-integer expected values. See the header. */
const FLOAT_TOLERANCE = 1e-12;

/**
 * Claims whose published value its own expression does not produce, left as they are
 * because correcting them is a decision about published evidence rather than a
 * transcription fix: for each, the number corresponds to no integer count in the
 * expression, so either the literals or the measurement is the authoritative one, and
 * only the person who ran it can say which.
 *
 * Each entry must STILL disagree. If one starts agreeing, this file fails too: a list of
 * known exceptions that nobody re-reads is how a fixed defect goes on being excused.
 */
/*
 * Two published figures that no integer input reproduces. The decision, 2026-11-05, is
 * NOT to chase the paper's arithmetic: the code keeps the exact expression and the
 * manifest labels the published figure as published, with the gap in that claim's own
 * `notes`. These entries stay so the discrepancy is declared rather than silently
 * tolerated -- and the stale-entry guard below still fails the run if either ever starts
 * agreeing, which is what stops a quiet reconciliation.
 */
const KNOWN_UNRESOLVED = {
  C15: 'published 0.005253784205889284, expression gives 0.005252981913594169 '
    + '(1.5e-4 relative; the published value implies a count of 9057.23, and no integer '
    + 'count reproduces it -- see the claim notes in verification/manifest.yaml)',
  C27: 'published 0.6037528604118994, expression gives 0.6037527593818984 '
    + '(1.7e-7 relative; the published value implies a denominator of 9059.9985, and is '
    + 'not a float-accumulation artefact -- see the claim notes in verification/manifest.yaml)'
};

function blocks() {
  const manifest = yaml.load(readFileSync(MANIFEST_PATH, 'utf8'));
  const out = [];
  for (const claim of manifest.claims ?? []) {
    if (claim.computable) out.push({ id: claim.id, computable: claim.computable });
  }
  for (const parameter of manifest.parameters ?? []) {
    if (parameter.computable) out.push({ id: `parameter:${parameter.name}`, computable: parameter.computable });
  }
  return out;
}

/** Run one expression in the language it declares. The expression is repo-owned. */
function evaluatePython(expression) {
  writeFileSync(SCRATCH, `print(repr((${expression})))\n`, 'utf8');
  return execFileSync('python3', [SCRATCH], { encoding: 'utf8' }).trim();
}

function agrees(expected, computed) {
  const wantedText = String(expected).replace(/^"|"$/g, '');
  if (/^-?\d+$/.test(wantedText) && /^-?\d+$/.test(computed)) {
    // Exact, always: this is the case a double silently rounds, which is why the
    // manifest encodes these as decimal strings in the first place.
    return wantedText === computed;
  }
  const wanted = Number(wantedText);
  const got = Number(computed);
  if (!Number.isFinite(wanted) || !Number.isFinite(got)) return wantedText === computed;
  return Math.abs(got - wanted) <= FLOAT_TOLERANCE * Math.max(Math.abs(wanted), Number.MIN_VALUE);
}

const failures = [];
const notEvaluated = [];
let checked = 0;
let excused = 0;

for (const { id, computable } of blocks()) {
  if (computable.language !== 'python') {
    notEvaluated.push(`${id} (${computable.language})`);
    continue;
  }
  let computed;
  try {
    computed = evaluatePython(computable.expression);
  } catch (error) {
    failures.push(`${id}: its expression did not evaluate — ${error instanceof Error ? error.message.split('\n')[0] : String(error)}`);
    continue;
  }
  const ok = agrees(computable.expected, computed);
  const known = Object.hasOwn(KNOWN_UNRESOLVED, id);
  if (ok && known) {
    failures.push(`${id}: now AGREES with its expression, so its KNOWN_UNRESOLVED entry is stale — delete it. ${KNOWN_UNRESOLVED[id]}`);
    continue;
  }
  if (ok) {
    checked += 1;
    continue;
  }
  if (known) {
    excused += 1;
    console.log(`UNRESOLVED ${id} — ${KNOWN_UNRESOLVED[id]}`);
    continue;
  }
  failures.push(
    `${id}: published ${JSON.stringify(computable.expected)}, its own expression gives ${computed}\n`
      + `        ${computable.expression}`
  );
}

if (notEvaluated.length) {
  console.log(`NOT EVALUATED (${notEvaluated.length}) — a completion value needs eval, which this repo will not add: ${notEvaluated.join(', ')}`);
}

if (failures.length) {
  console.error(`\n${failures.length} computable claim(s) disagree with their own expressions:`);
  for (const failure of failures) console.error(`  ${failure}`);
  process.exit(1);
}

console.log(`${checked} computable claims agree with their own expressions`
  + `${excused ? `, ${excused} recorded as unresolved above` : ''}`);

// Vendored from systemslibrarian/crypto-lab (tools/validate-manifest.mjs) so this lab's
// CI can validate its own manifest without a checkout of the catalog beside it. The only
// change is where the schema is resolved from: the catalog copy lives at
// <catalog>/verification/schema.json, and this lab carries its own copy at
// verification/schema.json. Everything else, including every cross-check, is verbatim.
import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const yaml = require('js-yaml');
const Ajv = require('ajv');

const ajv = new Ajv({ allErrors: true });

function getFilesRecursively(dir) {
  let results = [];
  if (!fs.existsSync(dir)) return results;
  const list = fs.readdirSync(dir);
  list.forEach((file) => {
    const fileBase = path.join(dir, file);
    const stat = fs.statSync(fileBase);
    if (stat && stat.isDirectory()) {
      results = results.concat(getFilesRecursively(fileBase));
    } else {
      results.push(fileBase);
    }
  });
  return results;
}

function extractSymbols(code) {
  const symbols = new Set();
  const re = /(?:function|class)\s+([A-Za-z0-9_]+)|(?:const|let|var)\s+([A-Za-z0-9_]+)\s*=/g;
  let m;
  while ((m = re.exec(code))) {
    if (m[1]) symbols.add(m[1]);
    if (m[2]) symbols.add(m[2]);
  }
  return symbols;
}

function validateManifest(manifestPath, labDir, catalogDir) {
  let manifestObj;
  try {
    const raw = fs.readFileSync(manifestPath, 'utf8');
    manifestObj = yaml.load(raw);
  } catch (err) {
    console.error(`Failed to read or parse manifest: ${err.message}`);
    return 1;
  }

  const schemaPath = path.join(catalogDir, 'verification', 'schema.json');
  let schemaObj;
  try {
    schemaObj = JSON.parse(fs.readFileSync(schemaPath, 'utf8'));
  } catch (err) {
    console.error(`Failed to read schema: ${err.message}`);
    return 1;
  }

  const validate = ajv.compile(schemaObj);
  const valid = validate(manifestObj);
  let hasError = false;

  if (!valid) {
    console.error('Schema validation errors:');
    validate.errors.forEach(err => {
      console.error(`- ${err.instancePath} ${err.message}`);
    });
    hasError = true;
  }

  // Cross-checks

  // 1. Unique IDs
  const allIds = new Set();
  const checkId = (id, context) => {
    if (allIds.has(id)) {
      console.error(`Duplicate ID found: ${id} in ${context}`);
      hasError = true;
    }
    allIds.add(id);
  };

  (manifestObj.claims || []).forEach(c => checkId(c.id, 'claims'));
  (manifestObj.deviations || []).forEach(d => checkId(d.id, 'deviations'));
  (manifestObj.open_questions || []).forEach(q => checkId(q.id, 'open_questions'));

  // 2. Canonical ordering (Claims by file, symbol, first line, IDs assigned C1..)
  let prevClaim = null;
  let expectedId = 1;
  (manifestObj.claims || []).forEach(c => {
    if (c.id !== `C${expectedId}`) {
      console.error(`Claim ID out of order or invalid: expected C${expectedId}, found ${c.id}`);
      hasError = true;
    }
    if (prevClaim) {
      if (c.code_anchor && prevClaim.code_anchor) {
        if (c.code_anchor.file < prevClaim.code_anchor.file) {
          console.error(`Claims out of order by file: ${c.id} should be before ${prevClaim.id}`);
          hasError = true;
        } else if (c.code_anchor.file === prevClaim.code_anchor.file) {
          if (c.code_anchor.symbol < prevClaim.code_anchor.symbol) {
             console.error(`Claims out of order by symbol: ${c.id} should be before ${prevClaim.id}`);
             hasError = true;
          } else if (c.code_anchor.symbol === prevClaim.code_anchor.symbol) {
             if (c.code_anchor.lines[0] < prevClaim.code_anchor.lines[0]) {
               console.error(`Claims out of order by line: ${c.id} should be before ${prevClaim.id}`);
               hasError = true;
             }
          }
        }
      }
    }
    prevClaim = c;
    expectedId++;
  });

  // 3. every reference_anchor.ref resolves to a reference_pack entry
  const packIds = new Set((manifestObj.reference_pack || []).map(p => p.id));
  const checkRef = (anchor, context) => {
    if (!anchor) return;
    const ref = anchor.ref;
    if (ref !== 'lab_specific' && ref !== 'TBD Pass C' && !packIds.has(ref)) {
      console.error(`Unresolved reference_anchor.ref: ${ref} in ${context}`);
      hasError = true;
    }
  };
  (manifestObj.parameters || []).forEach(p => checkRef(p.reference_anchor, `parameters ${p.name}`));
  (manifestObj.claims || []).forEach(c => checkRef(c.reference_anchor, `claims ${c.id}`));
  (manifestObj.deviations || []).forEach(d => checkRef(d.reference_anchor, `deviations ${d.id}`));

  // 4. depends_on resolves
  const claimIds = new Set((manifestObj.claims || []).map(c => c.id));
  (manifestObj.claims || []).forEach(c => {
    (c.depends_on || []).forEach(dep => {
      if (!claimIds.has(dep)) {
        console.error(`Unresolved depends_on: ${dep} in claim ${c.id}`);
        hasError = true;
      }
    });
  });

  // 5. commit_sha present
  if (!manifestObj.repository || !manifestObj.repository.commit_sha) {
    console.error('commit_sha is missing');
    hasError = true;
  }

  // 6. conditional blocks
  const isAttack = manifestObj.audit_mode && manifestObj.audit_mode.type === 'attack_reproduction';
  if (isAttack && !manifestObj.attack_model) {
    console.error('attack_model is required when audit_mode is attack_reproduction');
    hasError = true;
  } else if (!isAttack && manifestObj.attack_model) {
    console.error('attack_model must not be present unless audit_mode is attack_reproduction');
    hasError = true;
  }

  const compTypes = new Set(['arithmetic', 'invariant', 'encoding', 'distribution']);
  (manifestObj.claims || []).forEach(c => {
    if (compTypes.has(c.type) && !c.computable) {
      console.error(`computable block missing for claim ${c.id} of type ${c.type}`);
      hasError = true;
    }
  });

  // 7. banned-verdict-word lint
  const bannedWords = ['correct', 'correctly', 'secure', 'safe', 'verified', 'valid'];
  const checkBanned = (text, context, isStatement) => {
    if (!text || typeof text !== 'string') return;
    const lower = text.toLowerCase();
    for (const w of bannedWords) {
      // rough word boundary check
      const re = new RegExp(`\\b${w}\\b`, 'i');
      if (re.test(lower)) {
        if (isStatement && lower.includes('should equal')) continue; // permitted exception
        console.error(`Banned word '${w}' found in ${context}`);
        hasError = true;
      }
    }
  };
  (manifestObj.claims || []).forEach(c => {
    checkBanned(c.statement, `claim ${c.id} statement`, true);
    checkBanned(c.notes, `claim ${c.id} notes`, false);
  });
  (manifestObj.deviations || []).forEach(d => {
    checkBanned(d.description, `deviation ${d.id} description`, false);
    checkBanned(d.severity_note, `deviation ${d.id} severity_note`, false);
  });

  // 8. code_anchor.snippet matches
  let mathCoreContent = '';
  const mathCoreFiles = (manifestObj.scope_map && manifestObj.scope_map.files || [])
    .filter(f => f.role === 'math_core')
    .map(f => f.path)
    .sort();

  const fileContents = {};
  for (const f of mathCoreFiles) {
    const fp = path.join(labDir, f);
    if (fs.existsSync(fp)) {
      const content = fs.readFileSync(fp, 'utf8');
      fileContents[f] = content;
      mathCoreContent += content;
    } else {
      console.error(`math_core file not found: ${f}`);
      hasError = true;
    }
  }

  const checkSnippet = (anchor, context) => {
    if (!anchor || !anchor.file || !anchor.snippet) return;
    const content = fileContents[anchor.file];
    if (content) {
      if (!content.includes(anchor.snippet)) {
         console.error(`Snippet mismatch in ${context} for file ${anchor.file}`);
         hasError = true;
      }
    }
  };
  (manifestObj.claims || []).forEach(c => checkSnippet(c.code_anchor, `claim ${c.id}`));
  (manifestObj.parameters || []).forEach(p => checkSnippet(p.code_anchor, `parameter ${p.name}`));
  (manifestObj.deviations || []).forEach(d => checkSnippet(d.code_anchor, `deviation ${d.id}`));

  // 9. reference_quote is literal substring
  // We'll mock this slightly by just checking if the file exists if we were in real run, 
  // but to do it fully we need to load excerpts.
  const checkQuote = (quote, anchor, context) => {
    if (!quote || !anchor || anchor.ref === 'lab_specific' || anchor.ref === 'TBD Pass C') return;
    const refDir = path.join(catalogDir, 'verification', 'reference-packs', anchor.ref);
    if (!fs.existsSync(refDir)) {
      // Excerpt dir missing, cannot verify quote right now
      return;
    }
    const files = getFilesRecursively(refDir);
    let found = false;
    for (const f of files) {
      const content = fs.readFileSync(f, 'utf8');
      if (content.includes(quote)) {
        found = true; break;
      }
    }
    if (!found && files.length > 0) {
      console.error(`reference_quote not found in excerpts for ${anchor.ref} in ${context}`);
      hasError = true;
    }
  };
  (manifestObj.parameters || []).forEach(p => checkQuote(p.reference_quote, p.reference_anchor, `parameter ${p.name}`));
  (manifestObj.deviations || []).forEach(d => checkQuote(d.reference_quote, d.reference_anchor, `deviation ${d.id}`));

  // 10. extraction_hash matches
  if (manifestObj.extraction && manifestObj.extraction.extraction_hash && manifestObj.extraction.extraction_hash !== 'PENDING') {
     const computedHash = crypto.createHash('sha256').update(mathCoreContent).digest('hex');
     if (computedHash !== manifestObj.extraction.extraction_hash) {
       console.error(`extraction_hash mismatch. Manifest declares ${manifestObj.extraction.extraction_hash}, computed ${computedHash} from math_core contents — the manifest is stale relative to the code and must be re-extracted`);
       hasError = true;
     }
  }

  // 11. warn on empty reviewed_symbols
  // 12. coverage completeness
  (manifestObj.coverage || []).forEach(cov => {
    if (!cov.reviewed_symbols || cov.reviewed_symbols.length === 0) {
      console.warn(`WARNING: empty reviewed_symbols for file ${cov.file}`);
    }
    const content = fileContents[cov.file];
    if (content) {
      const symbolsInFile = extractSymbols(content);
      const covered = new Set([
        ...(cov.reviewed_symbols || []),
        ...(cov.excluded_symbols || []),
        ...(cov.unresolved_regions || [])
      ]);
      for (const sym of symbolsInFile) {
        if (!covered.has(sym)) {
          console.error(`Symbol ${sym} in file ${cov.file} is missing from coverage block`);
          hasError = true;
        }
      }
    }
  });

  // 13. extractor_confidence below high links an open_question
  const questionIds = (manifestObj.open_questions || []).map(q => q.id);
  (manifestObj.claims || []).forEach(c => {
    if (c.extractor_confidence && c.extractor_confidence !== 'high') {
      let linked = false;
      for (const qid of questionIds) {
        if (c.notes && c.notes.includes(qid)) {
          linked = true; break;
        }
      }
      if (!linked) {
         console.error(`Claim ${c.id} has confidence ${c.extractor_confidence} but notes do not link an open_question`);
         hasError = true;
      }
    }
  });

  // 14. self-reference lint over verification blocks
  const checkVerification = (ver, context) => {
    if (!ver) return;
    const str = JSON.stringify(ver).toLowerCase();
    if (str.includes("the lab's") || str.includes("our code") || str.includes("this function")) {
      console.error(`Banned self-reference in verification block for ${context}`);
      hasError = true;
    }
  };
  (manifestObj.claims || []).forEach(c => checkVerification(c.verification, `claim ${c.id}`));

  // 15. warn when open_questions empty without simplicity assertion
  if (!manifestObj.open_questions || manifestObj.open_questions.length === 0) {
    let asserted = false;
    // Look for assertion in coverage notes or somewhere else
    (manifestObj.coverage || []).forEach(cov => {
      if (cov.note && cov.note.toLowerCase().includes('simple')) asserted = true;
    });
    if (!asserted) {
      console.warn("WARNING: open_questions is empty and no explicit simplicity assertion found.");
    }
  }

  return hasError ? 1 : 0;
}

// Each failing fixture must trip its specific check — a fixture that fails for any
// other reason (or an unregistered fixture) fails the run.
const FIXTURE_EXPECTATIONS = {
  'failing-banned-word.yaml': 'Banned word',
  'failing-commit-sha.yaml': 'commit_sha is missing',
  'failing-conditional-attack.yaml': 'attack_model is required',
  'failing-conditional-computable.yaml': 'computable block missing',
  'failing-confidence-question.yaml': 'do not link an open_question',
  'failing-coverage-missing.yaml': 'missing from coverage block',
  'failing-depends-on.yaml': 'Unresolved depends_on',
  'failing-hash.yaml': 'extraction_hash mismatch',
  'failing-ordering.yaml': 'Claims out of order',
  'failing-reference-anchor.yaml': 'Unresolved reference_anchor.ref',
  'failing-self-reference.yaml': 'Banned self-reference',
  'failing-snippet.yaml': 'Snippet mismatch',
  'failing-unique-id.yaml': 'Duplicate ID found',
};

function captureOutput(fn) {
  const lines = [];
  const origError = console.error;
  const origWarn = console.warn;
  console.error = (...args) => lines.push(args.join(' '));
  console.warn = (...args) => lines.push(args.join(' '));
  try {
    return { code: fn(), output: lines.join('\n') };
  } finally {
    console.error = origError;
    console.warn = origWarn;
  }
}

function checkFixtures(catalogDir) {
  const fixturesDir = path.join(catalogDir, 'verification', 'fixtures');
  let failures = 0;

  const passingPath = path.join(fixturesDir, 'passing-manifest.yaml');
  const passing = captureOutput(() => validateManifest(passingPath, fixturesDir, catalogDir));
  if (passing.code === 0) {
    console.log('PASS passing-manifest.yaml — validates cleanly');
  } else {
    failures++;
    console.error(`FAIL passing-manifest.yaml — expected clean validation, got:\n${passing.output}`);
  }

  const failingFixtures = fs.readdirSync(fixturesDir)
    .filter(f => f.startsWith('failing-') && f.endsWith('.yaml'))
    .sort();
  for (const fixture of failingFixtures) {
    const expected = FIXTURE_EXPECTATIONS[fixture];
    if (!expected) {
      failures++;
      console.error(`FAIL ${fixture} — no expected error registered in FIXTURE_EXPECTATIONS; add one so the fixture proves its specific check`);
      continue;
    }
    const result = captureOutput(() => validateManifest(path.join(fixturesDir, fixture), fixturesDir, catalogDir));
    if (result.code === 0) {
      failures++;
      console.error(`FAIL ${fixture} — expected validation failure, but manifest passed`);
    } else if (!result.output.includes(expected)) {
      failures++;
      console.error(`FAIL ${fixture} — failed, but not on the targeted check (wanted "${expected}"), got:\n${result.output}`);
    } else {
      console.log(`PASS ${fixture} — trips "${expected}"`);
    }
  }

  const unrun = Object.keys(FIXTURE_EXPECTATIONS).filter(f => !failingFixtures.includes(f));
  for (const fixture of unrun) {
    failures++;
    console.error(`FAIL ${fixture} — registered in FIXTURE_EXPECTATIONS but not found in ${fixturesDir}`);
  }

  console.log(failures === 0
    ? `Fixture check passed: 1 passing + ${failingFixtures.length} failing fixtures behaved as expected`
    : `Fixture check failed: ${failures} problem(s)`);
  return failures === 0 ? 0 : 1;
}

function main() {
  // verification/tools/validate-manifest.mjs -> verification/ holds schema.json, so the
  // "catalog dir" for this vendored copy is the repo root.
  const defaultCatalogDir = path.dirname(path.dirname(path.dirname(new URL(import.meta.url).pathname)));

  if (process.argv[2] === '--check-fixtures') {
    process.exit(checkFixtures(defaultCatalogDir));
  }

  if (process.argv.length < 3) {
    console.error('Usage: node validate-manifest.mjs <manifest.yaml> [lab-dir] [catalog-dir]');
    console.error('       node validate-manifest.mjs --check-fixtures');
    console.error('lab-dir defaults to the manifest\'s grandparent directory (a lab\'s verification/manifest.yaml -> the lab root).');
    process.exit(1);
  }

  const manifestPath = path.resolve(process.argv[2]);
  const labDir = process.argv[3] ? path.resolve(process.argv[3]) : path.dirname(path.dirname(manifestPath));
  const catalogDir = process.argv[4] ? path.resolve(process.argv[4]) : defaultCatalogDir;

  const code = validateManifest(manifestPath, labDir, catalogDir);
  if (code !== 0) {
    console.error('Validation failed');
    process.exit(code);
  } else {
    console.log('Manifest is valid');
  }
}

main();

/**
 * An independent implementation of the manifest binding and signature checks.
 *
 * Same reasoning as the watermark verifier: written from the structure rather than from
 * the lab's TypeScript, so agreement is evidence. Uses Node's WebCrypto for ECDSA P-256,
 * which is the same standard primitive the browser side uses and is deliberately not
 * reimplemented — hand-rolling a curve here would be checking the wrong thing.
 */

import { webcrypto } from 'node:crypto';

const { subtle } = webcrypto;
const ALGORITHM = { name: 'ECDSA', namedCurve: 'P-256' };
const SIGN_PARAMS = { name: 'ECDSA', hash: 'SHA-256' };

/** Canonical JSON: keys sorted, no whitespace, array order preserved. */
export function canonicalize(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(',')}]`;
  const entries = Object.entries(value)
    .filter(([, entry]) => entry !== undefined)
    .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0));
  return `{${entries.map(([key, entry]) => `${JSON.stringify(key)}:${canonicalize(entry)}`).join(',')}}`;
}

export async function sha256Hex(bytes) {
  const digest = await subtle.digest('SHA-256', bytes);
  return Buffer.from(digest).toString('hex');
}

export async function buildManifest(assetBytes, assertions, options) {
  const hashed = [];
  for (const assertion of assertions) {
    hashed.push({
      label: assertion.label,
      alg: 'sha256',
      hash: await sha256Hex(Buffer.from(canonicalize(assertion), 'utf8')),
    });
  }
  return {
    claim: {
      claim_generator: options.claimGenerator,
      format: options.format,
      instance_id: options.instanceId,
      assertions: hashed,
      hard_binding: {
        label: 'c2pa.hash.data',
        alg: 'sha256',
        hash: await sha256Hex(assetBytes),
        assetByteLength: assetBytes.byteLength,
      },
    },
    assertions: [...assertions],
    signature: null,
    signer: null,
  };
}

export async function signManifest(manifest, keyPair) {
  const bytes = Buffer.from(canonicalize(manifest.claim), 'utf8');
  const signature = await subtle.sign(SIGN_PARAMS, keyPair.privateKey, bytes);
  const spki = await subtle.exportKey('spki', keyPair.publicKey);
  return {
    ...manifest,
    signature: Buffer.from(signature).toString('base64'),
    signer: {
      label: 'verifier session key',
      publicKeySpki: Buffer.from(spki).toString('base64'),
      algorithm: 'ECDSA-P256-SHA256',
    },
  };
}

export async function generateKeyPair() {
  return subtle.generateKey(ALGORITHM, true, ['sign', 'verify']);
}

export async function validate(manifest, assetBytes) {
  const actualAssetHash = await sha256Hex(assetBytes);
  if (!manifest) {
    return {
      manifestPresent: false, signatureValid: false, bindingValid: false,
      assertionsValid: false, valid: false, actualAssetHash,
    };
  }
  const binding = manifest.claim.hard_binding;
  const bindingValid = binding.hash === actualAssetHash
    && binding.assetByteLength === assetBytes.byteLength;

  let assertionsValid = true;
  for (const recorded of manifest.claim.assertions) {
    const assertion = manifest.assertions.find((entry) => entry.label === recorded.label);
    const actual = assertion
      ? await sha256Hex(Buffer.from(canonicalize(assertion), 'utf8'))
      : null;
    if (actual !== recorded.hash) assertionsValid = false;
  }

  let signatureValid = false;
  if (manifest.signature && manifest.signer) {
    const publicKey = await subtle.importKey(
      'spki', Buffer.from(manifest.signer.publicKeySpki, 'base64'), ALGORITHM, true, ['verify']);
    signatureValid = await subtle.verify(
      SIGN_PARAMS, publicKey,
      Buffer.from(manifest.signature, 'base64'),
      Buffer.from(canonicalize(manifest.claim), 'utf8'));
  }

  return {
    manifestPresent: true,
    signatureValid,
    bindingValid,
    assertionsValid,
    valid: signatureValid && bindingValid && assertionsValid,
    actualAssetHash,
  };
}

/**
 * Signed 64-bit arithmetic on pairs of 32-bit halves.
 *
 * The lab implements the same arithmetic with BigInt. This file deliberately does not:
 * an independent verifier that reuses the implementation it is checking verifies
 * nothing, and a reimplementation in different arithmetic catches a whole class of bug —
 * sign handling, wraparound, shift semantics — that a shared helper would hide from both
 * sides at once.
 *
 * Values are carried as { hi, lo }, each an unsigned 32-bit integer, together
 * representing a two's-complement 64-bit value.
 */

const MULTIPLIER_HI = 0x5851f42d;
const MULTIPLIER_LO = 0x4c957f2d; // 6364136223846793005 = 0x5851F42D4C957F2D

/** Multiply by the LCG multiplier and add the increment, modulo 2^64. */
function mulAddIncrement(hi, lo) {
  const aLow = lo & 0xffff;
  const aHigh = lo >>> 16;
  const bLow = MULTIPLIER_LO & 0xffff;
  const bHigh = MULTIPLIER_LO >>> 16;

  const p0 = aLow * bLow;
  const p1 = aHigh * bLow + Math.floor(p0 / 65536);
  const p2 = aLow * bHigh + (p1 & 0xffff);

  const lowResult = ((((p2 & 0xffff) << 16) | (p0 & 0xffff)) >>> 0);
  const carry = aHigh * bHigh + Math.floor(p1 / 65536) + Math.floor(p2 / 65536);
  const highResult = (carry + Math.imul(hi, MULTIPLIER_LO) + Math.imul(lo, MULTIPLIER_HI)) >>> 0;

  const withIncrementLo = lowResult + 1;
  const withIncrementHi = highResult + (withIncrementLo > 0xffffffff ? 1 : 0);
  return { hi: withIncrementHi >>> 0, lo: withIncrementLo >>> 0 };
}

/** One accumulation step: ((current + value) * multiplier + 1) as int64. */
export function accumulateStep(state, value) {
  const addedLo = state.lo + (value >>> 0);
  const carry = addedLo > 0xffffffff ? 1 : 0;
  // A value may be negative in principle; the reference feeds token ids and keys, which
  // are not, and this verifier rejects anything else rather than guessing.
  if (!Number.isInteger(value) || value < 0 || value > 0xffffffff) {
    throw new Error(`value out of the range this verifier accepts: ${value}`);
  }
  return mulAddIncrement((state.hi + carry) >>> 0, addedLo >>> 0);
}

export function accumulate(state, values) {
  let current = state;
  for (const value of values) current = accumulateStep(current, value);
  return current;
}

/** Arithmetic right shift, preserving the sign bit. */
export function shiftRight(state, bits) {
  if (bits <= 0 || bits >= 64) throw new Error(`unsupported shift: ${bits}`);
  if (bits < 32) {
    const lo = ((state.lo >>> bits) | (state.hi << (32 - bits))) >>> 0;
    const hi = ((state.hi | 0) >> bits) >>> 0;
    return { hi, lo };
  }
  const hi = ((state.hi | 0) >> 31) >>> 0;
  const lo = (((state.hi | 0) >> (bits - 32)) >>> 0);
  return { hi, lo };
}

/** Bit at the given index, counting from the least significant. */
export function bitAt(state, index) {
  return index < 32 ? (state.lo >>> index) & 1 : (state.hi >>> (index - 32)) & 1;
}

export function fromBigInt(value) {
  const unsigned = BigInt.asUintN(64, value);
  return { hi: Number(unsigned >> 32n) >>> 0, lo: Number(unsigned & 0xffffffffn) >>> 0 };
}

/** Decimal string of the signed value, for comparing against committed vectors. */
export function toDecimalString(state) {
  const unsigned = (BigInt(state.hi) << 32n) | BigInt(state.lo);
  return BigInt.asIntN(64, unsigned).toString();
}

export function equals(a, b) {
  return a.hi === b.hi && a.lo === b.lo;
}

/**
 * An independent GPT-2 byte-level BPE implementation.
 *
 * Written from the algorithm rather than from the lab's TypeScript, and structured
 * differently on purpose: this one materialises a rank-sorted pair list per word instead
 * of scanning for the minimum each pass. Same output, different route — which is what
 * makes agreement on the committed vectors worth something.
 */

import { createHash } from 'node:crypto';

const PATTERN = /'s|'t|'re|'ve|'m|'ll|'d| ?\p{L}+| ?\p{N}+| ?[^\s\p{L}\p{N}]+|\s+(?!\S)|\s+/gu;
const END_OF_TEXT = '<|endoftext|>';

function byteAlphabet() {
  const printable = [];
  for (let value = 0x21; value <= 0x7e; value += 1) printable.push(value);
  for (let value = 0xa1; value <= 0xac; value += 1) printable.push(value);
  for (let value = 0xae; value <= 0xff; value += 1) printable.push(value);

  const codePoints = printable.slice();
  let spare = 0;
  for (let value = 0; value < 256; value += 1) {
    if (!printable.includes(value)) {
      printable.push(value);
      codePoints.push(256 + spare);
      spare += 1;
    }
  }
  const byteToChar = new Array(256);
  const charToByte = new Map();
  printable.forEach((byteValue, index) => {
    const char = String.fromCodePoint(codePoints[index]);
    byteToChar[byteValue] = char;
    charToByte.set(char, byteValue);
  });
  return { byteToChar, charToByte, ordered: codePoints.map((c) => String.fromCodePoint(c)) };
}

export function createTokenizer(mergesText) {
  const { byteToChar, charToByte, ordered } = byteAlphabet();
  const merges = mergesText.split('\n').filter((line) => line && !line.startsWith('#version'));
  const rank = new Map(merges.map((line, index) => [line, index]));

  // GPT-2's vocabulary is exactly: the 256 byte tokens, the merge results in order, then
  // the end-of-text marker. Derived here rather than shipped, and checkable by hash.
  const vocabulary = [...ordered, ...merges.map((line) => line.replace(' ', '')), END_OF_TEXT];
  const idOf = new Map();
  vocabulary.forEach((token, id) => { if (!idOf.has(token)) idOf.set(token, id); });

  const cache = new Map();
  const mergeWord = (word) => {
    if (cache.has(word)) return cache.get(word);
    let symbols = Array.from(word);
    while (symbols.length > 1) {
      let best = null;
      for (let index = 0; index < symbols.length - 1; index += 1) {
        const candidate = rank.get(`${symbols[index]} ${symbols[index + 1]}`);
        if (candidate !== undefined && (best === null || candidate < best.rank)) {
          best = { rank: candidate, index };
        }
      }
      if (best === null) break;
      const left = symbols[best.index];
      const right = symbols[best.index + 1];
      const merged = [];
      for (let index = 0; index < symbols.length;) {
        if (index < symbols.length - 1 && symbols[index] === left && symbols[index + 1] === right) {
          merged.push(left + right);
          index += 2;
        } else {
          merged.push(symbols[index]);
          index += 1;
        }
      }
      symbols = merged;
    }
    cache.set(word, symbols);
    return symbols;
  };

  const encoder = new TextEncoder();
  const decoder = new TextDecoder('utf-8');

  return {
    vocabularySize: vocabulary.length,
    vocabularySha256() {
      return createHash('sha256').update(vocabulary.join('\n'), 'utf8').digest('hex');
    },
    encode(text) {
      const ids = [];
      text.split(END_OF_TEXT).forEach((chunk, chunkIndex) => {
        if (chunkIndex > 0) ids.push(vocabulary.length - 1);
        for (const match of chunk.matchAll(PATTERN)) {
          let mapped = '';
          for (const byte of encoder.encode(match[0])) mapped += byteToChar[byte];
          for (const piece of mergeWord(mapped)) {
            const id = idOf.get(piece);
            if (id === undefined) throw new Error(`unknown piece ${JSON.stringify(piece)}`);
            ids.push(id);
          }
        }
      });
      return ids;
    },
    decode(ids) {
      const bytes = [];
      for (const id of ids) {
        for (const char of Array.from(vocabulary[id] ?? '')) {
          const byte = charToByte.get(char);
          if (byte === undefined) for (const b of encoder.encode(char)) bytes.push(b);
          else bytes.push(byte);
        }
      }
      return decoder.decode(Uint8Array.from(bytes));
    },
  };
}

#!/usr/bin/env node
/**
 * The independent verifier.
 *
 * Parses the same committed vectors the lab ships, recomputes everything from its own
 * implementation, and compares. It imports nothing from src/ — a verifier that shares a
 * module with the thing it verifies would reproduce that module's bugs on both sides at
 * once and call the agreement a pass.
 *
 * Every expectation is classified, because they are not the same kind of claim:
 *
 *   MATHEMATICAL INVARIANT   true by the arithmetic; an exact comparison
 *   IMPLEMENTATION INVARIANT true of this construction as published; an exact comparison
 *   STATISTICAL EXPECTATION  true on average; compared against a stated tolerance
 *   EMPIRICAL OBSERVATION    what was measured here; recorded, and only bounded loosely
 *
 * A statistical expectation asserted as a binary invariant is a flaky test pretending to
 * be a proof, so the tolerances below are explicit and are part of the claim.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { accumulate, toDecimalString, fromBigInt } from './int64.mjs';
import {
  binomialUpperTail, chainSeed, eosMask, gValue, positionHashes, repeatedContextMask, score,
} from './watermark.mjs';
import { createTokenizer } from './tokenizer.mjs';
import { buildManifest, canonicalize, generateKeyPair, signManifest, validate } from './c2pa.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
const PINNED = join(ROOT, 'src', 'data', 'pinned');

const read = (path) => JSON.parse(readFileSync(path, 'utf8'));
const vectors = read(join(PINNED, 'test-vectors.json'));
const texts = read(join(PINNED, 'texts.json'));
const attacks = read(join(PINNED, 'attacks.json'));
const distributions = read(join(PINNED, 'distributions.json'));
const corpus = read(join(PINNED, 'null-corpus.json'));
const tokenizerMeta = read(join(PINNED, 'tokenizer-meta.json'));
const tokenizerVectors = read(join(PINNED, 'tokenizer-vectors.json'));
const labConfig = read(join(ROOT, 'src', 'data', 'watermark-config.json'));
const canonVectors = read(join(ROOT, 'verification', 'vectors', 'canonicalization.json'));

const params = vectors.watermark;
const tokenizer = createTokenizer(readFileSync(join(PINNED, 'gpt2-merges.txt'), 'utf8'));

const results = [];
let failures = 0;

function check(kind, name, passed, detail) {
  results.push({ kind, name, passed, detail });
  if (!passed) failures += 1;
}

const near = (actual, expected, tolerance) =>
  Number.isFinite(actual) && Number.isFinite(expected) && Math.abs(actual - expected) <= tolerance;

// ── The keyed hash ──────────────────────────────────────────────────────────────
for (const vector of vectors.lcg_vectors) {
  const actual = toDecimalString(accumulate(fromBigInt(BigInt(vector.seed)), vector.data));
  check('MATHEMATICAL INVARIANT', `LCG chain over ${JSON.stringify(vector.data)}`,
    actual === vector.hash, `${actual} vs ${vector.hash}`);
}

for (const [name, expected] of Object.entries(vectors.chain_seeds)) {
  const actual = toDecimalString(chainSeed(vectors.key_sets[name]));
  check('IMPLEMENTATION INVARIANT', `chain seed for ${name}`,
    actual === expected, `${actual} vs ${expected}`);
}

// ── g-values, masking and scores on the pinned sequences ────────────────────────
for (const [sequenceName, sequence] of Object.entries(vectors.sequences)) {
  for (const [keyName, expected] of Object.entries(sequence.per_key_set)) {
    const keyed = { ...params, keys: vectors.key_sets[keyName] };
    if (expected.g_values.length) {
      const positions = positionHashes(sequence.token_ids, keyed);
      const actual = positions.map((position) =>
        keyed.keys.map((key) => gValue(position.candidateHash, key)));
      check('IMPLEMENTATION INVARIANT', `g-values on ${sequenceName} under ${keyName}`,
        JSON.stringify(actual) === JSON.stringify(expected.g_values),
        `${actual.length} rows`);

      const mask = repeatedContextMask(sequence.token_ids, keyed);
      check('IMPLEMENTATION INVARIANT',
        `repeated-context mask on ${sequenceName} under ${keyName}`,
        JSON.stringify(mask) === JSON.stringify(expected.context_repetition_mask),
        `${mask.filter((keep) => !keep).length} positions dropped`);
    }
    const eos = eosMask(sequence.token_ids, 50256);
    check('IMPLEMENTATION INVARIANT', `end-of-text mask on ${sequenceName} under ${keyName}`,
      JSON.stringify(eos) === JSON.stringify(expected.eos_mask),
      `${eos.filter((keep) => !keep).length} tokens dropped`);
  }
}

check('MATHEMATICAL INVARIANT', 'masking actually fires on a repeated context',
  repeatedContextMask(vectors.sequences.repeated_context.token_ids, params)
    .some((keep) => !keep),
  'the repeated-context vector is not vacuous');

check('MATHEMATICAL INVARIANT', 'text shorter than one n-gram yields no score',
  score(vectors.sequences.too_short.token_ids, params).score === null,
  `${vectors.sequences.too_short.token_ids.length} tokens, ngram_len ${params.ngram_len}`);

check('MATHEMATICAL INVARIANT', 'the shortest scorable text offers exactly one position',
  score(vectors.sequences.shortest_scorable.token_ids, params).candidatePositions === 1,
  'one candidate position');

// ── The pinned samples, under every key set ─────────────────────────────────────
for (const [sampleName, perKey] of Object.entries(vectors.pinned_sample_scores)) {
  const tokenIds = texts.samples[sampleName].token_ids;
  for (const [keyName, expected] of Object.entries(perKey)) {
    const actual = score(tokenIds, { ...params, keys: vectors.key_sets[keyName] });
    check('IMPLEMENTATION INVARIANT', `score of ${sampleName} under ${keyName}`,
      near(actual.score, expected.score, 1e-12)
      && actual.scoredPositions === expected.scored_positions
      && actual.gSum === expected.g_sum,
      `${actual.score} vs ${expected.score}, ${actual.scoredPositions} positions`);
  }
}

// ── The adversarial matrix ──────────────────────────────────────────────────────
const watermarked = texts.samples.watermarked.token_ids;
const control = texts.samples.control.token_ids;
const baseline = score(watermarked, params);
const controlScore = score(control, params);

const threshold320 = corpus.by_length['320'].threshold_fpr_1_percent;
check('EMPIRICAL OBSERVATION', 'correct key clears this configuration’s 1% threshold',
  baseline.score >= threshold320,
  `${baseline.score.toFixed(4)} vs threshold ${threshold320.toFixed(4)}`);

check('EMPIRICAL OBSERVATION', 'unwatermarked control does not clear it',
  controlScore.score < threshold320,
  `${controlScore.score.toFixed(4)} vs threshold ${threshold320.toFixed(4)}`);

const wrongKeyScores = [];
for (let seed = 1; seed <= 40; seed += 1) {
  // Deterministic wrong keys, derived from the configured ones so they are keys of the
  // same shape rather than arbitrary noise.
  const keys = params.keys.map((key, index) => (key ^ ((seed * 2654435761 + index) >>> 8)) % 1048576);
  wrongKeyScores.push(score(watermarked, { ...params, keys }).score);
}
const wrongMean = wrongKeyScores.reduce((total, value) => total + value, 0) / wrongKeyScores.length;
const wrongMax = Math.max(...wrongKeyScores);
check('STATISTICAL EXPECTATION', 'forty wrong keys centre on one half (tolerance 0.02)',
  near(wrongMean, 0.5, 0.02), `mean ${wrongMean.toFixed(4)}`);
check('STATISTICAL EXPECTATION', 'no wrong key reaches the correct key’s score',
  wrongMax < baseline.score, `highest wrong key ${wrongMax.toFixed(4)}`);

const oneBit = score(watermarked, { ...params, keys: vectors.key_sets.one_bit_flipped });
check('IMPLEMENTATION INVARIANT', 'one flipped key bit removes essentially all evidence',
  Math.abs(oneBit.score - 0.5) < Math.abs(baseline.score - 0.5) * 0.15,
  `${oneBit.score.toFixed(4)} against baseline ${baseline.score.toFixed(4)}`);

// A tokenizer that disagrees with the generator is scoring a different sequence.
const shifted = watermarked.map((id) => (id + 1) % 50257);
const shiftedScore = score(shifted, params);
check('IMPLEMENTATION INVARIANT', 'a tokenizer mismatch destroys the evidence',
  Math.abs(shiftedScore.score - 0.5) < Math.abs(baseline.score - 0.5) * 0.3,
  `${shiftedScore.score.toFixed(4)} after shifting every token id by one`);

const truncated = score(watermarked.slice(0, 40), params);
check('MATHEMATICAL INVARIANT', 'truncation reduces the counted positions exactly',
  truncated.candidatePositions === 40 - (params.ngram_len - 1),
  `${truncated.candidatePositions} candidate positions from 40 tokens`);

const halfDeleted = score(watermarked.filter((_, index) => index % 2 === 0), params);
check('STATISTICAL EXPECTATION', 'deleting every second token moves the score toward the null',
  Math.abs(halfDeleted.score - 0.5) < Math.abs(baseline.score - 0.5),
  `${halfDeleted.score.toFixed(4)} against baseline ${baseline.score.toFixed(4)}`);

const substituted = watermarked.map((id, index) => (index % 2 === 0 ? watermarked[0] : id));
const substitutedScore = score(substituted, params);
check('STATISTICAL EXPECTATION', 'substituting every second token moves the score toward the null',
  Math.abs(substitutedScore.score - 0.5) < Math.abs(baseline.score - 0.5),
  `${substitutedScore.score.toFixed(4)} against baseline ${baseline.score.toFixed(4)}`);

for (const transformation of attacks.transformations) {
  const recomputed = score(tokenizer.encode(transformation.transformed_text), params);
  const captured = transformation.reference_score_transformed;
  check('IMPLEMENTATION INVARIANT', `${transformation.id}: recomputed score matches the capture`,
    near(recomputed.score, captured.score, 1e-12)
    && recomputed.scoredPositions === captured.scored_positions,
    `${recomputed.score} vs ${captured.score}`);
}

// ── Entropy of the pinned distributions ─────────────────────────────────────────
const entropyOf = (probabilities) =>
  -probabilities.reduce((total, p) => (p > 0 ? total + p * Math.log2(p) : total), 0);
const high = distributions.distributions.high_entropy;
const low = distributions.distributions.low_entropy;
check('EMPIRICAL OBSERVATION', 'the high-entropy context really has more entropy',
  entropyOf(high.candidates.map((c) => c.probability))
    > entropyOf(low.candidates.map((c) => c.probability)),
  `${entropyOf(high.candidates.map((c) => c.probability)).toFixed(3)} vs ` +
  `${entropyOf(low.candidates.map((c) => c.probability)).toFixed(3)} bits`);

// The tolerance is float32-scale on purpose: these probabilities are a softmax computed
// by torch in float32 and then written out as float64, so they sum to one to about 1e-7
// and no tighter. Asserting 1e-9 here would be asserting a precision the capture never had.
check('IMPLEMENTATION INVARIANT',
  'every pinned distribution is normalized to float32 precision',
  Object.values(distributions.distributions).every((dist) =>
    near(dist.candidates.reduce((total, c) => total + c.probability, 0), 1, 1e-6)),
  Object.entries(distributions.distributions)
    .map(([name, dist]) =>
      `${name}: ${dist.candidates.reduce((total, c) => total + c.probability, 0).toFixed(9)}`)
    .join(', '));

// ── The corpus and its thresholds ───────────────────────────────────────────────
for (const entry of Object.values(corpus.by_length)) {
  const scores = entry.null_scores;
  if (!scores.length) continue;
  const rank = Math.min(scores.length - 1, Math.max(0, Math.round(0.99 * scores.length) - 1));
  check('IMPLEMENTATION INVARIANT',
    `threshold at ${entry.tokens} tokens is the recorded quantile`,
    near([...scores].sort((a, b) => a - b)[rank], entry.threshold_fpr_1_percent, 1e-12),
    `${entry.threshold_fpr_1_percent}`);
}

const recomputedNull = corpus.corpus_token_ids
  .map((tokenIds) => score(tokenIds.slice(0, 200), params).score)
  .filter((value) => value !== null);
const pinnedNull = corpus.by_length['200'].null_scores;
check('IMPLEMENTATION INVARIANT', 'the pinned null at 200 tokens recomputes exactly',
  recomputedNull.length === pinnedNull.length
  && [...recomputedNull].sort((a, b) => a - b)
    .every((value, index) => near(value, pinnedNull[index], 1e-12)),
  `${recomputedNull.length} texts`);

const measuredSd = Math.sqrt(recomputedNull.reduce((total, value) =>
  total + (value - recomputedNull.reduce((a, b) => a + b, 0) / recomputedNull.length) ** 2, 0)
  / (recomputedNull.length - 1));
const meanScored = corpus.by_length['200'].null_mean_scored_positions
  ?? (200 - (params.ngram_len - 1));
const predictedSd = Math.sqrt(0.25 / (meanScored * params.keys.length));
check('EMPIRICAL OBSERVATION',
  'measured null spread against the independence prediction (recorded, bounded at 2x)',
  measuredSd < predictedSd * 2,
  `measured ${measuredSd.toFixed(5)} against predicted ${predictedSd.toFixed(5)}`);

// ── The exact null ──────────────────────────────────────────────────────────────
check('MATHEMATICAL INVARIANT', 'binomial tail is one half above the median for even trials',
  near(binomialUpperTail(6, 10).pValue,
    (1 - (252 / 1024)) / 2, 1e-12),
  'closed form for n = 10');
check('MATHEMATICAL INVARIANT', 'binomial tail keeps a log10 value after underflow',
  binomialUpperTail(9000, 9420).pValue === 0
  && Number.isFinite(binomialUpperTail(9000, 9420).log10PValue),
  `log10 p = ${binomialUpperTail(9000, 9420).log10PValue.toFixed(1)}`);

// ── The tokenizer ───────────────────────────────────────────────────────────────
check('IMPLEMENTATION INVARIANT', 'derived vocabulary matches the real one by hash',
  tokenizer.vocabularySha256() === tokenizerMeta.vocab_sha256,
  tokenizer.vocabularySha256().slice(0, 16));
check('IMPLEMENTATION INVARIANT', 'derived vocabulary has the recorded size',
  tokenizer.vocabularySize === tokenizerMeta.vocab_size, `${tokenizer.vocabularySize}`);

let tokenizerMismatches = 0;
for (const testCase of tokenizerVectors.cases) {
  if (JSON.stringify(tokenizer.encode(testCase.text)) !== JSON.stringify(testCase.token_ids)) {
    tokenizerMismatches += 1;
  }
  if (tokenizer.decode(testCase.token_ids) !== testCase.decoded) tokenizerMismatches += 1;
}
check('IMPLEMENTATION INVARIANT', 'every tokenizer vector round-trips',
  tokenizerMismatches === 0, `${tokenizerVectors.cases.length} cases`);

for (const [sampleName, sample] of Object.entries(texts.samples)) {
  check('IMPLEMENTATION INVARIANT', `${sampleName} re-tokenizes to its committed ids`,
    JSON.stringify(tokenizer.encode(sample.text)) === JSON.stringify(sample.token_ids),
    `${sample.token_ids.length} tokens`);
}

// ── Configuration consistency ───────────────────────────────────────────────────
check('IMPLEMENTATION INVARIANT', 'the shipped configuration matches the vectors',
  JSON.stringify(labConfig.watermark.keys) === JSON.stringify(params.keys)
  && labConfig.watermark.ngram_len === params.ngram_len
  && labConfig.watermark.context_history_size === params.context_history_size,
  `${params.keys.length} keys, ngram_len ${params.ngram_len}`);

// ── Signatures ──────────────────────────────────────────────────────────────────
const CLAIM_OPTIONS = {
  claimGenerator: 'crypto-lab-token-tell/verifier',
  format: 'text/plain',
  instanceId: 'urn:uuid:00000000-0000-4000-8000-000000000001',
};
const ASSERTIONS = [{ label: 'stds.schema-org.CreativeWork', data: { author: [{ name: 'A. Cataloguer' }] } }];

for (const testCase of canonVectors.cases) {
  check('IMPLEMENTATION INVARIANT',
    `canonicalization of ${JSON.stringify(testCase.input).slice(0, 40)}`,
    canonicalize(testCase.input) === testCase.canonical,
    canonicalize(testCase.input));
}

const asset = Buffer.from('The library will retain the accession register in paper form.', 'utf8');
const keyPair = await generateKeyPair();
const signed = await signManifest(await buildManifest(asset, ASSERTIONS, CLAIM_OPTIONS), keyPair);

const clean = await validate(signed, asset);
check('IMPLEMENTATION INVARIANT', 'a signed manifest verifies', clean.valid,
  `signature ${clean.signatureValid}, binding ${clean.bindingValid}`);

const tampered = Buffer.from(asset);
tampered[0] ^= 0x01;
const tamperedResult = await validate(signed, tampered);
check('MATHEMATICAL INVARIANT', 'one flipped asset byte breaks the binding',
  !tamperedResult.bindingValid && !tamperedResult.valid && tamperedResult.signatureValid,
  'binding fails while the signature over the claim still verifies');

const stripped = await validate(null, asset);
check('IMPLEMENTATION INVARIANT', 'a stripped manifest leaves nothing to verify',
  !stripped.manifestPresent && !stripped.valid
  && stripped.actualAssetHash === clean.actualAssetHash,
  'the asset bytes are unchanged and now unmarked');

const lie = Buffer.from('This document was written by hand in 1687 and contains no errors.', 'utf8');
const signedLie = await signManifest(
  await buildManifest(lie, [{ label: 'stds.schema-org.CreativeWork', data: { dateCreated: '1687-01-01' } }],
    CLAIM_OPTIONS), keyPair);
const lieResult = await validate(signedLie, lie);
check('IMPLEMENTATION INVARIANT', 'a plainly false statement still verifies',
  lieResult.valid, 'integrity and truth are different properties');

// ── Report ──────────────────────────────────────────────────────────────────────
const byKind = results.reduce((groups, result) => {
  (groups[result.kind] ??= []).push(result);
  return groups;
}, {});

for (const [kind, group] of Object.entries(byKind)) {
  const failed = group.filter((result) => !result.passed);
  console.log(`\n${kind} — ${group.length - failed.length}/${group.length} passed`);
  for (const result of group) {
    if (!result.passed) console.log(`  FAIL  ${result.name} — ${result.detail}`);
  }
}

console.log(`\n${results.length - failures} of ${results.length} checks passed.`);
if (failures > 0) {
  console.error(`${failures} check(s) failed.`);
  process.exit(1);
}

/**
 * An independent implementation of the SynthID-Text detection path.
 *
 * Written against the reference implementation's published source
 * (google-deepmind/synthid-text @ addb4a1) and the paper, NOT against the lab's
 * TypeScript. It shares no module with the lab. If the two agree on the committed
 * vectors, that agreement is evidence; if one file imported the other it would be
 * decoration.
 */

import { createHash } from 'node:crypto';

import { accumulate, accumulateStep, bitAt, equals, fromBigInt, shiftRight } from './int64.mjs';

const NUM_APPLY_HASH = 12;
const SHIFT = 5; // 64 // 12, which is what `shift = shift or (64 // num_apply_hash)` yields
const OUTPUT_BIT = 30;
const INT64_MAX = (1n << 63n) - 1n;

/** SHA-256 over the little-endian int64 key array, big-endian, modulo 2^63 - 1. */
export function chainSeed(keys) {
  const packed = Buffer.alloc(keys.length * 8);
  keys.forEach((key, index) => packed.writeBigInt64LE(BigInt(key), index * 8));
  const digest = createHash('sha256').update(packed).digest();
  let value = 0n;
  for (const byte of digest) value = (value << 8n) | BigInt(byte);
  return fromBigInt(value % INT64_MAX);
}

/** g-value for one candidate hash under one layer key. */
export function gValue(candidateHash, key) {
  let state = accumulateStep(candidateHash, key);
  for (let round = 0; round < NUM_APPLY_HASH; round += 1) {
    state = shiftRight(accumulateStep(state, 1), SHIFT);
  }
  return bitAt(state, OUTPUT_BIT);
}

/**
 * Per-position hashes.
 *
 * The window starts at ngram_len - 1: earlier tokens are context only. Built by hashing
 * the context and then folding the candidate in, which the reference's prefix property
 * makes equivalent to hashing the whole n-gram at once.
 */
export function positionHashes(tokenIds, params) {
  const seed = chainSeed(params.keys);
  const window = params.ngram_len - 1;
  const positions = [];
  for (let index = window; index < tokenIds.length; index += 1) {
    const contextHash = accumulate(seed, tokenIds.slice(index - window, index));
    positions.push({
      tokenIndex: index,
      contextHash,
      candidateHash: accumulateStep(contextHash, tokenIds[index]),
    });
  }
  return positions;
}

/** Positions whose context has not been seen before, in a rolling history. */
export function repeatedContextMask(tokenIds, params) {
  const seed = chainSeed(params.keys);
  const window = params.ngram_len - 1;
  const history = [];
  const keep = [];
  for (let index = window; index < tokenIds.length; index += 1) {
    const contextHash = accumulate(seed, tokenIds.slice(index - window, index));
    const seen = history.some((entry) => equals(entry, contextHash))
      // The reference initialises its history buffer with zeros, so a context hashing to
      // exactly zero collides with the empty buffer. Reproduced, not corrected.
      || equals(contextHash, { hi: 0, lo: 0 });
    keep.push(!seen);
    history.unshift(contextHash);
    if (history.length > params.context_history_size) history.pop();
  }
  return keep;
}

/** Everything from the first end-of-text token onward is dropped. */
export function eosMask(tokenIds, eosTokenId) {
  const mask = tokenIds.map(() => true);
  if (eosTokenId === null || eosTokenId === undefined) return mask;
  const first = tokenIds.indexOf(eosTokenId);
  if (first === -1) return mask;
  for (let index = first; index < mask.length; index += 1) mask[index] = false;
  return mask;
}

/** The mean g-score, with the position bookkeeping needed to interpret it. */
export function score(tokenIds, params, eosTokenId = 50256) {
  const window = params.ngram_len - 1;
  if (tokenIds.length <= window) {
    return { score: null, gSum: 0, scoredPositions: 0, candidatePositions: 0, depth: params.keys.length };
  }
  const positions = positionHashes(tokenIds, params);
  const notRepeated = repeatedContextMask(tokenIds, params);
  const eos = eosMask(tokenIds, eosTokenId).slice(window);

  let gSum = 0;
  let counted = 0;
  const perPosition = [];
  positions.forEach((position, index) => {
    const keep = notRepeated[index] && (eos[index] ?? true);
    const values = params.keys.map((key) => gValue(position.candidateHash, key));
    if (keep) {
      counted += 1;
      for (const value of values) gSum += value;
    }
    perPosition.push({ tokenIndex: position.tokenIndex, values, keep });
  });

  return {
    score: counted === 0 ? null : gSum / (counted * params.keys.length),
    gSum,
    scoredPositions: counted,
    candidatePositions: positions.length,
    depth: params.keys.length,
    perPosition,
  };
}

/** Exact upper tail of Binomial(trials, 1/2), by direct summation in log space. */
export function binomialUpperTail(observedSum, trials) {
  if (trials <= 0) return { pValue: Number.NaN, log10PValue: Number.NaN };
  const k0 = Math.ceil(observedSum);
  if (k0 <= 0) return { pValue: 1, log10PValue: 0 };
  if (k0 > trials) return { pValue: 0, log10PValue: -Infinity };

  const logFactorial = new Array(trials + 1).fill(0);
  for (let n = 1; n <= trials; n += 1) logFactorial[n] = logFactorial[n - 1] + Math.log(n);
  const logTerms = [];
  for (let k = k0; k <= trials; k += 1) {
    logTerms.push(
      logFactorial[trials] - logFactorial[k] - logFactorial[trials - k] - trials * Math.LN2,
    );
  }
  const maxLog = Math.max(...logTerms);
  const sum = logTerms.reduce((total, term) => total + Math.exp(term - maxLog), 0);
  const logP = maxLog + Math.log(sum);
  return { pValue: Math.exp(logP), log10PValue: logP / Math.LN10 };
}

