// Mutations run only on a committed, clean source baseline. Each is built, killed,
// restored byte-for-byte, rebuilt and tested green before the next begins.
import { readFileSync, writeFileSync, readdirSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..'); process.chdir(root);
const config = process.env.PLAYWRIGHT_CONFIG;
const browser = title => ['npx', ['playwright','test','e2e/claims.spec.ts','--project=claims','--grep',title,'--workers=1','--retries=0',...(config ? ['--config',config] : [])]];
const unit = title => ['npx',['vitest','run','src/corpus/corpus.test.ts','-t',title]];
const build = ['npm',['run','build']];
const run = ([cmd,args]) => {
 const env={...process.env,CI:'1'};
 if(cmd==='npx'&&args[0]==='playwright')env.MUTATION_ASSETS=JSON.stringify(Object.fromEntries(readdirSync('dist/assets').filter(p=>p.endsWith('.js')).map(p=>[p,createHash('sha256').update(readFileSync(join('dist/assets',p))).digest('hex')])));
 return spawnSync(cmd,args,{cwd:root,encoding:'utf8',env});
};
const pass = (cmd,label) => { const r=run(cmd); if(r.status!==0) throw Error(`${label}\n${r.stdout}\n${r.stderr}`); return r; };
const hash = () => { const h=createHash('sha256'); const walk=d=>{for(const e of readdirSync(d,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))){const p=join(d,e.name); if(e.isDirectory())walk(p);else {h.update(p);h.update(readFileSync(p));}}};walk('dist');return h.digest('hex'); };
const cases = [
 ['wrong remainder modulus','src/corpus/batchgcd.ts','%(n*n)','%n',unit('batch and independent pairwise raw gcds')],
 ['missing leaf division','src/corpus/batchgcd.ts','gcd(n,remainders[0][i]/n)','gcd(n,remainders[0][i])',browser('corpus public GCD transcript')],
 ['fresh primes ignore repeated seeds','src/corpus/generate.ts',
  'const prime=(r:number):bigint=>{if(!cache.has(r))cache.set(r,primeFromSeed(r,ctx.bits));return cache.get(r)!;};',
  'const prime=(_r:number):bigint=>randomPrime(ctx.bits);',browser('corpus observed collisions')],
 ['verifier bypass','src/corpus/verify.ts',
  'verifyFactorization({n:ns[i],p:split.factor,q:split.factor===null?null:ns[i]/split.factor})',
  "(void verifyFactorization, void ns[i], void split.factor, {status:'no-claim',product:null,productMatchesN:false,factors:[],fullyFactored:false,reason:'Verifier bypassed'} as Verdict)",unit('every corpus result goes through the original verifier')],
 ['compromise painted green','src/ui/corpus.ts',"recovered?'alarm':v.status", "recovered?'pass':v.status",browser('corpus public GCD transcript')],
 ['missing negative claim','src/ui/corpus.ts',
  "export const CORPUS_NEGATIVE_CLAIM='The four bounded per-key searches found no factor, yet the same public key was factored by the corpus. Giving up is not a certificate of security.';",
  "export const CORPUS_NEGATIVE_CLAIM='';",browser('corpus negative claim')],
];
const dirty=spawnSync('git',['diff','--exit-code','--',...new Set(cases.map(x=>x[1]))],{encoding:'utf8'});
if(dirty.status!==0)throw Error('Commit the source baseline before mutation checks.');
pass(build,'baseline build');const baseline=hash();const evidence=[];
mkdirSync('mutation-logs',{recursive:true});
for(const [name,file,before,after,command] of cases){
 pass(command,`${name}: baseline test`);
 const original=readFileSync(file,'utf8');if(original.split(before).length!==2)throw Error(`${name}: expected one mutation site`);
 let mutant;
 try{
  writeFileSync(file,original.replace(before,after));
  const diff=spawnSync('git',['diff','--',file],{encoding:'utf8'}).stdout;if(!diff.trim())throw Error(`${name}: empty diff`);
  pass(build,`${name}: mutant build`); mutant=hash();if(mutant===baseline)throw Error(`${name}: bundle did not move`);
  const r=run(command);writeFileSync(`mutation-logs/${name.replaceAll(' ','-')}.log`,r.stdout+r.stderr);
  if(r.status===0 || /MUTATION_ASSET_MISMATCH/.test(r.stdout+r.stderr) || !/expect\(|AssertionError|Error: expect/.test(r.stdout+r.stderr))throw Error(`${name}: no assertion kill\n${r.stdout}\n${r.stderr}`);
  evidence.push({name,sourceDiff:diff,baseline,mutant,namedTest:command[1].includes('--grep') ? command[1][command[1].indexOf('--grep')+1] : command[1].at(-1),assertionFailure:true,retries:0,servedAssetGuard:true});
 }finally{writeFileSync(file,original);pass(build,`${name}: restore build`);if(hash()!==baseline)throw Error(`${name}: restored hash differs`);pass(command,`${name}: restored test`);}
 evidence.at(-1).restoredGreen=true;console.log(`${name}: killed; exact artifact restored; owning test green`);
}
writeFileSync('mutation-evidence.json',JSON.stringify(evidence,null,2)+'\n');

#!/usr/bin/env node
/**
 * The mutation runner — template §4.1c, made reproducible, for a page whose
 * claims are rendered rather than returned.
 *
 * WHY THIS EXISTS RATHER THAN A PROSE LEDGER
 *
 * `e2e/verdict-mutations.json` used to carry each mutation as a SENTENCE and an
 * `observed` paragraph written by hand. Both halves fail in the same way: a
 * sentence cannot be replayed, and a paragraph describing a run is the author's
 * side of the claim. Some of those paragraphs described a run against a tree
 * that no longer existed. Worse, one described a mutation that had never
 * applied — the anchor matched nothing, the edit silently did not land, and
 * both runs came back green, which is indistinguishable from "the harness does
 * not bite". Every record in that file is now produced BY this script, from a
 * run it actually did.
 *
 * THE RULES, each learned from a way of being wrong:
 *
 *  0. The owning test must PASS on the UNMUTATED tree in this same session. A
 *     mutation "caught" by an already-red test is caught by nothing.
 *  1. The run happens in an ISOLATED TREE — `git archive HEAD` into a temp
 *     directory with node_modules symlinked — so nothing is judged against the
 *     working copy, and a crash mid-run cannot strand an inverted condition in
 *     a file that also holds real work.
 *  2. The patch must APPLY: its anchor must occur exactly once, and the file on
 *     disk must actually differ afterwards. This is the check the old records
 *     lacked, and the one that would have caught the silent no-op.
 *  3. The BUNDLE HASH must move, which is what proves the mutation reached the
 *     browser rather than being tree-shaken, shadowed, or folded away by a
 *     build-time define.
 *  4. The build must SUCCEED. A patch that does not compile is reported as DOES
 *     NOT BUILD and is never counted as a kill: the suite would otherwise run
 *     against the last good bundle, or fail for a reason that is not the claim.
 *     Fix the patch — `|| true` rather than deleting a used local — and re-run.
 *  5. The owning test must FAIL, and its output must NAME the marker or claim it
 *     covers. A test that fails for an unrelated reason is not evidence about
 *     this verdict.
 *  6. The tree is restored and the hash must return to its baseline value.
 *
 * It writes `observed` back into e2e/verdict-mutations.json itself, recording
 * the sha it ran at, both bundle hashes, the md5 of the patched file before and
 * after, the baseline pass count, and the verbatim failure line. No evidence
 * line in that file may be carried over from a run that did not happen on this
 * tree, so this writer is the only thing that produces them.
 *
 * Usage:  node scripts/mutation.mjs           (all)
 *         node scripts/mutation.mjs M7        (one)
 *         node scripts/mutation.mjs --keep    (leave the isolated tree behind)
 */

import { execFileSync, execSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

const ROOT = new URL('..', import.meta.url).pathname.replace(/\/$/, '')
const LEDGER = join(ROOT, 'e2e', 'verdict-mutations.json')

const argv = process.argv.slice(2)
const keep = argv.includes('--keep')
const only = argv.find((a) => !a.startsWith('--'))

const doc = JSON.parse(readFileSync(LEDGER, 'utf8'))
const entries = []
for (const group of ['markers', 'claims']) {
  for (const [name, entry] of Object.entries(doc[group])) {
    for (const m of entry.mutations) entries.push({ ...m, group, name, ref: m })
  }
}
const selected = entries.filter((e) => !only || e.id === only)
if (!selected.length) {
  console.error(`No mutation matches "${only}". Ids: ${entries.map((e) => e.id).join(', ')}`)
  process.exit(2)
}

const git = (...a) => execFileSync('git', ['-C', ROOT, ...a], { encoding: 'utf8' }).trim()

// Rule 1's precondition: the archive is of HEAD, so uncommitted work would be
// invisible to the run and every record would describe a tree nobody has.
const dirty = git('status', '--porcelain', '--untracked-files=no')
if (dirty && !process.env.MUTATION_ALLOW_DIRTY) {
  console.error('Refusing to run: uncommitted changes to tracked files.\n')
  console.error(dirty)
  console.error('\n`git archive HEAD` would not contain them, so every record this run wrote')
  console.error('would describe a tree that does not exist. Commit first.')
  console.error('MUTATION_ALLOW_DIRTY=1 overrides, knowing that.')
  process.exit(2)
}
const sha = git('rev-parse', 'HEAD')
const shortSha = sha.slice(0, 7)

const TREE = mkdtempSync(join(tmpdir(), 'pp-mutation-'))
console.log(`isolated tree: ${TREE}`)
console.log(`archived from: ${shortSha}\n`)
execSync(`git -C ${ROOT} archive HEAD | tar -x -C ${TREE}`, { stdio: 'pipe' })
symlinkSync(join(ROOT, 'node_modules'), join(TREE, 'node_modules'))

// CI=1 on purpose: it flips playwright.config.ts's `reuseExistingServer` to
// false, so a mutated bundle can never be judged by a server that an earlier and
// UNMUTATED run left listening — which reports a real kill as a survivor.
const sh = (cmd) =>
  execSync(cmd, {
    cwd: TREE,
    stdio: 'pipe',
    encoding: 'utf8',
    env: { ...process.env, CI: '1' },
    maxBuffer: 64 * 1024 * 1024,
  })

const DIST = join(TREE, 'dist', 'assets')
function bundleHash() {
  if (!existsSync(DIST)) return null
  const h = createHash('sha256')
  for (const f of readdirSync(DIST).sort()) h.update(f).update(readFileSync(join(DIST, f)))
  return h.digest('hex').slice(0, 12)
}
const md5 = (rel) => createHash('md5').update(readFileSync(join(TREE, rel))).digest('hex').slice(0, 12)

function build() {
  try {
    sh('npm run build')
    return true
  } catch {
    return false
  }
}

function runOwner(spec, test) {
  const cmd = `npx playwright test ${spec} --project=claims -g ${JSON.stringify(test)}`
  try {
    return { failed: false, output: sh(cmd) }
  } catch (err) {
    return { failed: true, output: `${err.stdout ?? ''}${err.stderr ?? ''}` }
  }
}

function apply(m, forward) {
  const { patch } = m
  const [from, to] = forward ? [patch.from, patch.to] : [patch.to, patch.from]
  const path = join(TREE, patch.file)
  const before = readFileSync(path, 'utf8')
  const count = before.split(from).length - 1
  if (count !== 1) {
    throw new Error(
      `expected exactly one occurrence of the ${forward ? 'anchor' : 'replacement'} in ${patch.file}, found ${count}`,
    )
  }
  const after = before.replace(from, to)
  // Rule 2, and the reason this runner exists: an edit that does not land reads
  // exactly like a harness that does not bite.
  if (after === before) throw new Error('the patch produced an identical file: it did not apply')
  writeFileSync(path, after)
}

const strip = (s) => s.replace(/\x1b\[[0-9;]*m/g, '')

/** The failure line that names the covered id, or the first assertion line. */
function failureLine(output, needle) {
  const lines = strip(output).split('\n').map((l) => l.trimEnd())
  const at = lines.findIndex((l) => l.includes(needle))
  if (at >= 0) return lines[at].trim().slice(0, 260)
  const err = lines.findIndex((l) => /Error:|expect\(/.test(l))
  return (err >= 0 ? lines[err] : lines.slice(-3).join(' ')).trim().slice(0, 260)
}
const passCount = (output) => (strip(output).match(/(\d+)\s+passed/) || [])[1] ?? '?'

/* Validate every selected patch BEFORE touching anything.
 *
 * The first run of this runner lost twelve of twenty results to one bad patch:
 * a replacement of `''`, which applied fine and then matched 24,385 times on the
 * way back. The restore threw, the file stayed mutated, and every mutation after
 * it was judged against a poisoned tree — reported as NOT RESTORED and FAILED
 * FOR THE WRONG REASON, which are both true and neither of which is about the
 * mutation they were filed under. A ledger is checked in one pass now, and the
 * run refuses to start if any entry cannot make the round trip. */
const invalid = []
for (const m of selected) {
  const path = join(TREE, m.patch.file)
  const text = readFileSync(path, 'utf8')
  const anchors = text.split(m.patch.from).length - 1
  if (anchors !== 1) { invalid.push(`${m.id}: anchor occurs ${anchors} times in ${m.patch.file}, expected 1`); continue }
  const after = text.replace(m.patch.from, m.patch.to)
  if (after === text) { invalid.push(`${m.id}: the patch is a no-op — it would not change ${m.patch.file}`); continue }
  const back = after.split(m.patch.to).length - 1
  if (back !== 1) invalid.push(`${m.id}: the replacement occurs ${back} times after applying, so it cannot be reversed`)
}
if (invalid.length) {
  console.error('Refusing to run: these patches cannot make the round trip.\n')
  for (const line of invalid) console.error(`  ${line}`)
  console.error('\nEvery entry is checked before ANY is applied, because one unreversible patch')
  console.error('strands a mutated file and turns every later result into a verdict about that,')
  console.error('not about the mutation it is filed under.')
  if (!keep) rmSync(TREE, { recursive: true, force: true })
  process.exit(2)
}
console.log(`${selected.length} patches make the round trip.\n`)

console.log('building the baseline in the isolated tree...')
if (!build()) {
  console.error('The baseline build fails in the isolated tree. Nothing below would mean anything.')
  if (!keep) rmSync(TREE, { recursive: true, force: true })
  process.exit(2)
}
const baselineHash = bundleHash()
console.log(`baseline bundle ${baselineHash}\n`)

// Baselines are cached per owning test: the tree is unmutated at that moment, so
// two mutations sharing a test share one honest baseline.
const baselines = new Map()
function baselineFor(spec, test) {
  const key = `${spec}::${test}`
  if (!baselines.has(key)) baselines.set(key, runOwner(spec, test))
  return baselines.get(key)
}

const results = []
for (const m of selected) {
  process.stdout.write(`${m.id.padEnd(5)} ${m.name.padEnd(17)} `)
  let applied = false
  try {
    const base = baselineFor(m.killedBy.spec, m.killedBy.test)
    const beforeMd5 = md5(m.patch.file)
    apply(m, true)
    applied = true
    const afterMd5 = md5(m.patch.file)
    const built = build()
    const mutatedHash = built ? bundleHash() : null
    const owner = built ? runOwner(m.killedBy.spec, m.killedBy.test) : { failed: false, output: '' }
    apply(m, false)
    applied = false
    build()
    const restoredHash = bundleHash()
    /* A tree that did not come back is not a tree anything else can be judged in.
       Stop here rather than report eleven more verdicts about the wrong file. */
    if (md5(m.patch.file) !== beforeMd5) {
      console.log('NOT RESTORED')
      console.error(`\n${m.id}: ${m.patch.file} did not return to md5 ${beforeMd5}. Aborting: every`)
      console.error('later result would be a verdict about this file, not about its own mutation.')
      if (!keep) rmSync(TREE, { recursive: true, force: true })
      process.exit(2)
    }

    const covered = m.name
    const verdict = base.failed
      ? 'BASELINE ALREADY RED'
      : !built
        ? 'DOES NOT BUILD'
        : mutatedHash === baselineHash
          ? 'BUNDLE UNCHANGED'
          : !owner.failed
            ? 'SURVIVED'
            : !strip(owner.output).includes(covered)
              ? 'FAILED FOR THE WRONG REASON'
              : restoredHash !== baselineHash
                ? 'NOT RESTORED'
                : 'KILLED'

    m.ref.observed = [
      `re-derived ${new Date().toISOString().slice(0, 10)} by scripts/mutation.mjs at ${shortSha},`,
      'in an isolated `git archive HEAD` tree with node_modules symlinked and CI=1,',
      'so Playwright built and served the mutated bundle itself.',
      `Baseline (unmutated, same session): ${base.failed ? 'FAILED' : `${passCount(base.output)} passed`}.`,
      `${m.patch.file} md5 ${beforeMd5} -> ${afterMd5};`,
      `bundle ${baselineHash} -> ${mutatedHash ?? 'no build'} -> ${restoredHash}.`,
      verdict === 'KILLED'
        ? `Mutated run FAILED naming "${covered}": ${failureLine(owner.output, covered)}`
        : `VERDICT ${verdict}: ${failureLine(owner.output, covered)}`,
    ].join(' ')

    results.push({ id: m.id, verdict })
    console.log(
      verdict === 'KILLED'
        ? `KILLED    ${baselineHash} -> ${mutatedHash} -> ${restoredHash}   baseline ${passCount(base.output)} passed`
        : verdict,
    )
  } catch (err) {
    if (applied) {
      try {
        apply(m, false)
        build()
      } catch (restoreErr) {
        console.log(`ERROR  ${err.message}`)
        console.error(`\n${m.id}: could not restore ${m.patch.file} (${restoreErr.message}). Aborting:`)
        console.error('a mutated file left in place makes every later verdict a statement about it.')
        if (!keep) rmSync(TREE, { recursive: true, force: true })
        process.exit(2)
      }
    }
    results.push({ id: m.id, verdict: `ERROR: ${err.message}` })
    console.log(`ERROR  ${err.message}`)
  }
}

writeFileSync(LEDGER, `${JSON.stringify(doc, null, 2)}\n`)
const bad = results.filter((r) => r.verdict !== 'KILLED')
console.log(`\n${results.length - bad.length}/${results.length} mutations were killed by the test that owns them.`)
if (bad.length) {
  console.log('\nNot killed:')
  for (const r of bad) console.log(`  ${r.id}: ${r.verdict}`)
  console.log('\nDOES NOT BUILD is a broken PATCH, not a surviving mutation: fix the patch and re-run.')
  console.log('SURVIVED is evidence about the SOURCE or the test, and is the one worth stopping for.')
}
if (keep) console.log(`\nisolated tree kept at ${TREE}`)
else rmSync(TREE, { recursive: true, force: true })
process.exit(bad.length ? 1 : 0)

#!/usr/bin/env node
/**
 * Replays every record in e2e/verdict-mutations.ts and JUDGES it against the four
 * rules a kill has to clear. Nothing below is typed by a person: every verdict is
 * produced by the run that earned it.
 *
 *   node scripts/mutation.mjs list
 *   node scripts/mutation.mjs verify           # all twelve
 *   node scripts/mutation.mjs verify 0 3 7     # by index
 *
 * WHAT CHANGED IN THE LEDGER TO MAKE THIS POSSIBLE
 *
 * Every record described its edit as PROSE -- "src/ppe/control.ts
 * randomizedEncrypt(): replace `crypto.getRandomValues(new Uint8Array(12))` with
 * `new Uint8Array(12)`" -- which a person can redo and a script cannot. Each now
 * also carries `edits`: one or more { file, find, replace } steps, applied in order
 * and reversed last-first.
 *
 * It is a LIST rather than a single patch because two records genuinely need more
 * than one edit, and collapsing them would have meant encoding less than the record
 * describes:
 *
 *   [1] replaces the control branch's interpolated aggregate in BOTH query() and
 *       recover(). Doing only one leaves the other half of the claim measured, and
 *       the record is about the pair.
 *   [7] renders the bar INDEX instead of the value name, and the index does not
 *       exist until the map callback takes it -- so the signature changes first and
 *       the template second.
 *
 * The prose stays, because it carries what the edits cannot: which function the edit
 * sits in, and why that edit rather than another. [4] is the clearest case -- it
 * moves a verdict's STATE while leaving its words untouched, and its prose records
 * that this is the exact defect Fix 1 describes, the page going on saying the right
 * sentence while claiming the opposite in every other way a reader can see. No
 * find/replace pair says that.
 *
 * THE FOUR RULES, each enforced rather than assumed:
 *
 *   1. The owning test PASSED UNMUTATED in this same run, checked per record from
 *      `killedByTest`. A baseline green overall can still be green because the one
 *      test that matters never ran.
 *   2. Every edit CHANGED ITS FILE, and every file returns to its original md5.
 *      The whole sequence is checked for every selected record BEFORE any is
 *      applied -- forward and then in reverse, which is the only way to know a
 *      multi-edit record can be undone -- and the md5s are re-checked after each
 *      record. A restore that does not land aborts the run: every verdict after it
 *      would describe the file that stayed mutated rather than its own mutation.
 *   3. The run served the MUTATED CODE, proved two ways because one is not enough:
 *      the built bundle's hash must MOVE, and the failure must not match a shape
 *      meaning the code never ran at all. CI=1 turns off reuseExistingServer and
 *      the preview server is --strictPort on 4201.
 *   4. A patch that DOES NOT COMPILE is DOES NOT BUILD, never a kill. The build runs
 *      explicitly before the gate, so that answer arrives directly rather than as a
 *      webServer timeout.
 *
 * WHY THE GATE RUNS AS A PROJECT, NEVER -g
 *
 * playwright.config.ts gives `verdict-coverage` a `dependencies: ['claims']`, and
 * e2e/verdict-coverage.spec.ts fails the run when a recorded kill's (test title,
 * marker) pair was never executed. So the gate is `--project=verdict-coverage`, and
 * a single-test run cannot exit 0 here: the named test passes and the coverage check
 * fails on the other eleven.
 *
 * When a mutation does kill its owning test, the `claims` project goes red and the
 * dependent `verdict-coverage` project is SKIPPED. That is expected, and it is why
 * the verdict below is read from the OWNING TEST's own result in the JSON report
 * rather than from the suite's exit code.
 *
 * `killedByTest` names a test TITLE and not a file, so the title is looked up across
 * every spec the run reported, and a title matching two specs is refused as an
 * ambiguous record rather than guessed at.
 *
 * ON IMPORTING THE LEDGER. The records are a TypeScript module, so this script
 * imports it directly and relies on Node's type stripping (23.6+, verified on 26.9).
 * Moving them to JSON was the alternative and was not taken: e2e/verdict-coverage.spec.ts
 * imports this module, so the records would have had to be duplicated or that spec
 * rewritten to make a script's life easier. A failed import is reported as a failed
 * import, never as zero records.
 *
 * Results are NOT written back into the ledger. verdict-coverage.spec.ts already
 * fails the run when a recorded kill did not execute, so an archived `observed`
 * string would be a second copy of an enforced answer -- the choice
 * crypto-lab-hidden-bit and crypto-lab-pqxdh-wire both made, and §4.1c calls
 * writing back optional and enforcement the requirement.
 *
 * The `baseline` and `killedBy` fields each record carries ARE typed observations,
 * pasted from the session that first ran them -- and this lab's are unusually good,
 * naming the bundle hash before and after. They are left alone: they are historical
 * evidence, this script now supersedes them as the live answer, and deleting another
 * author's recorded evidence is a maintainer's call rather than a side effect of
 * adding a runner.
 */
import { createHash } from 'node:crypto'
import { execFileSync, execSync, spawnSync } from 'node:child_process'
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = fileURLToPath(new URL('../', import.meta.url)).replace(/\/$/, '')
const GATE = ['--project=verdict-coverage']

let LEDGER
try {
  LEDGER = await import(join(ROOT, 'e2e/verdict-mutations.ts'))
} catch (error) {
  console.error('Could not import e2e/verdict-mutations.ts, so there are no records to judge.')
  console.error(`  ${error.message.split('\n')[0]}`)
  console.error('\nThis script imports the TypeScript ledger directly and needs Node 23.6+ for')
  console.error(`type stripping. This is ${process.version}.`)
  process.exit(2)
}

const RECORDS = LEDGER.MARKER_MUTATIONS.map((record, index) => ({ index, id: String(index), ...record }))

const [, , command, ...only] = process.argv

if (command === 'list') {
  for (const record of RECORDS) {
    console.log(`[${record.id}] ${record.marker}  (${record.kind})`)
    console.log(`  edits     ${record.edits ? record.edits.map((e) => `${e.file}: ${e.find.split('\n')[0].trim().slice(0, 70)}`).join('\n            ') : 'NOT ENCODED'}`)
    console.log(`  killed by ${record.killedByTest}\n`)
  }
  process.exit(0)
}

if (command !== 'verify') {
  console.error('usage: mutation.mjs list | verify [index...]')
  process.exit(1)
}

const selected = only.length === 0 ? RECORDS : RECORDS.filter((record) => only.includes(record.id) || only.includes(record.marker))
if (only.length > 0 && selected.length === 0) {
  console.error(`nothing selected by: ${only.join(', ')}`)
  process.exit(1)
}
const unencoded = selected.filter((record) => !record.edits || record.edits.length === 0)
if (unencoded.length > 0) {
  console.error('Refusing to run: these records have only prose, no `edits`.\n')
  for (const record of unencoded) console.error(`  [${record.id}] ${record.mutation}`)
  console.error('\nA sentence describing an edit cannot be replayed. Encode it as file/find/replace.')
  process.exit(2)
}

const git = (...args) => execFileSync('git', ['-C', ROOT, ...args], { encoding: 'utf8' }).trim()

/* The archive below is taken from HEAD, so uncommitted work would be absent from
   the tree every verdict describes. Commit first. */
const dirty = git('status', '--porcelain', '--untracked-files=no')
if (dirty && !process.env.MUTATION_ALLOW_DIRTY) {
  console.error('Refusing to run: uncommitted changes to tracked files.\n')
  console.error(dirty)
  console.error('\nThe isolated tree is archived from HEAD and would not contain them.')
  console.error('Commit first. MUTATION_ALLOW_DIRTY=1 overrides, knowing that.')
  process.exit(2)
}

const sha = git('rev-parse', 'HEAD').slice(0, 7)
const TREE = mkdtempSync(join(tmpdir(), 'order-leak-mutation-'))
const SCRATCH = mkdtempSync(join(tmpdir(), 'order-leak-reports-'))
execSync(`git -C ${ROOT} archive HEAD | tar -x -C ${TREE}`, { stdio: 'pipe' })
symlinkSync(join(ROOT, 'node_modules'), join(TREE, 'node_modules'))
console.log(`isolated tree: ${TREE}`)
console.log(`archived from: ${sha}`)

const digest = (rel) => createHash('md5').update(readFileSync(join(TREE, rel))).digest('hex').slice(0, 12)

/** Apply one record's edits in order, or reverse them last-first. */
function apply(record, direction) {
  const steps = direction === 'apply' ? record.edits : [...record.edits].reverse()
  for (const step of steps) {
    const path = join(TREE, step.file)
    const source = readFileSync(path, 'utf8')
    const [from, to] = direction === 'apply' ? [step.find, step.replace] : [step.replace, step.find]
    const occurrences = source.split(from).length - 1
    if (occurrences !== 1) {
      throw new Error(`${step.file}: ${direction} [${record.id}] expected exactly one occurrence, found ${occurrences}`)
    }
    const next = source.replace(from, to)
    if (next === source) throw new Error(`${step.file}: ${direction} [${record.id}] produced an identical file`)
    writeFileSync(path, next)
  }
}

/* Rule 2, for every selected record, BEFORE any is applied, read from the TREE the
   edits are applied to rather than from the working copy. The sequence is run
   forward AND back: for a multi-edit record that is the only way to know it can be
   undone, and a record that cannot be undone poisons every verdict after it. */
function preflight() {
  const broken = []
  for (const record of selected) {
    const files = [...new Set(record.edits.map((e) => e.file))]
    const before = new Map(files.map((f) => [f, digest(f)]))
    try {
      apply(record, 'apply')
      apply(record, 'restore')
      for (const [f, md5] of before) {
        if (digest(f) !== md5) broken.push(`[${record.id}] ${record.marker}: ${f} did not return to ${md5} after a dry round trip`)
      }
    } catch (error) {
      broken.push(`[${record.id}] ${record.marker}: ${error.message}`)
      // leave nothing behind for the next record to trip over
      for (const [f, md5] of before) {
        if (digest(f) !== md5) broken.push(`[${record.id}] ${record.marker}: ${f} LEFT MUTATED by the dry run`)
      }
    }
  }
  if (broken.length > 0) {
    console.error('\nRefusing to run: these records cannot make the round trip.\n')
    for (const line of broken) console.error(`  ${line}`)
    rmSync(TREE, { recursive: true, force: true })
    rmSync(SCRATCH, { recursive: true, force: true })
    process.exit(2)
  }
}
preflight()
console.log(`${selected.length} record(s) make the round trip, ${selected.reduce((n, r) => n + r.edits.length, 0)} edits in total\n`)

const DIST = join(TREE, 'dist', 'assets')
function bundleHash() {
  if (!existsSync(DIST)) return null
  const h = createHash('sha256')
  for (const file of readdirSync(DIST).sort()) h.update(file).update(readFileSync(join(DIST, file)))
  return h.digest('hex').slice(0, 12)
}

/** Rule 4. Keeps the output so the reason is reportable. */
function build() {
  const result = spawnSync('npm', ['run', 'build'], {
    cwd: TREE,
    env: { ...process.env, CI: '1' },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  })
  return { ok: result.status === 0, output: `${result.stdout ?? ''}${result.stderr ?? ''}` }
}

const ESC = String.fromCharCode(27)
const strip = (text) => text.split(new RegExp(`${ESC}\\[[0-9;]*m`, 'g')).join('')

/* Rule 3's second half: red for one of these means the code never ran, so the red is
   about the harness and not about the verdict. */
const NOT_A_KILL = [
  { pattern: /error TS\d+|Build failed|Transform failed|Could not resolve/i, label: 'build error' },
  { pattern: /webServer.*did not start|Timed out waiting .* from config\.webServer/i, label: 'server never started' },
  { pattern: /net::ERR_CONNECTION_REFUSED/i, label: 'nothing served on the port' },
  { pattern: /is already (?:used|in use)|EADDRINUSE/i, label: 'port already held' },
]
const notAKill = (output) => NOT_A_KILL.find(({ pattern }) => pattern.test(strip(output)))?.label ?? null

function runGate(label) {
  const report = join(SCRATCH, `${label}.json`)
  const result = spawnSync('npx', ['playwright', 'test', ...GATE, '--reporter=json', '--retries=0'], {
    cwd: TREE,
    env: { ...process.env, CI: '1', PLAYWRIGHT_JSON_OUTPUT_NAME: report },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  })
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`
  let parsed
  try {
    parsed = JSON.parse(readFileSync(report, 'utf8'))
  } catch {
    return { specs: null, exitCode: result.status, output }
  }
  const specs = []
  const walk = (suite) => {
    for (const spec of suite.specs ?? []) specs.push(spec)
    for (const child of suite.suites ?? []) walk(child)
  }
  for (const suite of parsed.suites ?? []) walk(suite)
  return { specs, exitCode: result.status, output }
}

/** The record's own test, by TITLE. An ambiguous title is refused, not resolved. */
function outcome(specs, record) {
  const matches = specs?.filter((spec) => spec.title === record.killedByTest) ?? []
  if (matches.length === 0) return { found: false, ok: false, detail: `no test titled "${record.killedByTest}" ran` }
  if (matches.length > 1) {
    return { found: false, ok: false, detail: `"${record.killedByTest}" matched ${matches.length} specs (${matches.map((s) => s.file).join(', ')}); the record is ambiguous` }
  }
  const spec = matches[0]
  const statuses = spec.tests.flatMap((test) => test.results.map((result) => result.status))
  return { found: true, ok: spec.ok === true, detail: statuses.join(', ') }
}

function abort(message) {
  console.error(`\n${message}`)
  rmSync(TREE, { recursive: true, force: true })
  rmSync(SCRATCH, { recursive: true, force: true })
  process.exit(2)
}

console.log('building the baseline in the isolated tree...')
const baselineBuild = build()
if (!baselineBuild.ok) {
  abort(`The baseline does not build in the isolated tree. Nothing below would mean anything.\n\n${strip(baselineBuild.output).split('\n').slice(-20).join('\n')}`)
}
const baselineHash = bundleHash()
console.log(`baseline bundle ${baselineHash}`)

console.log('running the gate unmutated (--project=verdict-coverage, which pulls claims first)...')
const baseline = runGate('baseline')
const notGreen = selected.filter((record) => !outcome(baseline.specs, record).ok)
if (baseline.exitCode !== 0 || notGreen.length > 0) {
  for (const record of notGreen) console.error(`  [${record.id}] ${record.marker}: ${outcome(baseline.specs, record).detail}`)
  abort(`The unmutated gate is not green (exit ${baseline.exitCode}); a kill read against it would prove nothing.\n\n${strip(baseline.output).split('\n').slice(-25).join('\n')}`)
}
console.log(`baseline green, ${baseline.specs.length} specs\n`)

const results = []
for (const [position, record] of selected.entries()) {
  const label = `${String(position + 1).padStart(2)}/${selected.length}`
  const files = [...new Set(record.edits.map((e) => e.file))]
  const before = new Map(files.map((f) => [f, digest(f)]))
  let verdict
  let detail = ''
  let hashes = ''
  try {
    apply(record, 'apply')
    const built = build()
    if (!built.ok) {
      verdict = 'DOES NOT BUILD'
      detail = (strip(built.output).match(/error TS\d+[^\n]*/) ?? [''])[0]
    } else {
      const mutatedHash = bundleHash()
      if (mutatedHash === baselineHash) {
        verdict = 'BUNDLE UNCHANGED'
      } else {
        const mutated = runGate(record.id)
        const shape = notAKill(mutated.output)
        const result = outcome(mutated.specs, record)
        verdict = shape
          ? `NOT A KILL (${shape})`
          : !result.found
            ? `NOT A KILL (${result.detail})`
            : result.ok
              ? 'SURVIVED'
              : 'KILLED'
        detail = result.detail
        hashes = `${baselineHash} -> ${mutatedHash}`
      }
    }
  } finally {
    apply(record, 'restore')
  }
  const rebuilt = build()
  const restoredHash = rebuilt.ok ? bundleHash() : null
  for (const [f, md5] of before) {
    if (digest(f) !== md5) {
      abort(`[${record.id}] ${record.marker}: ${f} did not return to md5 ${md5}. Aborting: every verdict after this one would describe that file rather than its own mutation.`)
    }
  }
  if (rebuilt.ok && restoredHash !== baselineHash) {
    abort(`[${record.id}] ${record.marker}: the bundle did not return to ${baselineHash} after restoring. Aborting for the same reason.`)
  }
  results.push({ record, verdict, detail })
  console.log(`${label}  ${verdict.padEnd(18)} [${record.id}] ${record.marker.padEnd(16)} ${hashes ? `${hashes} -> ${restoredHash}` : detail}`)
}

rmSync(TREE, { recursive: true, force: true })
rmSync(SCRATCH, { recursive: true, force: true })

const killed = results.filter((r) => r.verdict === 'KILLED')
const survived = results.filter((r) => r.verdict === 'SURVIVED')
const broken = results.filter((r) => r.verdict !== 'KILLED' && r.verdict !== 'SURVIVED')
console.log(`\n${killed.length}/${results.length} killed, ${survived.length} survived, ${broken.length} neither`)
for (const { record, detail } of survived) {
  console.log(`  SURVIVED [${record.id}] ${record.marker}: "${record.killedByTest}" stayed green under its own recorded mutation (${detail}). The record is not evidence.`)
}
for (const { record, verdict, detail } of broken) {
  console.log(`  ${verdict} [${record.id}] ${record.marker}${detail ? `: ${detail}` : ''}`)
}
if (broken.length > 0) {
  console.log('\nDOES NOT BUILD is a broken PATCH, not a surviving mutation: fix the patch and re-run.')
  console.log('BUNDLE UNCHANGED means the edit never reached the browser.')
}
process.exit(killed.length === results.length ? 0 : 1)

#!/usr/bin/env node
/**
 * Replays every recorded §4.1c mutation in e2e/verdict-mutations.json and JUDGES it
 * against the four rules a kill has to clear. Nothing below is typed by a person:
 * every verdict is produced by the run that earned it.
 *
 *   node scripts/mutation.mjs list
 *   node scripts/mutation.mjs verify            # all records, both families
 *   node scripts/mutation.mjs verify <marker>   # just these
 *
 * WHAT CHANGED IN THE LEDGER TO MAKE THIS POSSIBLE
 *
 * Each record already carried `mutation` as PROSE — "src/dpf/gen.ts — flip every
 * direction bit: X becomes Y" — which a person can follow and a script cannot. The
 * prose is kept, because several records explain a REJECTED alternative that is
 * worth keeping (key-part-root records that the deeper serializer mutation stops the
 * key round-tripping and takes the whole suite red, which is not a readable kill on
 * that marker). Beside it each record now carries `patch`: the file, an anchor that
 * must occur exactly once, and its replacement. The prose says why; the patch is
 * what runs.
 *
 * THE FOUR RULES, each enforced rather than assumed:
 *
 *   1. The owning test PASSED UNMUTATED in this same run, checked per record. A
 *      baseline green overall can still be green because the one test that matters
 *      never ran.
 *   2. The patch CHANGED THE FILE, and the restore returns the file's original md5.
 *      Both halves are checked for EVERY selected patch before any is applied, and
 *      the md5 is re-checked after each individual mutation. A restore that does not
 *      land aborts the whole run: every verdict after it would describe the file
 *      that stayed mutated rather than its own mutation.
 *   3. The run served the MUTATED CODE, proved two ways because one is not enough:
 *      the built bundle's hash must MOVE, and the failure must not match a shape
 *      meaning the code never ran at all. CI=1 turns off reuseExistingServer and the
 *      preview server is --strictPort, so a listener left by an earlier run on 4698
 *      cannot answer for an unmutated build.
 *   4. A patch that DOES NOT COMPILE is DOES NOT BUILD, never a kill. The build runs
 *      explicitly before the gate, so that answer arrives directly instead of as a
 *      webServer timeout.
 *
 * WHY THE GATE RUNS AS A PROJECT, NEVER -g
 *
 * playwright.config.ts gives `verdict-ledger` a `dependencies: ['claims']`, and
 * e2e/verdict-ledger.spec.ts asserts that every record's (spec, test, status, says)
 * triple appears in the ledger the helpers wrote AS THEY EXECUTED. So the gate is
 * `--project=verdict-ledger`, which pulls claims.spec.ts, flows.spec.ts and
 * verdict-coverage.spec.ts in first. A single-test run cannot exit 0 here: the named
 * test passes and the ledger assertion fails on the other fifteen.
 *
 * When a mutation does kill its owning test, the `claims` project goes red and the
 * dependent `verdict-ledger` project is SKIPPED. That is expected, and it is why the
 * verdict below is read from the OWNING TEST's own result in the JSON report rather
 * than from the suite's exit code.
 *
 * Results are NOT written back into the ledger. verdict-ledger.spec.ts already fails
 * the run when a recorded kill's assertion did not execute, so an archived
 * `observed` string would be a second copy of an enforced answer — the choice
 * crypto-lab-hidden-bit and crypto-lab-pqxdh-wire both made, and §4.1c calls writing
 * back optional and enforcement the requirement.
 */
import { createHash } from 'node:crypto'
import { execFileSync, execSync, spawnSync } from 'node:child_process'
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { basename, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = fileURLToPath(new URL('../', import.meta.url)).replace(/\/$/, '')
const LEDGER = JSON.parse(readFileSync(join(ROOT, 'e2e/verdict-mutations.json'), 'utf8'))
const GATE = ['--project=verdict-ledger']

/** Both families, flattened, so one loop judges markers and claims alike. */
const RECORDS = ['markers', 'claims'].flatMap((family) =>
  Object.entries(LEDGER[family]).map(([marker, record]) => ({ family, marker, ...record })),
)

const [, , command, ...only] = process.argv

if (command === 'list') {
  for (const record of RECORDS) {
    console.log(`${record.marker}  [${record.family}]`)
    console.log(`  renders  ${record.renders}`)
    console.log(`  patch    ${record.patch ? `${record.patch.file}: ${record.patch.find.split('\n')[0].trim()}` : 'NOT ENCODED'}`)
    console.log(`  killed by ${record.assertedBy.spec} :: ${record.assertedBy.test}\n`)
  }
  process.exit(0)
}

if (command !== 'verify') {
  console.error('usage: mutation.mjs list | verify [marker...]')
  process.exit(1)
}

const selected = only.length === 0 ? RECORDS : RECORDS.filter((record) => only.includes(record.marker))
const unknown = only.filter((marker) => !RECORDS.some((record) => record.marker === marker))
if (unknown.length > 0) {
  console.error(`unknown marker(s): ${unknown.join(', ')}`)
  process.exit(1)
}
const unencoded = selected.filter((record) => !record.patch)
if (unencoded.length > 0) {
  console.error('Refusing to run: these records have no `patch`, only prose.\n')
  for (const record of unencoded) console.error(`  ${record.marker}: ${record.mutation}`)
  console.error('\nA sentence describing an edit cannot be replayed. Encode it as file/find/replace.')
  process.exit(2)
}

const git = (...args) => execFileSync('git', ['-C', ROOT, ...args], { encoding: 'utf8' }).trim()

/* The archive below is taken from HEAD, so uncommitted work would be absent from the
   tree every verdict describes. Commit first. */
const dirty = git('status', '--porcelain', '--untracked-files=no')
if (dirty && !process.env.MUTATION_ALLOW_DIRTY) {
  console.error('Refusing to run: uncommitted changes to tracked files.\n')
  console.error(dirty)
  console.error('\nThe isolated tree is archived from HEAD and would not contain them.')
  console.error('Commit first. MUTATION_ALLOW_DIRTY=1 overrides, knowing that.')
  process.exit(2)
}

/* Rule 2, for every selected patch, BEFORE any is applied, and read from the TREE
   the patches are applied to rather than from the working copy. A patch that cannot
   make the round trip is a broken RECORD; discovering that halfway through leaves a
   mutated file behind and poisons every verdict after it. */
function preflight(tree) {
  const broken = []
  for (const record of selected) {
    const { file, find, replace } = record.patch
    const text = readFileSync(join(tree, file), 'utf8')
    const anchors = text.split(find).length - 1
    if (anchors !== 1) {
      broken.push(`${record.marker}: find occurs ${anchors}x in ${file}, expected exactly 1`)
      continue
    }
    const after = text.replace(find, replace)
    if (after === text) {
      broken.push(`${record.marker}: the patch is a no-op, it would not change ${file}`)
    } else if (after.split(replace).length - 1 !== 1) {
      broken.push(`${record.marker}: replace occurs ${after.split(replace).length - 1}x after applying, so it cannot be reverted`)
    }
  }
  if (broken.length > 0) {
    console.error('Refusing to run: these records cannot make the round trip.\n')
    for (const line of broken) console.error(`  ${line}`)
    rmSync(tree, { recursive: true, force: true })
    process.exit(2)
  }
}

const sha = git('rev-parse', 'HEAD').slice(0, 7)
const TREE = mkdtempSync(join(tmpdir(), 'split-point-mutation-'))
const SCRATCH = mkdtempSync(join(tmpdir(), 'split-point-reports-'))
execSync(`git -C ${ROOT} archive HEAD | tar -x -C ${TREE}`, { stdio: 'pipe' })
symlinkSync(join(ROOT, 'node_modules'), join(TREE, 'node_modules'))
console.log(`isolated tree: ${TREE}`)
console.log(`archived from: ${sha}`)
preflight(TREE)
console.log(`${selected.length} record(s) make the round trip\n`)

const digest = (rel) => createHash('md5').update(readFileSync(join(TREE, rel))).digest('hex').slice(0, 12)

const DIST = join(TREE, 'dist', 'assets')
function bundleHash() {
  if (!existsSync(DIST)) return null
  const h = createHash('sha256')
  for (const file of readdirSync(DIST).sort()) h.update(file).update(readFileSync(join(DIST, file)))
  return h.digest('hex').slice(0, 12)
}

/** Rule 4. Keeps the output so the reason is reportable. */
function build() {
  const result = spawnSync('npm', ['run', 'build'], {
    cwd: TREE,
    env: { ...process.env, CI: '1' },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  })
  return { ok: result.status === 0, output: `${result.stdout ?? ''}${result.stderr ?? ''}` }
}

const ESC = String.fromCharCode(27)
const strip = (text) => text.split(new RegExp(`${ESC}\\[[0-9;]*m`, 'g')).join('')

/* Rule 3's second half: red for one of these means the code never ran, so the red is
   about the harness and not about the verdict. */
const NOT_A_KILL = [
  { pattern: /error TS\d+|Build failed|Transform failed|Could not resolve/i, label: 'build error' },
  { pattern: /webServer.*did not start|Timed out waiting .* from config\.webServer/i, label: 'server never started' },
  { pattern: /net::ERR_CONNECTION_REFUSED/i, label: 'nothing served on the port' },
  { pattern: /is already (?:used|in use)|EADDRINUSE/i, label: 'port already held' },
]
const notAKill = (output) => NOT_A_KILL.find(({ pattern }) => pattern.test(strip(output)))?.label ?? null

function runGate(label) {
  const report = join(SCRATCH, `${label}.json`)
  const result = spawnSync('npx', ['playwright', 'test', ...GATE, '--reporter=json', '--retries=0'], {
    cwd: TREE,
    env: { ...process.env, CI: '1', PLAYWRIGHT_JSON_OUTPUT_NAME: report },
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  })
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`
  let parsed
  try {
    parsed = JSON.parse(readFileSync(report, 'utf8'))
  } catch {
    return { specs: null, exitCode: result.status, output }
  }
  const specs = []
  const walk = (suite) => {
    for (const spec of suite.specs ?? []) specs.push(spec)
    for (const child of suite.suites ?? []) walk(child)
  }
  for (const suite of parsed.suites ?? []) walk(suite)
  return { specs, exitCode: result.status, output }
}

/** The record's own test, found by spec file plus exact title from `assertedBy`. */
function outcome(specs, record) {
  const want = { file: basename(record.assertedBy.spec), title: record.assertedBy.test }
  const spec = specs?.find((item) => basename(item.file) === want.file && item.title === want.title)
  if (!spec) return { found: false, ok: false, detail: `${want.file} ran no test called "${want.title}"` }
  const statuses = spec.tests.flatMap((test) => test.results.map((result) => result.status))
  return { found: true, ok: spec.ok === true, detail: statuses.join(', ') }
}

function apply(record, direction) {
  const { file, find, replace } = record.patch
  const path = join(TREE, file)
  const source = readFileSync(path, 'utf8')
  const [from, to] = direction === 'apply' ? [find, replace] : [replace, find]
  const occurrences = source.split(from).length - 1
  if (occurrences !== 1) {
    throw new Error(`${file}: ${direction} ${record.marker} expected exactly one occurrence, found ${occurrences}`)
  }
  const next = source.replace(from, to)
  if (next === source) throw new Error(`${file}: ${direction} ${record.marker} produced an identical file`)
  writeFileSync(path, next)
}

function abort(message) {
  console.error(`\n${message}`)
  rmSync(TREE, { recursive: true, force: true })
  rmSync(SCRATCH, { recursive: true, force: true })
  process.exit(2)
}

console.log('building the baseline in the isolated tree...')
const baselineBuild = build()
if (!baselineBuild.ok) {
  abort(`The baseline does not build in the isolated tree. Nothing below would mean anything.\n\n${strip(baselineBuild.output).split('\n').slice(-20).join('\n')}`)
}
const baselineHash = bundleHash()
console.log(`baseline bundle ${baselineHash}`)

console.log('running the gate unmutated (--project=verdict-ledger, which pulls claims first)...')
const baseline = runGate('baseline')
const notGreen = selected.filter((record) => !outcome(baseline.specs, record).ok)
if (baseline.exitCode !== 0 || notGreen.length > 0) {
  for (const record of notGreen) console.error(`  ${record.marker}: ${outcome(baseline.specs, record).detail}`)
  abort(`The unmutated gate is not green (exit ${baseline.exitCode}); a kill read against it would prove nothing.\n\n${strip(baseline.output).split('\n').slice(-25).join('\n')}`)
}
console.log(`baseline green, ${baseline.specs.length} specs\n`)

const results = []
for (const [index, record] of selected.entries()) {
  const position = `${String(index + 1).padStart(2)}/${selected.length}`
  const before = digest(record.patch.file)
  let verdict
  let detail = ''
  let hashes = ''
  try {
    apply(record, 'apply')
    const built = build()
    if (!built.ok) {
      verdict = 'DOES NOT BUILD'
      detail = (strip(built.output).match(/error TS\d+[^\n]*/) ?? [''])[0]
    } else {
      const mutatedHash = bundleHash()
      if (mutatedHash === baselineHash) {
        verdict = 'BUNDLE UNCHANGED'
      } else {
        const mutated = runGate(record.marker)
        const shape = notAKill(mutated.output)
        const result = outcome(mutated.specs, record)
        verdict = shape
          ? `NOT A KILL (${shape})`
          : !result.found
            ? 'NOT A KILL (its test did not run)'
            : result.ok
              ? 'SURVIVED'
              : 'KILLED'
        detail = result.detail
        hashes = `${baselineHash} -> ${mutatedHash}`
      }
    }
  } finally {
    apply(record, 'restore')
  }
  const rebuilt = build()
  const restoredHash = rebuilt.ok ? bundleHash() : null
  if (digest(record.patch.file) !== before) {
    abort(`${record.marker}: ${record.patch.file} did not return to md5 ${before}. Aborting: every verdict after this one would describe that file rather than its own mutation.`)
  }
  if (rebuilt.ok && restoredHash !== baselineHash) {
    abort(`${record.marker}: the bundle did not return to ${baselineHash} after restoring ${record.patch.file}. Aborting for the same reason.`)
  }
  results.push({ record, verdict, detail })
  console.log(`${position}  ${verdict.padEnd(18)} ${record.marker.padEnd(20)} ${hashes ? `${hashes} -> ${restoredHash}` : detail}`)
}

rmSync(TREE, { recursive: true, force: true })
rmSync(SCRATCH, { recursive: true, force: true })

const killed = results.filter((r) => r.verdict === 'KILLED')
const survived = results.filter((r) => r.verdict === 'SURVIVED')
const broken = results.filter((r) => r.verdict !== 'KILLED' && r.verdict !== 'SURVIVED')
console.log(`\n${killed.length}/${results.length} killed, ${survived.length} survived, ${broken.length} neither`)
for (const { record, detail } of survived) {
  console.log(`  SURVIVED ${record.marker}: "${record.assertedBy.test}" stayed green under its own recorded mutation (${detail}). The record is not evidence.`)
}
for (const { record, verdict, detail } of broken) {
  console.log(`  ${verdict} ${record.marker}${detail ? `: ${detail}` : ''}`)
}
if (broken.length > 0) {
  console.log('\nDOES NOT BUILD is a broken PATCH, not a surviving mutation: fix the patch and re-run.')
  console.log('BUNDLE UNCHANGED means the edit never reached the browser.')
}
process.exit(killed.length === results.length ? 0 : 1)

#!/usr/bin/env node
/**
 * Applies or restores one recorded §4.1c verdict mutation, so a kill is reproducible
 * rather than a claim in a commit body.
 *
 *   node tools/verdict-mutation.mjs list
 *   node tools/verdict-mutation.mjs apply <marker>
 *   node tools/verdict-mutation.mjs restore <marker>
 *
 * A mutation counts as a kill only when the unmutated baseline passed in the same run,
 * the failure is that verdict's own assertion, and the server served the mutated code
 * (CI=1, which turns off reuseExistingServer).
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const root = new URL('../', import.meta.url)
const registry = JSON.parse(readFileSync(new URL('e2e/verdict-mutations.json', root), 'utf8'))

const [, , command, marker] = process.argv

function fail(message) {
  console.error(message)
  process.exit(1)
}

if (command === 'list') {
  for (const entry of registry) console.log(`${entry.marker}\t${entry.file}\t${entry.kills}`)
  process.exit(0)
}

if (command !== 'apply' && command !== 'restore') {
  fail('usage: verdict-mutation.mjs list | apply <marker> | restore <marker>')
}

const entry = registry.find((item) => item.marker === marker)
if (!entry) fail(`unknown marker: ${marker}`)

const path = fileURLToPath(new URL(entry.file, root))
const source = readFileSync(path, 'utf8')
const from = command === 'apply' ? entry.find : entry.replace
const to = command === 'apply' ? entry.replace : entry.find

const occurrences = source.split(from).length - 1
if (occurrences !== 1) {
  fail(`${entry.file}: expected exactly one occurrence of the ${command === 'apply' ? 'original' : 'mutated'} text for ${marker}, found ${occurrences}`)
}

writeFileSync(path, source.replace(from, to))
console.log(`${command} ${marker} -> ${entry.file}`)

#!/usr/bin/env node
/**
 * Replays every record in e2e/verdict-mutations.ts and JUDGES it against the four
 * rules a kill has to clear. Nothing below is typed by a person: every verdict is
 * produced by the run that earned it.
 *
 *   node scripts/mutation.mjs list
 *   node scripts/mutation.mjs verify            # all 41, both families
 *   node scripts/mutation.mjs verify <marker>   # just these
 *
 * WHAT CHANGED IN THE LEDGER TO MAKE THIS POSSIBLE
 *
 * Every record already described its edit as PROSE -- "template(): `const plain =
 * { ...result.folded, E: [0n, 0n] }` -> `const plain = { ...result.folded }`" --
 * which a person can redo and a script cannot. Each now also carries `patch`: the
 * file, an anchor that must occur exactly once, and its replacement.
 *
 * The prose stays, and not out of sentiment. It carries two things the patch does
 * not: WHICH FUNCTION the edit sits in (`template()`, `foldPublic()`,
 * `CountingPoint.multiply()`), which is how a reader finds it again when the line
 * moves; and WHY that edit and not another -- `chain-total-ops` records that it is
 * the only mutation in either set that can tell a summed total from a multiplied
 * one, because every other one moves all folds at once. A patch cannot hold that.
 *
 * Eight of the 41 could not be read straight out of the prose, because the prose
 * elided the part that does not matter to a person and does matter to a string
 * match: `JSON.stringify(A, …)`, `valid: constraintValid && ...`,
 * `verifierGroupOps(…)`. Those were expanded from the source, and the expansion is
 * recorded in the patch rather than left for the next reader to redo.
 *
 * THE FOUR RULES, each enforced rather than assumed:
 *
 *   1. The owning test PASSED UNMUTATED in this same run, checked per record from
 *      `killedBy`. A baseline green overall can still be green because the one test
 *      that matters never ran.
 *   2. The patch CHANGED THE FILE, and the file returns to its original md5. Both
 *      halves are checked for EVERY selected patch before any is applied, and the
 *      md5 is re-checked after each individual mutation. A restore that does not
 *      land aborts the whole run: every verdict after it would describe the file
 *      that stayed mutated rather than its own mutation.
 *   3. The run served the MUTATED CODE, proved two ways because one is not enough:
 *      the built bundle's hash must MOVE, and the failure must not match a shape
 *      meaning the code never ran at all. CI=1 turns off reuseExistingServer and
 *      the preview server is --strictPort on 4695, so a listener left by an earlier
 *      run cannot answer for an unmutated build.
 *   4. A patch that DOES NOT COMPILE is DOES NOT BUILD, never a kill. The build runs
 *      explicitly before the gate, so that answer arrives directly rather than as a
 *      webServer timeout.
 *
 * WHY THE GATE RUNS AS A PROJECT, NEVER -g
 *
 * playwright.config.ts gives `verdict-replay` a `dependencies: ['lab']`, and
 * e2e/coverage-replay.spec.ts fails the run when a recorded kill's assertion did
 * not ACTUALLY RUN -- the helpers write down the (test title, marker) pairs they
 * execute and that project reads them back once the suite is over. So the gate is
 * `--project=verdict-replay`, and a single-test run cannot exit 0 here: the named
 * test passes and the replay fails on the other forty.
 *
 * When a mutation does kill its owning test, the `lab` project goes red and the
 * dependent `verdict-replay` project is SKIPPED. That is expected, and it is why
 * the verdict below is read from the OWNING TEST's own result in the JSON report
 * rather than from the suite's exit code.
 *
 * `killedBy` names a test TITLE and not a file, so the title is looked up across
 * every spec the run reported. A title matching two specs is refused rather than
 * guessed at: that is an ambiguous record, not a kill.
 *
 * ON IMPORTING THE LEDGER. The records are a TypeScript module, so this script
 * imports it directly and relies on Node's type stripping (Node 23.6+; verified on
 * 26.9). Moving them to JSON was the alternative and was not taken: four files
 * import this module -- including src/ui/app.ts, which renders from it -- so the
 * records would have had to be duplicated or every importer rewritten, to make a
 * script's life easier. A failed import is reported as a failed import.
 *
 * Results are NOT written back into the ledger. coverage-replay.spec.ts already
 * fails the run when a recorded kill did not execute, so an archived `observed`
 * string would be a second copy of an enforced answer -- the choice
 * crypto-lab-hidden-bit and crypto-lab-pqxdh-wire both made, and §4.1c calls
 * writing back optional and enforcement the requirement.
 *
 * The `baseline` and `failure` fields each record carries ARE typed observations,
 * pasted reporter lines from the session that first ran them. They are left alone
 * here: they are historical evidence, this script now supersedes them as the live
 * answer, and deleting another author's recorded evidence is a maintainer's call
 * rather than a side effect of adding a runner.
 */
