const mutations = [
  {
    name: 'identity domain separation silently changes',
    file: 'src/hash.ts',
    from: "export const IDENTITY_DOMAIN = 'CRYPTO-LAB-LATTICE-IBE-GPV-ID-v1';",
    to: "export const IDENTITY_DOMAIN = 'CRYPTO-LAB-LATTICE-IBE-GPV-ID-v2';",
